(8, 2, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá văn hóa và cà phê Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Bắt đầu ngày mới tại trung tâm Buôn Ma Thuột bằng việc khám phá văn hóa cà phê. Tham quan Bảo tàng Cà phê và thưởng thức một ly cà phê đậm đà tại một quán địa phương.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng taxi/xe máy trong trung tâm thành phố.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người (bao gồm vé tham quan bảo tàng và cà phê).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực đặc sản Tây Nguyên tại nhà hàng địa phương, thử các món như gà nướng Bản Đôn, cơm lam, lẩu lá rừng.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc taxi/xe máy.\",\n          \"price\": \"150.000 - 300.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê cổ truyền đẹp nhất Buôn Ma Thuột. Tìm hiểu về kiến trúc nhà dài truyền thống và văn hóa bản địa.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua sắm quà lưu niệm).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Dạo chợ đêm Buôn Ma Thuột, thưởng thức các món ăn vặt đường phố và mua sắm đặc sản địa phương.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc taxi/xe máy.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người (chi phí ăn uống, mua sắm).\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khởi hành đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Tại đây, bạn có thể trải nghiệm đi thuyền độc mộc trên hồ, tìm hiểu về văn hóa M\'nông và ngắm cảnh thiên nhiên hùng vĩ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~50km) theo quốc lộ 27 từ Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 250.000 VNĐ/người (bao gồm vé tham quan, chi phí thuyền).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại một nhà hàng địa phương gần Hồ Lắk, thưởng thức các món ăn dân dã của đồng bào M\'nông.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy trong khu vực Hồ Lắk.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan buôn làng quanh Hồ Lắk, tìm hiểu thêm về đời sống và phong tục của người M\'nông. Mua sắm các sản phẩm thủ công mỹ nghệ làm quà lưu niệm.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy quanh khu vực Hồ Lắk.\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua sắm).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Trở về Buôn Ma Thuột. Thưởng thức bữa tối chia tay tại một nhà hàng với các món ăn đặc trưng của Đắk Lắk.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~50km) về Buôn Ma Thuột.\",\n          \"price\": \"150.000 - 300.000 VNĐ/người.\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-06 09:07:20'),
