(10, 2, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Buôn Ma Thuột và Thưởng thức Cà phê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê lâu đời và đẹp nhất tại Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa địa phương.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy khoảng 15 phút (~5km) từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua quà lưu niệm hoặc đồ uống).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức các món đặc sản địa phương tại một nhà hàng gần trung tâm Buôn Ma Thuột. Gợi ý: Bún đỏ, phở khô, hoặc lẩu rau rừng.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.\",\n          \"price\": \"Khoảng 80.000 - 150.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm văn hóa Cà phê Buôn Ma Thuột. Tham quan bảo tàng cà phê hoặc một quán cà phê vườn nổi tiếng để thưởng thức hương vị cà phê Ban Mê chính hiệu.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.\",\n          \"price\": \"Miễn phí vé vào cửa bảo tàng, chi phí đồ uống khoảng 50.000 - 100.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Dạo chợ đêm Buôn Ma Thuột, khám phá ẩm thực đường phố và mua sắm đặc sản địa phương.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng taxi/xe máy nếu ở xa chợ đêm.\",\n          \"price\": \"Khoảng 100.000 - 200.000 VNĐ/người tùy vào lựa chọn ăn uống và mua sắm.\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá Hồ Lắk và Văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Trải nghiệm đi thuyền độc mộc trên hồ, tìm hiểu văn hóa của người M\'nông bản địa.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi đi khoảng 1 giờ 30 phút (~50km) theo quốc lộ 27 từ Buôn Ma Thuột.\",\n          \"price\": \"Thuê thuyền độc mộc khoảng 150.000 - 300.000 VNĐ/chuyến tùy số lượng người và thời gian.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức bữa trưa với các món ăn đặc sản vùng Hồ Lắk như cá lăng, gà nướng bản địa tại các nhà hàng ven hồ.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy gần khu vực Hồ Lắk.\",\n          \"price\": \"Khoảng 150.000 - 250.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Đôn, làng văn hóa nổi tiếng với nghề săn bắt và thuần dưỡng voi. Tìm hiểu nhà dài truyền thống và cầu treo độc đáo.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~45km) từ Hồ Lắk. Từ Buôn Ma Thuột đi Buôn Đôn khoảng 40 phút (~30km).\",\n          \"price\": \"Vé vào cổng khoảng 40.000 VNĐ/người. Chi phí nếu muốn cưỡi voi hoặc trải nghiệm khác khoảng 150.000 - 300.000 VNĐ.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Quay về Buôn Ma Thuột, thưởng thức bữa tối và mua sắm quà lưu niệm trước khi kết thúc chuyến đi.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/ô tô khoảng 40 phút (~30km) từ Buôn Đôn về Buôn Ma Thuột.\",\n          \"price\": \"Khoảng 100.000 - 200.000 VNĐ/người.\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-07 08:07:17'),
(11, 2, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Làng Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Thưởng thức cà phê Ban Mê tại TP. Buôn Ma Thuột\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/taxi trong trung tâm thành phố.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (chi phí cà phê và bữa sáng nhẹ)\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Làng Cà phê Buôn Ma Thuột để tìm hiểu về quy trình sản xuất cà phê và văn hóa cà phê bản địa.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy/taxi trong trung tâm TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (chỉ tốn chi phí nếu mua sắm hoặc sử dụng dịch vụ ăn uống)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với các món đặc sản địa phương như bún đỏ, nem nướng tại TP. Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy/taxi trong TP. Buôn Ma Thuột.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Khám phá Buôn Ako Dhong, ngôi làng Ê Đê cổ kính ngay giữa lòng thành phố, tìm hiểu về kiến trúc nhà dài và đời sống văn hóa của người dân tộc Ê Đê.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy/taxi khoảng 10-15 phút từ trung tâm TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (chi phí mua sắm đồ lưu niệm nếu có)\"\n        },\n        {\n          \"time\": \"Hoàng hôn\",\n          \"activity\": \"Ngắm hoàng hôn lãng mạn tại Hồ Ea Kao. Du khách có thể đi dạo, cắm trại hoặc thưởng thức đồ uống tại các quán ven hồ.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái khoảng 20-30 phút (~12km) từ trung tâm TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (chi phí ăn uống, đồ uống nếu có)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thưởng thức ẩm thực đường phố tại chợ đêm Buôn Ma Thuột hoặc dùng bữa tại nhà hàng địa phương.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong TP. Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 250.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá Văn hóa M\'nông và Thiên nhiên Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Di chuyển đến Hồ Lắk để đón bình minh và trải nghiệm không khí trong lành của vùng hồ. Ngắm nhìn cảnh quan thiên nhiên và các hoạt động của người dân địa phương vào buổi sáng.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi đi khoảng 1 giờ 30 phút (~55km) theo quốc lộ 27 từ TP. Buôn Ma Thuột. Nên khởi hành sớm để kịp đón bình minh.\",\n          \"price\": \"Miễn phí (chi phí thuê xe hoặc taxi)\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trải nghiệm văn hóa M\'nông tại Hồ Lắk. Có thể tham gia chèo thuyền độc mộc trên hồ hoặc khám phá các buôn làng xung quanh để tìm hiểu về đời sống và phong tục tập quán của người M\'nông.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ quanh hồ hoặc sử dụng các dịch vụ thuyền độc mộc tại chỗ.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người (chi phí thuê thuyền hoặc dịch vụ tham quan buôn làng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại nhà hàng địa phương ven Hồ Lắk, thưởng thức các món ăn đặc sản của vùng như cá nướng, cơm lam.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy/taxi ngắn.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm cuộc sống của người dân địa phương tại Huyện Buôn Đôn, tham quan cầu treo và nhà dài truyền thống.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái khoảng 1 giờ 30 phút (~70km) từ Hồ Lắk. Hoặc quay về TP. Buôn Ma Thuột và di chuyển từ đó.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (vé vào cổng, phí cầu treo)\"\n        },\n        {\n          \"time\": \"Hoàng hôn\",\n          \"activity\": \"Ngắm hoàng hôn tại Dray Nur Waterfall - một trong những thác nước hùng vĩ nhất Tây Nguyên. Cảnh quan hùng vĩ và không khí trong lành sẽ mang lại trải nghiệm đáng nhớ.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái khoảng 1 giờ (~40km) từ Buôn Đôn hoặc 30 phút (~25km) từ TP. Buôn Ma Thuột.\",\n          \"price\": \"30.000 - 50.000 VNĐ/người (vé vào cửa)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Quay về TP. Buôn Ma Thuột, thưởng thức bữa tối cuối cùng với các món ăn Tây Nguyên và mua sắm đặc sản làm quà.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái hoặc taxi về TP. Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 250.000 VNĐ/người\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-07 09:29:43'),
(12, 2, 'Lịch trình 4 ngày - văn hoá, ẩm thực', 4, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Làng Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Bắt đầu hành trình với trải nghiệm không gian cà phê tại thủ phủ cà phê Buôn Ma Thuột. Thưởng thức hương vị cà phê địa phương và tìm hiểu về quy trình chế biến tại một quán cà phê nổi tiếng.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy đến trung tâm thành phố.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (chi phí cà phê và đồ uống)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với các món đặc sản địa phương như bún đỏ, nem nướng hoặc bánh ướt thịt nướng tại các nhà hàng quanh khu vực trung tâm thành phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lán\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy/taxi trong thành phố.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Ako Dhong, một ngôi làng Ê Đê yên bình ngay giữa lòng thành phố. Tìm hiểu về kiến trúc nhà dài truyền thống và văn hóa bản địa.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (nếu có thuê hướng dẫn viên hoặc mua đồ lưu niệm thì chi phí sẽ khác)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Dạo chợ đêm Buôn Ma Thuột, khám phá ẩm thực đường phố và mua sắm các sản phẩm thủ công, đặc sản địa phương làm quà. Thưởng thức bữa tối tại chợ.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong thành phố.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người (chi phí ăn uống và mua sắm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá Văn hóa M\'nông tại Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Tận hưởng không khí trong lành, ngắm cảnh bình minh trên hồ và tìm hiểu về văn hóa M\'nông địa phương.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi đi khoảng 1 giờ 30 phút (~55km) theo quốc lộ 27 từ Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (chi phí di chuyển tự túc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức bữa trưa với các món ăn đặc sản địa phương tại nhà hàng ven hồ Lắk, như cá lăng nướng, cơm lam, hoặc gà nướng.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy gần khu vực hồ.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm đi thuyền độc mộc trên Hồ Lắk, khám phá cuộc sống của người dân M\'nông và ngắm cảnh hoàng hôn tuyệt đẹp trên hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy/taxi gần khu vực hồ.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thưởng thức bữa tối và nghỉ ngơi tại các homestay hoặc nhà nghỉ gần Hồ Lắk để trải nghiệm không gian văn hóa bản địa.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong khu vực Hồ Lắk.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người (chi phí ăn tối) + chi phí lưu trú\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Hành trình khám phá Buôn Đôn và Văn hóa Voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Buôn Đôn, nổi tiếng với truyền thống săn bắt và thuần dưỡng voi. Tham quan những ngôi nhà dài truyền thống và tìm hiểu về văn hóa của người M\'nông.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 1 giờ (~45km) từ Buôn Ma Thuột.\",\n          \"price\": \"50.000 VNĐ/người (vé vào cổng Buôn Đôn)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại nhà hàng địa phương ở Buôn Đôn với các món đặc sản như gà nướng, cá suối nướng hoặc lẩu cá lăng.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong khu vực Buôn Đôn.\",\n          \"price\": \"120.000 - 200.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm đi cầu treo bắc qua sông Serepok. Nếu có điều kiện, có thể trải nghiệm cho voi ăn hoặc tham gia các hoạt động thân thiện với voi (lưu ý tìm hiểu kỹ về các hoạt động bảo vệ voi).\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ tham quan các điểm trong Buôn Đôn.\",\n          \"price\": \"40.000 - 80.000 VNĐ/người (vé cầu treo)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Quay về Buôn Ma Thuột, thưởng thức bữa tối tại một nhà hàng có món ăn Tây Nguyên và thư giãn tại một quán cà phê acoustic.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 1 giờ (~45km) về Buôn Ma Thuột.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người (chi phí ăn tối và cà phê)\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Thiên nhiên và Hồ Ea Kao\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan chợ Buôn Ma Thuột vào buổi sáng để cảm nhận nhịp sống địa phương, mua sắm các sản vật và đặc sản tươi sống về làm quà.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong thành phố.\",\n          \"price\": \"Miễn phí (chi phí mua sắm tự túc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với các món ăn vặt đặc trưng của Buôn Ma Thuột hoặc chọn một quán ăn truyền thống để thưởng thức ẩm thực lần cuối trước khi rời đi.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong thành phố.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Thư giãn tại Hồ Ea Kao, một hồ nước yên bình với phong cảnh hữu tình. Có thể đi dạo quanh hồ, chụp ảnh hoặc đơn giản là tận hưởng không khí trong lành trước khi ra sân bay.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 20-30 phút (~12km) từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Di chuyển ra sân bay Buôn Ma Thuột hoặc bến xe để kết thúc chuyến đi.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe buýt sân bay.\",\n          \"price\": \"50.000 - 150.000 VNĐ (chi phí di chuyển ra sân bay/bến xe)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-07 10:30:44');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(13, 2, 'Lịch trình 5 ngày - ẩm thực, trekking', 5, 'ẩm thực, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tìm hiểu văn hóa cà phê Buôn Ma Thuột tại các quán cà phê nổi tiếng và ghé thăm Bảo tàng Cà phê.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi để di chuyển trong trung tâm thành phố.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người (chi phí đồ uống, vé vào bảo tàng nếu có)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức các món ăn đặc sản Đắk Lắk như bún đỏ, nem nướng...\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy đến các quán ăn địa phương.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê cổ truyền với những ngôi nhà dài truyền thống.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 15 phút từ trung tâm TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Tự do khám phá ẩm thực đường phố Buôn Ma Thuột hoặc thưởng thức không khí cà phê đêm.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trekking và Thưởng ngoạn Thác nước Hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Di chuyển đến Thác Dray Nur và bắt đầu hành trình trekking khám phá vẻ đẹp hoang sơ của thác nước hùng vĩ này.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc ô tô tự lái/taxi khoảng 45 phút (~30km) từ Buôn Ma Thuột theo quốc lộ 14.\",\n          \"price\": \"30.000 - 50.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại nhà hàng địa phương gần thác Dray Nur, thưởng thức các món ăn dân dã.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy quãng ngắn.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tiếp tục tham quan Thác Dray Sáp, chiêm ngưỡng dòng thác \'nước khói\' độc đáo.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái khoảng 5-10 phút từ Thác Dray Nur (hai thác khá gần nhau).\",\n          \"price\": \"30.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Quay về Buôn Ma Thuột, nghỉ ngơi và ăn tối.\",\n          \"address\": \"\",\n          \"transport\": \"Xe máy/ô tô tự lái/taxi khoảng 45 phút (~30km) về Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Khám phá Buôn Đôn và Vườn Quốc gia Yok Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu văn hóa săn bắt và thuần dưỡng voi, trải nghiệm cầu treo Buôn Đôn.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~45km) từ TP. Buôn Ma Thuột.\",\n          \"price\": \"40.000 - 100.000 VNĐ/người (vé vào cổng, phí cầu treo, không bao gồm cưỡi voi)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức các món ăn đặc sản Buôn Đôn như cơm lam, gà nướng, cá lăng sông Sêrêpôk.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy quãng ngắn.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Khám phá Vườn quốc gia Yok Đôn, vườn quốc gia lớn nhất Việt Nam, nơi sinh sống của voi rừng. Có thể lựa chọn các tour trekking trong rừng ngắn hoặc đạp xe.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái khoảng 15 phút từ Buôn Đôn.\",\n          \"price\": \"60.000 - 200.000 VNĐ/người (vé vào cổng, chi phí thuê hướng dẫn viên hoặc các dịch vụ khác)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Quay về Buôn Ma Thuột, nghỉ ngơi và thưởng thức ẩm thực địa phương.\",\n          \"address\": \"\",\n          \"transport\": \"Xe máy/ô tô tự lái/taxi khoảng 1 giờ (~45km) về Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Hồ Lắk và Văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, khám phá văn hóa M\'nông bản địa.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc ô tô tự lái/taxi khoảng 1.5 giờ (~50km) từ Buôn Ma Thuột theo quốc lộ 27.\",\n          \"price\": \"20.000 - 50.000 VNĐ/người (chi phí tham quan buôn làng, không bao gồm chèo thuyền)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại nhà hàng ven hồ Lắk, thưởng thức đặc sản cá nước ngọt và ẩm thực địa phương.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy quãng ngắn.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm chèo thuyền độc mộc trên Hồ Lắk, ngắm cảnh hoàng hôn trên hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ quanh khu vực hồ.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (chi phí thuê thuyền)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Trải nghiệm văn hóa cồng chiêng và thưởng thức rượu cần (nếu có đoàn biểu diễn hoặc đặt trước). Nghỉ đêm tại Hồ Lắk hoặc quay về Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ.\",\n          \"price\": \"100.000 - 300.000 VNĐ/người (tùy thuộc vào hình thức trải nghiệm và chỗ ở)\"\n        }\n      ]\n    },\n    {\n      \"day\": 5,\n      \"title\": \"Thư giãn tại Hồ Ea Kao và Mua sắm Đặc sản\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Hồ Ea Kao, hồ nước rộng lớn gần trung tâm thành phố, thích hợp để tản bộ, ngắm cảnh hoặc cắm trại nhẹ (nếu muốn).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 20-30 phút (~12km) từ trung tâm TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại các nhà hàng ven Hồ Ea Kao hoặc quay về trung tâm Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Xe máy/taxi.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Mua sắm đặc sản Đắk Lắk làm quà như cà phê, mật ong, tiêu, thổ cẩm tại chợ Buôn Ma Thuột hoặc các cửa hàng đặc sản.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy trong trung tâm thành phố.\",\n          \"price\": \"Tùy thuộc vào nhu cầu mua sắm\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối chia tay Đắk Lắk và chuẩn bị khởi hành.\",\n          \"address\": \"\",\n          \"transport\": \"Xe máy/taxi.\",\n          \"price\": \"100.000 - 250.000 VNĐ/người\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-07 11:54:05'),
(14, NULL, 'Lịch trình 2 ngày - văn hoá, trekking', 2, 'văn hoá, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Buôn Ma Thuột và văn hóa Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Buôn Akô Dhông, buôn làng Ê Đê lâu đời và đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa địa phương.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Từ trung tâm Buôn Ma Thuột, bạn có thể đi taxi hoặc xe máy khoảng 10-15 phút (~3km).\",\n          \"price\": \"Miễn phí (chi phí cá nhân nếu mua sắm hoặc thưởng thức đồ uống).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương tại các nhà hàng ở trung tâm Buôn Ma Thuột. Gợi ý các món đặc sản như bún đỏ, lẩu lá rừng.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi trong khu vực trung tâm thành phố.\",\n          \"price\": \"Khoảng 100.000 - 200.000 VNĐ/người cho bữa trưa.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan khu vực Cà phê Buôn Ma Thuột, tìm hiểu quy trình trồng và chế biến cà phê, thưởng thức những ly cà phê đậm đà tại thủ phủ cà phê Việt Nam.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi từ trung tâm thành phố, khoảng 15-20 phút.\",\n          \"price\": \"Miễn phí tham quan (chi phí thưởng thức cà phê khoảng 30.000 - 70.000 VNĐ/ly).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Dạo quanh chợ đêm Buôn Ma Thuột, mua sắm quà lưu niệm và thưởng thức các món ăn vặt đường phố.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong khu vực trung tâm thành phố.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người tùy vào chi tiêu cá nhân.\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình khám phá thác nước và thiên nhiên hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Bắt đầu hành trình trekking tại Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Khám phá vẻ đẹp hoang sơ và tận hưởng không khí trong lành.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi từ trung tâm Buôn Ma Thuột, đi khoảng 45 phút (~30km) theo quốc lộ 14 và đường tỉnh 684.\",\n          \"price\": \"Vé vào cửa khoảng 30.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa gần khu vực thác Dray Nur, có thể là các quán ăn địa phương hoặc chuẩn bị đồ ăn nhẹ mang theo để picnic.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy trong khu vực quanh thác.\",\n          \"price\": \"100.000 - 150.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tiếp tục khám phá Thác Dray Sáp, thác \'nước khói\' nổi tiếng nằm cách Dray Nur không xa, với những trải nghiệm trekking và ngắm cảnh khác biệt.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Từ Thác Dray Nur, bạn có thể đi bộ qua cầu treo hoặc di chuyển bằng xe máy khoảng 5-10 phút để đến Thác Dray Sáp.\",\n          \"price\": \"Vé vào cửa khoảng 30.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Trở về Buôn Ma Thuột, dùng bữa tối và nghỉ ngơi, chuẩn bị cho chuyến đi về.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi từ Thác Dray Sáp về trung tâm Buôn Ma Thuột khoảng 45 phút (~30km).\",\n          \"price\": \"150.000 - 250.000 VNĐ/người cho bữa tối.\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-13 07:46:16'),
(15, NULL, 'Lịch trình 2 ngày - văn hoá', 2, 'văn hoá', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá văn hóa Ê Đê và thưởng thức cà phê nguyên bản\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Buôn Akô Dhông - buôn làng Ê Đê lâu đời và đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống, giao lưu với người dân bản địa và nghe kể chuyện về văn hóa Ê Đê.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Từ trung tâm thành phố Buôn Ma Thuột, bạn có thể đi taxi hoặc xe máy khoảng 10-15 phút (~5km).\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua sắm quà lưu niệm hoặc đồ uống).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương tại một nhà hàng gần trung tâm Buôn Ma Thuột, với các món ăn mang đậm hương vị Tây Nguyên.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi về trung tâm thành phố.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan và trải nghiệm văn hóa cà phê Buôn Ma Thuột. Ghé thăm các quán cà phê rang xay thủ công, tìm hiểu quy trình chế biến cà phê và thưởng thức những ly cà phê nguyên chất.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi tham quan các quán cà phê trong trung tâm thành phố.\",\n          \"price\": \"Miễn phí (chi phí mua cà phê và đồ uống: 50.000 - 100.000 VNĐ/người).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Tự do khám phá Buôn Ma Thuột về đêm, thưởng thức các món ăn vặt đường phố hoặc ghé một quán cà phê acoustic để thư giãn.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người (tùy chọn ăn uống).\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình về miền đất voi và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Di chuyển đến Buôn Đôn, tham quan Làng văn hoá Buôn Đôn, tìm hiểu về nghề săn bắt và thuần dưỡng voi truyền thống. Khám phá kiến trúc nhà dài độc đáo và cầu treo bắc qua sông Serepok.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô tự lái từ Buôn Ma Thuột đi khoảng 1 giờ (~45km) theo tỉnh lộ 1.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người (bao gồm vé vào cổng, tham quan cầu treo và các hoạt động văn hóa tại buôn).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức bữa trưa với các món ăn đặc sản của Buôn Đôn như cơm lam, gà nướng, cá lăng sông Serepok.\",\n          \"address\": \"\",\n          \"transport\": \"Ăn uống tại các nhà hàng trong khu vực Buôn Đôn.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Khám phá Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Trải nghiệm chèo thuyền độc mộc trên hồ và tìm hiểu văn hóa M\'nông, ngắm cảnh hoàng hôn tuyệt đẹp.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Từ Buôn Đôn, di chuyển bằng xe máy hoặc ô tô khoảng 1.5 - 2 giờ (~70km) về phía Nam theo quốc lộ 27. Hoặc từ Buôn Ma Thuột đi khoảng 1.5 giờ (~50km).\",\n          \"price\": \"Miễn phí vé vào cổng (chi phí thuê thuyền độc mộc: 50.000 - 100.000 VNĐ/người).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Kết thúc chuyến đi, quay trở về Buôn Ma Thuột hoặc nghỉ đêm tại các nhà nghỉ/homestay gần Hồ Lắk để trải nghiệm không khí yên bình của vùng đất này.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô về Buôn Ma Thuột (~50km) hoặc tìm chỗ nghỉ tại Hồ Lắk.\",\n          \"price\": \"Tùy chọn chỗ ở (nếu nghỉ lại).\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-15 07:37:01'),
(16, NULL, 'Lịch trình 2 ngày - trekking, cà phê', 2, 'trekking, cà phê', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Thưởng thức cà phê Buôn Ma Thuột và khám phá văn hóa Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Bắt đầu ngày mới tại thủ phủ cà phê Buôn Ma Thuột. Thưởng thức một ly cà phê đậm đà tại một quán cà phê địa phương nổi tiếng. Có thể ghé thăm Bảo tàng Cà phê Thế giới để tìm hiểu sâu hơn về lịch sử và văn hóa cà phê.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (bao gồm cà phê và vé tham quan bảo tàng nếu có)\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa bản địa.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi từ trung tâm thành phố (khoảng 10-15 phút).\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua sắm quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với các món đặc sản Tây Nguyên tại nhà hàng địa phương ở Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy/taxi trong TP. Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Có thể tham gia trekking nhẹ xung quanh khu vực thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 45 phút (~30km) từ Buôn Ma Thuột theo quốc lộ 14 và đường nhánh.\",\n          \"price\": \"30.000 - 50.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Hoàng hôn\",\n          \"activity\": \"Ngắm hoàng hôn tại Thác Dray Nur và sau đó quay về Buôn Ma Thuột.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi về lại TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và tự do khám phá Buôn Ma Thuột về đêm.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong TP. Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 250.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hồ Lắk huyền thoại và trải nghiệm thiên nhiên\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, để đón bình minh và trải nghiệm văn hóa M\'nông. Có thể đi thuyền độc mộc trên hồ hoặc tham quan buôn làng.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi đi khoảng 1.5 giờ (~50km) theo quốc lộ 27 từ Buôn Ma Thuột.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người (bao gồm vé tham quan, thuyền độc mộc nếu có)\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Thác Dray Sáp, thác \'nước khói\' nổi tiếng. Du khách có thể đi bộ tham quan và tận hưởng không khí trong lành.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái từ Hồ Lắk khoảng 1 giờ (~40km) hoặc từ TP. Buôn Ma Thuột khoảng 45 phút (~30km).\",\n          \"price\": \"30.000 - 50.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại nhà hàng địa phương gần khu vực Thác Dray Sáp hoặc quay về Buôn Ma Thuột để thưởng thức ẩm thực.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Vườn quốc gia Yok Đôn, vườn quốc gia lớn nhất Việt Nam. Trải nghiệm trekking trong rừng để khám phá hệ sinh thái đa dạng.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô khoảng 1 giờ (~40km) từ Buôn Ma Thuột. Từ Thác Dray Sáp đến Yok Đôn mất khoảng 1.5 - 2 giờ di chuyển.\",\n          \"price\": \"60.000 - 150.000 VNĐ/người (vé vào cổng, có thể thêm chi phí thuê hướng dẫn viên hoặc dịch vụ đi bộ)\"\n        },\n        {\n          \"time\": \"Hoàng hôn\",\n          \"activity\": \"Tận hưởng không khí yên bình của rừng núi Yok Đôn vào lúc hoàng hôn, sau đó di chuyển về Buôn Ma Thuột.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô về lại TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối chia tay và thư giãn tại Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong TP. Buôn Ma Thuột.\",\n          \"price\": \"150.000 - 300.000 VNĐ/người\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:01:22'),
(17, NULL, 'Lịch trình 2 ngày - văn hoá, ẩm thực, trekking', 2, 'văn hoá, ẩm thực, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá bản sắc cà phê và văn hóa Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Bắt đầu hành trình khám phá văn hóa cà phê tại thủ phủ Buôn Ma Thuột. Tham quan một quán cà phê địa phương, tìm hiểu quy trình chế biến cà phê và thưởng thức hương vị đặc trưng. Gợi ý: Làng cà phê Trung Nguyên hoặc SOUL Roastery để có trải nghiệm sâu sắc.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy (100.000 - 150.000 VNĐ/ngày) hoặc taxi để di chuyển trong thành phố.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (chi phí cà phê)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương với món bún đỏ nổi tiếng Buôn Ma Thuột. Gợi ý: Bún đỏ cô Thu hoặc Thúy.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc đi bộ trong trung tâm thành phố.\",\n          \"price\": \"30.000 - 50.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Khám phá kiến trúc nhà dài truyền thống và tìm hiểu về đời sống, văn hóa của người Ê Đê. Đây là một góc khuất yên bình ngay trong lòng thành phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thưởng thức đặc sản phở hai tô hoặc bánh ướt chồng dĩa 45. Sau đó, có thể dạo quanh quảng trường hoặc các quán cà phê acoustic.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Thám hiểm thác nước và văn hóa voi rừng\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Du khách có thể trekking xung quanh thác để cảm nhận trọn vẹn vẻ đẹp hoang sơ. Sau đó di chuyển đến Thác Dray Sáp, thác \'nước khói\' nổi tiếng gần đó để có một trải nghiệm thác nước đa dạng hơn.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi di chuyển khoảng 45 phút (~30km) từ Buôn Ma Thuột theo quốc lộ 14 và quốc lộ 27. Sau đó có thể đi bộ giữa 2 thác.\",\n          \"price\": \"60.000 VNĐ/người (vé vào cửa Dray Nur) + 30.000 VNĐ/người (vé vào cửa Dray Sáp)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với món gà nướng - cơm lam đặc trưng của vùng Tây Nguyên tại khu vực gần thác hoặc trên đường đến Buôn Đôn.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô.\",\n          \"price\": \"100.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Đôn, làng văn hoá nổi tiếng với nghề săn bắt và thuần dưỡng voi. Khám phá cầu treo dài bắt qua sông Sêrêpôk và tìm hiểu về nhà dài truyền thống. Đây là một trải nghiệm văn hóa độc đáo, ít người biết về lịch sử voi rừng.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái khoảng 1 giờ (~45km) từ khu vực thác Dray Nur/Dray Sáp.\",\n          \"price\": \"40.000 VNĐ/người (vé vào cổng khu du lịch) + 30.000 VNĐ/người (vé cầu treo) + 50.000 - 100.000 VNĐ/người (tùy chọn cưỡi voi hoặc tham quan nhà sàn cổ)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Trở về Buôn Ma Thuột. Mua sắm đặc sản địa phương như cà phê, thịt nai khô, mật ong. Sau đó dùng bữa tối và chuẩn bị kết thúc chuyến đi.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô tự lái khoảng 45 phút (~30km) về Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người (chi phí ăn tối và mua sắm tùy chọn)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:11:55'),
(18, NULL, 'Lịch trình 2 ngày - văn hoá, ẩm thực, gia đình', 2, 'văn hoá, ẩm thực, gia đình', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Buôn Ma Thuột: Văn hóa cà phê và làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại bảo tàng cà phê và các quán cà phê nổi tiếng.\",\n          \"suggestion\": \"Thưởng thức cà phê Buôn Ma Thuột tại Làng cà phê Trung Nguyên hoặc Arul Coffee.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab để di chuyển trong thành phố.\",\n          \"price\": \"Miễn phí (chi phí cà phê tự túc khoảng 50.000 - 100.000 VNĐ/người)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với đặc sản địa phương.\",\n          \"suggestion\": \"Ăn Bún đỏ tại quán cô Thu hoặc Phở hai tô.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc thuê xe máy.\",\n          \"price\": \"50.000 - 80.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê truyền thống giữa lòng thành phố.\",\n          \"suggestion\": \"Khám phá kiến trúc nhà dài truyền thống và mua sắm các sản phẩm thủ công địa phương.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab, di chuyển khoảng 15 phút từ trung tâm.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và tự do khám phá Buôn Ma Thuột về đêm.\",\n          \"suggestion\": \"Thưởng thức Bánh ướt chồng dĩa 45. Nghỉ ngơi tại khách sạn Mường Thanh hoặc homestay Lee\'s House.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc thuê xe máy.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (chưa bao gồm chi phí lưu trú)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình về Hồ Lắk: Thiên nhiên và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Di chuyển đến Hồ Lắk và khám phá vẻ đẹp tự nhiên của hồ nước ngọt lớn thứ hai Việt Nam.\",\n          \"suggestion\": \"Có thể thuê thuyền độc mộc trải nghiệm trên hồ và tìm hiểu văn hóa M\'nông.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi/ô tô đi khoảng 1 giờ 30 phút (~50km) theo quốc lộ 27.\",\n          \"price\": \"Vé vào cổng/phí tham quan khu vực: 20.000 - 50.000 VNĐ/người. Thuê thuyền độc mộc: 100.000 - 200.000 VNĐ/chuyến.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại khu vực Hồ Lắk với các món ăn đặc sản.\",\n          \"suggestion\": \"Thưởng thức cơm lam, gà nướng hoặc cá tươi từ hồ.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan buôn làng M\'nông gần Hồ Lắk, tìm hiểu văn hóa bản địa.\",\n          \"suggestion\": \"Mua sắm cà phê, thịt nai khô, mật ong làm quà trước khi về lại Buôn Ma Thuột.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc thuê xe máy.\",\n          \"price\": \"Miễn phí (chi phí mua sắm tự túc)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Quay về Buôn Ma Thuột. Ăn tối và chuẩn bị kết thúc hành trình.\",\n          \"suggestion\": \"Ăn tối tại một nhà hàng địa phương yêu thích hoặc thưởng thức các món ăn vặt của Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô về lại Buôn Ma Thuột.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:15:14'),
(19, NULL, 'Lịch trình 2 ngày - văn hoá, ẩm thực, chụp ảnh', 2, 'văn hoá, ẩm thực, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Bản sắc Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại bảo tàng và thưởng thức hương vị đặc trưng.\",\n          \"suggestion\": \"Thưởng thức cà phê tại Làng cà phê Trung Nguyên hoặc Arul Coffee.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab để di chuyển trong thành phố.\",\n          \"price\": \"Miễn phí (chi phí cà phê tự túc khoảng 30.000 - 60.000 VNĐ/người)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với đặc sản địa phương.\",\n          \"suggestion\": \"Thưởng thức Bún đỏ tại quán cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) hoặc Phở hai tô 52 (52 Ngô Quyền).\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc đi bộ tùy vị trí.\",\n          \"price\": \"30.000 - 50.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, tìm hiểu văn hóa nhà dài của người Ê Đê và chụp ảnh.\",\n          \"suggestion\": \"Nghỉ ngơi tại Homestay Lee\'s House hoặc Zan Homestay nếu muốn trải nghiệm gần gũi hơn với thiên nhiên.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab khoảng 15-20 phút từ trung tâm.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và tự do khám phá Buôn Ma Thuột về đêm.\",\n          \"suggestion\": \"Ăn Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông) hoặc Quán Cà Te (140 Lê Thánh Tông).\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Chinh phục Thác Nước và Đắm mình trong Thiên nhiên hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên, chụp ảnh và tận hưởng không khí trong lành.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi đi khoảng 45 phút (~30km) theo quốc lộ 27.\",\n          \"price\": \"30.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại khu vực gần thác.\",\n          \"suggestion\": \"Thưởng thức các món ăn địa phương tại các nhà hàng hoặc quán ăn ven đường gần thác.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"50.000 - 80.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, trải nghiệm đi thuyền độc mộc và tìm hiểu văn hoá M\'nông.\",\n          \"suggestion\": \"Trải nghiệm lưu trú tại Lak Tented Camp nếu có thời gian.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 1 giờ (~50km) từ Thác Dray Nur hoặc TP Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (chi phí thuyền độc mộc khoảng 100.000 - 200.000 VNĐ/người)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và mua sắm đặc sản Đắk Lắk trước khi kết thúc chuyến đi.\",\n          \"suggestion\": \"Mua cà phê, thịt nai khô, mật ong hoặc hạt mắc ca làm quà tại các cửa hàng đặc sản.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển về Buôn Ma Thuột bằng xe máy hoặc taxi.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:18:48'),
(20, NULL, 'Lịch trình 2 ngày - văn hoá, ẩm thực, chụp ảnh', 2, 'văn hoá, ẩm thực, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Trải nghiệm văn hóa Cà phê Buôn Ma Thuột tại một quán cà phê địa phương để bắt đầu ngày mới.\",\n          \"suggestion\": \"Thưởng thức cà phê Ban Mê tại Làng cà phê Trung Nguyên hoặc Arul Coffee.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi để di chuyển trong thành phố.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (chi phí đồ uống)\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Buôn Akô Dhông - buôn làng Ê Đê đẹp nhất Buôn Ma Thuột, tìm hiểu kiến trúc nhà dài và văn hóa địa phương.\",\n          \"suggestion\": \"Tương tác với người dân địa phương, chụp ảnh nhà dài truyền thống.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi xe máy hoặc taxi khoảng 15 phút từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (tùy chọn mua quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương tại Buôn Ma Thuột.\",\n          \"suggestion\": \"Ăn Bún đỏ tại quán cô Thu hoặc Bánh ướt chồng dĩa 45.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc đi bộ đến các quán ăn.\",\n          \"price\": \"30.000 - 60.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Hồ Ea Kao, tận hưởng không khí trong lành và cảnh hoàng hôn lãng mạn.\",\n          \"suggestion\": \"Chuẩn bị máy ảnh để ghi lại khoảnh khắc hoàng hôn tuyệt đẹp.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 20 phút từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Dùng bữa tối tại Buôn Ma Thuột và khám phá các quán cà phê buổi tối.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te. Thưởng thức cà phê tại SOUL Roastery.\",\n          \"address\": \"\",\n          \"transport\": \"Thuê xe máy hoặc taxi.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hồ Lắk Huyền thoại và Thác nước hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Ngắm bình minh và tham quan Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, khám phá văn hóa M\'nông.\",\n          \"suggestion\": \"Trải nghiệm đi thuyền độc mộc trên Hồ Lắk (nếu có).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Nên thuê xe máy hoặc taxi đi khoảng 1 tiếng (~50km) theo quốc lộ 27.\",\n          \"price\": \"30.000 - 100.000 VNĐ/người (chi phí thuê thuyền nếu có)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với đặc sản địa phương gần Hồ Lắk hoặc trên đường về Buôn Ma Thuột.\",\n          \"suggestion\": \"Thưởng thức các món cá nước ngọt hoặc thịt rừng (nếu có).\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên, để chụp ảnh và tận hưởng thiên nhiên.\",\n          \"suggestion\": \"Đi bộ khám phá các điểm ngắm cảnh quanh thác, chụp ảnh hoàng hôn nếu thời gian cho phép.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Từ Hồ Lắk, di chuyển bằng xe máy hoặc taxi khoảng 1 giờ 30 phút (~70km).\",\n          \"price\": \"30.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Quay về Buôn Ma Thuột, ăn tối và mua sắm quà lưu niệm trước khi kết thúc chuyến đi.\",\n          \"suggestion\": \"Mua cà phê, thịt nai khô hoặc mật ong làm quà. Thưởng thức Phở hai tô 52.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi về Buôn Ma Thuột (~30 phút từ thác Dray Nur).\",\n          \"price\": \"100.000 - 200.000 VNĐ/người (ăn uống và mua sắm)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:18:55'),
(21, NULL, 'Lịch trình 2 ngày - cà phê, gia đình', 2, 'cà phê, gia đình', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại Làng cà phê Trung Nguyên\",\n          \"suggestion\": \"Ăn sáng và thưởng thức cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab để di chuyển đến Làng cà phê Trung Nguyên. Thời gian di chuyển tùy thuộc vào vị trí khách sạn.\",\n          \"price\": \"Miễn phí (chi phí đồ uống khoảng 50.000 - 100.000 VNĐ/người)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Tham quan Buôn Akô Dhông - Buôn làng Ê Đê cổ kính\",\n          \"suggestion\": \"Ăn trưa các món đặc sản địa phương tại một nhà hàng gần trung tâm TP. Buôn Ma Thuột, ví dụ như Quán Cà Te (140 Lê Thánh Tông).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab từ trung tâm thành phố (khoảng 15 phút).\",\n          \"price\": \"Miễn phí (chi phí ăn trưa khoảng 100.000 - 150.000 VNĐ/người)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan chợ trung tâm Buôn Ma Thuột, mua sắm đặc sản\",\n          \"suggestion\": \"Mua sắm cà phê, mật ong, thịt nai khô tại chợ trung tâm Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe máy/taxi trong nội thành Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (chi phí mua sắm tùy thuộc nhu cầu)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thưởng thức ẩm thực và cà phê tại quán địa phương\",\n          \"suggestion\": \"Ăn tối Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Sau đó, thưởng thức cà phê tại SOUL Roastery (87 Nguyễn Khuyến).\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab trong nội thành.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người (ăn tối + cà phê)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hòa mình vào thiên nhiên hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Thác Dray Nur - Thác nước hùng vĩ bậc nhất Tây Nguyên\",\n          \"suggestion\": \"Ăn sáng tại khách sạn hoặc trên đường đi. Nên xuất phát sớm để có nhiều thời gian tham quan.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab đi khoảng 45 phút (~30km) theo quốc lộ 14 và đường tỉnh 682.\",\n          \"price\": \"30.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại khu vực Thác Dray Nur\",\n          \"suggestion\": \"Ăn trưa tại các nhà hàng hoặc quán ăn trong khu du lịch Thác Dray Nur với các món ăn địa phương.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ trong khu vực thác.\",\n          \"price\": \"100.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm Hồ Ea Kao và thư giãn\",\n          \"suggestion\": \"Thư giãn, chụp ảnh và tận hưởng không khí trong lành tại Hồ Ea Kao. Hoặc có thể ghé một quán cà phê ven hồ để nghỉ ngơi.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab từ Thác Dray Nur về Hồ Ea Kao (khoảng 30-40 phút).\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Mua sắm quà lưu niệm và thưởng thức bữa tối cuối cùng\",\n          \"suggestion\": \"Mua quà lưu niệm tại các cửa hàng đặc sản trong thành phố. Ăn tối Phở hai tô 52 (52 Ngô Quyền) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông) trước khi kết thúc chuyến đi.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab trong nội thành.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:21:28'),
(22, NULL, 'Lịch trình 2 ngày - thiên nhiên, chụp ảnh', 2, 'thiên nhiên, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá thác nước hùng vĩ và văn hóa cà phê Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Thác Dray Nur và Thác Dray Sáp, chiêm ngưỡng vẻ đẹp thiên nhiên hùng vĩ và chụp ảnh.\",\n          \"suggestion\": \"Nên thuê xe máy hoặc taxi/Grab để di chuyển thuận tiện giữa hai thác. Chuẩn bị đồ bơi nếu muốn tắm thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab đi khoảng 30km (~45 phút) từ trung tâm Buôn Ma Thuột theo QL14 rồi rẽ vào đường 682. Chi phí thuê xe máy khoảng 100.000 - 150.000 VNĐ/ngày.\",\n          \"price\": \"Vé vào cửa Thác Dray Nur: 30.000 VNĐ/người. Vé vào cửa Thác Dray Sáp: 30.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa đặc sản địa phương và nghỉ ngơi.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng gần khu vực thác hoặc quay về trung tâm Buôn Ma Thuột. Sau đó, nghỉ trưa tại Zan Homestay (37 Hồ Giáo) nếu muốn có không gian yên tĩnh.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab.\",\n          \"price\": \"100.000 - 150.000 VNĐ/người cho bữa ăn. Chi phí nghỉ ngơi tùy chọn.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm văn hóa Cà phê Buôn Ma Thuột, tham quan bảo tàng cà phê và thưởng thức hương vị cà phê đặc trưng.\",\n          \"suggestion\": \"Ghé Làng cà phê Trung Nguyên (163 Lý Thái Tổ) để có trải nghiệm toàn diện hoặc SOUL Roastery (87 Nguyễn Khuyến) nếu thích không gian hiện đại hơn.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab trong thành phố.\",\n          \"price\": \"Miễn phí tham quan bảo tàng cà phê. Chi phí thưởng thức cà phê: 50.000 - 100.000 VNĐ/người.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Khám phá chợ đêm Buôn Ma Thuột, ăn tối và mua sắm đặc sản.\",\n          \"suggestion\": \"Ăn Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Ngủ đêm tại Mường Thanh (81 Nguyễn Tất Thành) để thuận tiện di chuyển.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong thành phố.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người cho bữa tối. Chi phí mua sắm quà lưu niệm tùy chọn. Giá phòng khách sạn khoảng 700.000 - 1.200.000 VNĐ/đêm.\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Đắm mình vào thiên nhiên Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, trải nghiệm thuyền độc mộc và văn hóa M\'nông.\",\n          \"suggestion\": \"Nên đi sớm để tận hưởng không khí trong lành và cảnh bình minh trên hồ. Thưởng thức bữa sáng nhẹ tại khu vực Hồ Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab đi khoảng 50km (~1 tiếng 15 phút) theo quốc lộ 27 từ Buôn Ma Thuột.\",\n          \"price\": \"Thuê thuyền độc mộc: 100.000 - 200.000 VNĐ/người (tùy thời gian và số lượng). Tham quan buôn làng: Miễn phí.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại Hồ Lắk với các món ăn địa phương và nghỉ ngơi.\",\n          \"suggestion\": \"Thưởng thức các món cá nước ngọt tại các nhà hàng ven hồ. Có thể nghỉ trưa tại Lak Tented Camp (ven Hồ Lắk) nếu muốn trải nghiệm hòa mình vào thiên nhiên.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi quanh khu vực Hồ Lắk.\",\n          \"price\": \"100.000 - 150.000 VNĐ/người cho bữa ăn.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột, tìm hiểu kiến trúc nhà dài và văn hóa bản địa.\",\n          \"suggestion\": \"Đi bộ tham quan buôn làng, trò chuyện với người dân địa phương. Kết thúc chuyến đi bằng cách mua sắm quà lưu niệm cà phê hoặc đặc sản tại chợ truyền thống gần đó.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab về Buôn Ma Thuột (~1h15p), sau đó đi bộ hoặc xe máy/taxi trong thành phố đến Buôn Akô Dhông.\",\n          \"price\": \"Miễn phí tham quan. Chi phí mua sắm tùy chọn.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và chuẩn bị kết thúc hành trình.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông) với các món ăn đa dạng. Ngủ đêm tại Lee\'s House (55 đường số 3, Cư Bur) để tận hưởng không gian yên bình trước khi rời Đắk Lắk.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab trong thành phố.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người cho bữa tối. Giá phòng homestay khoảng 500.000 - 800.000 VNĐ/đêm.\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:24:26');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(23, 2, 'Lịch trình 3 ngày - thiên nhiên, văn hoá, gia đình', 3, 'thiên nhiên, văn hoá, gia đình', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Đón bình minh tại Hồ Lắk và trải nghiệm đi thuyền độc mộc trên hồ. Khám phá làng M\'nông và tìm hiểu văn hóa bản địa.\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, thích hợp cho gia đình muốn trải nghiệm thiên nhiên và văn hóa. Buổi sáng sớm là thời điểm đẹp nhất để ngắm bình minh và tham gia các hoạt động trên hồ. Di chuyển đến Hồ Lắk mất khoảng 1.5 - 2 tiếng từ Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho người dân địa phương (dịch vụ thuyền độc mộc, hướng dẫn viên).\",\n          \"suggestion\": \"Thuê thuyền độc mộc của người dân địa phương. Homestay: Lak Tented Camp (ven Hồ Lắk) hoặc các homestay xung quanh Hồ Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô riêng để di chuyển từ Buôn Ma Thuột đến Hồ Lắk.\",\n          \"price\": \"200.000đ (vé tham quan + thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi tại Hồ Lắk.\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan, thưởng thức các món ăn đặc trưng của vùng Hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Quán ăn ven hồ với các món cá tươi. Homestay: Lak Tented Camp (ven Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột.\",\n          \"reason\": \"Buôn Akô Dhông mang đậm nét văn hóa Ê Đê truyền thống, với những ngôi nhà dài cổ kính. Nơi đây yên bình và dễ dàng tiếp cận, phù hợp cho gia đình. Buổi chiều mát mẻ để đi dạo và chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho các sản phẩm thủ công địa phương nếu mua sắm.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi/Grab hoặc xe máy từ Hồ Lắk về Buôn Ma Thuột, sau đó di chuyển trong thành phố.\",\n          \"price\": \"50.000đ (nước uống/đồ lưu niệm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thưởng thức ẩm thực Buôn Ma Thuột và nghỉ ngơi.\",\n          \"reason\": \"Khám phá ẩm thực đường phố và các món đặc sản của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Khách sạn: Mường Thanh (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột) hoặc Elephants (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi/Grab hoặc đi bộ\",\n          \"price\": \"200.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Thám hiểm thác nước hùng vĩ và trải nghiệm cà phê Tây Nguyên\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên.\",\n          \"reason\": \"Thác Dray Nur có vẻ đẹp hoang sơ, hùng vĩ, phù hợp cho gia đình yêu thiên nhiên và thích khám phá. Buổi sáng là thời điểm lý tưởng để tránh nắng nóng và đông đúc.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho vé vào cổng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô riêng từ Buôn Ma Thuột.\",\n          \"price\": \"30.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa và nghỉ ngơi gần khu vực thác.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi sau buổi sáng trekking tại thác.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Các quán ăn ven đường gần Thác Dray Nur. Homestay: Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột) nếu muốn về trung tâm thành phố nghỉ trưa.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trải nghiệm văn hóa Cà phê Buôn Ma Thuột tại Làng Cà phê Trung Nguyên.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, đây là cơ hội tuyệt vời để gia đình tìm hiểu về quy trình làm cà phê và thưởng thức hương vị đặc trưng. Chiều mát mẻ để dạo chơi và thư giãn.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho sản phẩm cà phê địa phương.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi/Grab hoặc xe máy.\",\n          \"price\": \"50.000đ (thức uống cà phê)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Tự do khám phá ẩm thực tối tại Buôn Ma Thuột và mua sắm đặc sản.\",\n          \"reason\": \"Khám phá thêm các món ăn địa phương và mua quà lưu niệm về cà phê, thịt nai khô, mật ong.\",\n          \"community_impact\": \"Dự kiến 400.000đ cho nhà hàng và cửa hàng đặc sản địa phương.\",\n          \"suggestion\": \"Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Khách sạn: Elephants (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi/Grab hoặc đi bộ\",\n          \"price\": \"250.000đ (ăn tối + mua sắm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Văn hóa voi Buôn Đôn và thiên nhiên hồ Ea Kao\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Buôn Đôn, làng văn hoá nổi tiếng với nghề săn bắt và thuần dưỡng voi.\",\n          \"reason\": \"Buôn Đôn mang đến trải nghiệm văn hóa độc đáo về voi và người Ê Đê. Gia đình có thể tìm hiểu về lịch sử săn bắt voi và kiến trúc nhà dài truyền thống. Buổi sáng sớm khí hậu dễ chịu.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho người dân địa phương (vé tham quan, dịch vụ tại Buôn Đôn).\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô riêng từ Buôn Ma Thuột.\",\n          \"price\": \"50.000đ (vé tham quan Buôn Đôn)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa đặc sản Buôn Đôn và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức các món ăn đặc trưng của Buôn Đôn, đặc biệt là các món từ cá sông.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Các quán ăn tại Buôn Đôn. Homestay: Lee\'s House (55 đ.số 3, Cư Bur, TP. Buôn Ma Thuột) nếu muốn về trung tâm thành phố nghỉ trưa.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Thư giãn tại Hồ Ea Kao, ngắm cảnh hoàng hôn.\",\n          \"reason\": \"Hồ Ea Kao là một hồ nước rộng lớn, gần trung tâm thành phố, thích hợp cho gia đình thư giãn, đi dạo và ngắm hoàng hôn. Đây là hoạt động nhẹ nhàng, kết thúc chuyến đi một cách thư thái.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho nước uống/đồ ăn vặt địa phương.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi/Grab hoặc xe máy từ Buôn Đôn về Buôn Ma Thuột, sau đó di chuyển đến Hồ Ea Kao.\",\n          \"price\": \"50.000đ (đồ uống)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối chia tay Đắk Lắk và di chuyển ra sân bay/bến xe.\",\n          \"reason\": \"Thưởng thức bữa tối cuối cùng với các món ăn yêu thích của Buôn Ma Thuột trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi/Grab\",\n          \"price\": \"200.000đ (ăn tối + di chuyển sân bay/bến xe)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:39:16'),
(24, 2, 'Lịch trình 2 ngày - văn hoá, trekking, chụp ảnh', 2, 'văn hoá, trekking, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Buôn Ma Thuột: Văn hóa cà phê và làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột. Tham quan bảo tàng cà phê và thưởng thức các loại cà phê đặc trưng.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê Việt Nam, trải nghiệm này sẽ giúp du khách hiểu hơn về văn hóa cà phê và là điểm khởi đầu lý tưởng cho sở thích văn hóa.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho cơ sở sản xuất cà phê địa phương.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk) hoặc Arul Coffee (17 Trần Nhật Duật, TP. Buôn Ma Thuột, Đắk Lắk)\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (100k-150k/ngày) hoặc taxi/Grab để di chuyển trong thành phố.\",\n          \"price\": \"100.000đ (phí tham quan bảo tàng + đồ uống)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa và nghỉ ngơi tại trung tâm thành phố.\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan và nạp năng lượng cho buổi chiều.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk) với các món ăn đặc sản Tây Nguyên. Nghỉ ngơi tại Khách sạn Elephants (142 Hai Bà Trưng, TP. Buôn Ma Thuột, Đắk Lắk).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong phạm vi gần.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê truyền thống đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài và văn hóa bản địa.\",\n          \"reason\": \"Đáp ứng sở thích văn hóa và chụp ảnh với kiến trúc độc đáo của nhà dài Ê Đê, đồng thời không di chuyển quá xa trung tâm.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua đồ lưu niệm nhỏ từ người dân.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ trung tâm thành phố.\",\n          \"price\": \"50.000đ (chi phí cá nhân/mua sắm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương và tự do khám phá Buôn Ma Thuột về đêm.\",\n          \"reason\": \"Trải nghiệm thêm văn hóa ẩm thực và thư giãn sau một ngày dài.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Ăn tối Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột, Đắk Lắk). Nghỉ đêm tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột, Đắk Lắk) để trải nghiệm không gian địa phương.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"250.000đ (ăn tối + đồ uống)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình khám phá Hồ Lắk và Thác Dray Nur\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam. Trải nghiệm đi thuyền độc mộc trên hồ và tìm hiểu văn hóa M\'nông.\",\n          \"reason\": \"Hồ Lắk mang đến trải nghiệm thiên nhiên hùng vĩ và văn hóa bản địa độc đáo, rất phù hợp với sở thích văn hóa và chụp ảnh, trekking nhẹ.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho dịch vụ thuyền độc mộc của người dân M\'nông.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (khoảng 1.5 - 2 tiếng di chuyển từ BMT) hoặc thuê xe ô tô riêng.\",\n          \"price\": \"250.000đ (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa đặc sản tại khu vực Hồ Lắk.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi trước khi tiếp tục hành trình.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Thưởng thức món ăn địa phương tại các nhà hàng ven Hồ Lắk. Có thể nghỉ ngơi tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk, Đắk Lắk) nếu có nhu cầu.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy trong phạm vi gần.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Có thể trekking nhẹ quanh khu vực thác và chụp ảnh.\",\n          \"reason\": \"Thác Dray Nur mang đến cảnh quan thiên nhiên tráng lệ, phù hợp với sở thích trekking và chụp ảnh. Vị trí gần Hồ Lắk giúp tối ưu hóa thời gian di chuyển.\",\n          \"community_impact\": \"Dự kiến 30.000đ vé vào cổng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô từ Hồ Lắk (khoảng 1 tiếng di chuyển).\",\n          \"price\": \"30.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Di chuyển về Buôn Ma Thuột, ăn tối và kết thúc hành trình.\",\n          \"reason\": \"Thư giãn sau chuyến đi dài và thưởng thức bữa tối cuối cùng tại Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn tối Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột, Đắk Lắk). Khách sạn Mường Thanh (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk) là lựa chọn tiện nghi nếu cần ở lại thêm.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về lại trung tâm Buôn Ma Thuột.\",\n          \"price\": \"200.000đ (ăn tối)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:49:57'),
(25, 2, 'Lịch trình 2 ngày - văn hoá, trekking, chụp ảnh', 2, 'văn hoá, trekking, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá văn hóa cà phê và buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trải nghiệm văn hoá cà phê tại Thủ phủ cà phê Buôn Ma Thuột và tham quan Buôn Akô Dhông\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, du khách có thể tìm hiểu về quy trình sản xuất và thưởng thức cà phê đặc trưng. Buôn Akô Dhông là buôn làng Ê Đê đẹp và gần trung tâm, phù hợp cho việc khám phá văn hóa và chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho người dân/cơ sở OCOP tại Buôn Akô Dhông.\",\n          \"suggestion\": \"Thưởng thức cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ) hoặc SOUL Roastery (87 Nguyễn Khuyến).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (100k-150k/ngày) hoặc taxi/Grab để di chuyển giữa các điểm.\",\n          \"price\": \"100000\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa đặc sản Buôn Ma Thuột và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) hoặc Phở hai tô 52 (52 Ngô Quyền). Nghỉ ngơi tại Zan Homestay (37 Hồ Giáo) hoặc Elephants Hotel (142 Hai Bà Trưng).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc đi bộ.\",\n          \"price\": \"200000\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Khám phá Hồ Ea Kao và cắm trại\",\n          \"reason\": \"Hồ Ea Kao là hồ nước rộng lớn gần trung tâm thành phố, thích hợp để cắm trại, chụp ảnh và tận hưởng không gian thiên nhiên yên bình. Phù hợp cho sở thích chụp ảnh và thư giãn.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho các dịch vụ nhỏ lẻ tại địa phương (nếu có).\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"50000\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và trải nghiệm không gian đêm Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và trải nghiệm nhịp sống về đêm của thành phố.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng và cửa hàng lưu niệm.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng) hoặc Mường Thanh (81 Nguyễn Tất Thành).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ.\",\n          \"price\": \"500000\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trekking thác nước và văn hóa voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trekking và tham quan Thác Dray Nur, Thác Dray Sáp\",\n          \"reason\": \"Hai thác nước hùng vĩ này nằm gần nhau, rất phù hợp cho hoạt động trekking, chụp ảnh và chiêm ngưỡng vẻ đẹp thiên nhiên Tây Nguyên.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho vé vào cửa và dịch vụ tại thác.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột. Quãng đường khoảng 30km.\",\n          \"price\": \"50000\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại khu vực Thác hoặc di chuyển về Buôn Đôn ăn trưa\",\n          \"reason\": \"Nạp năng lượng sau buổi sáng trekking. Tùy chọn ăn trưa gần thác để tiết kiệm thời gian hoặc di chuyển về Buôn Đôn để trải nghiệm ẩm thực tại đây.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Có thể tìm các quán ăn nhỏ tại khu vực thác hoặc di chuyển đến các quán ăn ở Buôn Đôn. Nghỉ ngơi tại một quán cà phê hoặc nhà sàn tại Buôn Đôn.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk hoặc Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"150000\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Đôn và trải nghiệm văn hóa voi\",\n          \"reason\": \"Buôn Đôn nổi tiếng với nghề săn bắt và thuần dưỡng voi, cùng với kiến trúc nhà dài truyền thống. Đây là cơ hội tuyệt vời để tìm hiểu văn hóa địa phương và chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho vé vào cửa và hỗ trợ cộng đồng tại Buôn Đôn (ví dụ: mua sắm sản phẩm địa phương).\",\n          \"suggestion\": \"Gợi ý mua sắm cà phê, thịt nai khô tại các cửa hàng địa phương.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Thác Dray Nur/Dray Sáp (khoảng 20-30km).\",\n          \"price\": \"200000\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và mua sắm đặc sản Buôn Ma Thuột, kết thúc hành trình\",\n          \"reason\": \"Thưởng thức bữa tối cuối cùng tại Đắk Lắk và mua sắm quà lưu niệm trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng và cửa hàng đặc sản.\",\n          \"suggestion\": \"Ăn tối tại một nhà hàng có món nướng hoặc lẩu địa phương. Mua sắm cà phê, hạt mắc ca tại các cửa hàng đặc sản ở trung tâm Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Buôn Đôn về TP. Buôn Ma Thuột (khoảng 40km).\",\n          \"price\": \"300000\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 05:50:08'),
(26, 2, 'Lịch trình 2 ngày - văn hoá, trekking', 2, 'văn hoá, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Thác Nước hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột và tham quan chợ truyền thống\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê Việt Nam, trải nghiệm này giúp du khách hiểu hơn về quy trình sản xuất và thưởng thức cà phê địa phương, đồng thời khám phá chợ truyền thống để cảm nhận nhịp sống và ẩm thực địa phương.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nông dân/cửa hàng cà phê địa phương và 100.000đ tại chợ.\",\n          \"suggestion\": \"Thưởng thức cà phê tại SOUL Roastery (87 Nguyễn Khuyến). Ghé thăm chợ Trung tâm Buôn Ma Thuột (đường Nguyễn Thị Minh Khai).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy để tiện di chuyển giữa các điểm (khoảng 100.000 - 150.000đ/ngày).\",\n          \"price\": \"50.000đ (cà phê) + 100.000đ (mua sắm chợ)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan và nạp năng lượng với các món ăn đặc trưng của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"70.000đ (ăn trưa) + 100.000đ (chi phí nghỉ ngơi/nước uống nếu có)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Trekking và khám phá Thác Dray Nur\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước hùng vĩ nhất Tây Nguyên, phù hợp với sở thích trekking và khám phá thiên nhiên của du khách. Đường đi bộ quanh thác mang đến trải nghiệm gần gũi với thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 30.000đ vé vào cổng.\",\n          \"suggestion\": \"Mang giày thoải mái để đi bộ và đừng quên máy ảnh.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy (khoảng 25km từ trung tâm BMT).\",\n          \"price\": \"30.000đ (vé vào cổng) + 50.000đ (xăng xe)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và trải nghiệm không gian cà phê độc đáo\",\n          \"reason\": \"Thư giãn sau một ngày khám phá, thưởng thức ẩm thực và tận hưởng không khí yên bình của Buôn Ma Thuột về đêm.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng/quán cà phê.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền). Thưởng thức cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"100.000đ (ăn tối) + 50.000đ (cà phê)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình Văn hóa Bản làng và Đại ngàn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Buôn Akô Dhông và tìm hiểu văn hóa Ê Đê\",\n          \"reason\": \"Buôn Akô Dhông nằm ngay trong lòng thành phố, là nơi lưu giữ nét văn hóa truyền thống của người Ê Đê với những ngôi nhà dài cổ kính, phù hợp với sở thích khám phá văn hóa.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho các sản phẩm thủ công địa phương.\",\n          \"suggestion\": \"Tìm hiểu về kiến trúc nhà dài và cuộc sống của người dân bản địa.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (tham quan)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa và di chuyển đến Hồ Lắk\",\n          \"reason\": \"Nạp năng lượng trước khi di chuyển đến Hồ Lắk, một trong những hồ nước ngọt tự nhiên lớn nhất Việt Nam.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"80.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Khám phá Hồ Lắk và trải nghiệm thuyền độc mộc\",\n          \"reason\": \"Hồ Lắk không chỉ là cảnh quan thiên nhiên tuyệt đẹp mà còn gắn liền với văn hóa M\'nong, trải nghiệm thuyền độc mộc là cách tuyệt vời để cảm nhận sự yên bình và gần gũi với văn hóa bản địa.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho người dân địa phương (dịch vụ thuyền).\",\n          \"suggestion\": \"Đi thuyền độc mộc trên hồ và ghé thăm một buôn làng ven hồ. Thưởng thức cà phê chiều tại một quán nhỏ ven hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy (khoảng 50km từ BMT).\",\n          \"price\": \"150.000đ (thuê thuyền độc mộc) + 50.000đ (xăng xe)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và nghỉ ngơi tại Hồ Lắk\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương ven hồ và tận hưởng không gian yên bình của Hồ Lắk về đêm, chuẩn bị cho hành trình tiếp theo.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng/homestay địa phương.\",\n          \"suggestion\": \"Thưởng thức hải sản nước ngọt tại nhà hàng ven hồ. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"150.000đ (ăn tối)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 06:06:23'),
(27, 2, 'Lịch trình 2 ngày - trekking, cà phê', 2, 'trekking, cà phê', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá đại ngàn và văn hóa cà phê Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Trekking tại Thác Dray Nur và Thác Dray Sáp\",\n          \"reason\": \"Hai thác nước hùng vĩ, liền kề nhau, rất phù hợp cho du khách yêu thích trekking và khám phá thiên nhiên. Quý khách sẽ được trải nghiệm đi bộ qua những con đường rừng, ngắm nhìn vẻ đẹp hoang sơ của Tây Nguyên và cảm nhận sự tươi mát từ dòng thác.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho vé vào cổng và dịch vụ tại khu vực thác.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ trung tâm Buôn Ma Thuột (khoảng 30km) để tiện di chuyển giữa hai thác.\",\n          \"price\": \"50.000đ/người (vé vào cổng Dray Nur) + 30.000đ/người (vé vào cổng Dray Sáp) + 150.000đ (thuê xe máy)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa đặc sản địa phương và nghỉ ngơi\",\n          \"reason\": \"Sau buổi trekking, quý khách cần nạp lại năng lượng với các món ăn đặc trưng của Đắk Lắk và có thời gian thư giãn.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho bữa trưa tại nhà hàng địa phương.\",\n          \"suggestion\": \"Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) hoặc các quán ăn gần khu vực thác. Nghỉ ngơi tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột) để thuận tiện di chuyển cho buổi chiều.\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab về lại TP. Buôn Ma Thuột.\",\n          \"price\": \"150.000đ - 250.000đ/người (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Khám phá văn hóa cà phê Buôn Ma Thuột\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, không thể bỏ qua trải nghiệm tìm hiểu về quy trình sản xuất cà phê và thưởng thức hương vị cà phê nguyên bản tại đây. Đây là hoạt động rất phù hợp với sở thích về cà phê của du khách.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho sản phẩm cà phê và đồ uống.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột) để tham quan và thưởng thức cà phê. Hoặc SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) để trải nghiệm cà phê specialty.\",\n          \"address\": \"163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ tùy vị trí từ chỗ nghỉ.\",\n          \"price\": \"Free (tham quan) + 50.000đ - 100.000đ (thức uống/mua sắm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và trải nghiệm không gian Buôn Ma Thuột về đêm\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và thư giãn sau một ngày khám phá.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho bữa tối.\",\n          \"suggestion\": \"Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột) hoặc Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột) để tiện khám phá trung tâm.\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ.\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối) + 500.000đ - 1.000.000đ (khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình về miền văn hóa M\'nông và đại ngàn Yok Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt lớn thứ hai Việt Nam, nơi quý khách có thể trải nghiệm văn hóa M\'nông đặc sắc, đi thuyền độc mộc trên hồ và ngắm cảnh bình yên. Đây là hoạt động gắn liền với thiên nhiên và văn hóa bản địa, rất phù hợp với yêu cầu của du khách.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho dịch vụ thuyền độc mộc và tương tác với người dân địa phương.\",\n          \"suggestion\": \"Trải nghiệm đi thuyền độc mộc trên Hồ Lắk. Có thể ghé thăm buôn làng M\'nông ven hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km).\",\n          \"price\": \"Free (tham quan hồ) + 150.000đ - 250.000đ (thuyền độc mộc) + 150.000đ (thuê xe máy nếu chưa có)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại Hồ Lắk và khởi hành về Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức các món ăn đặc sản địa phương tại khu vực Hồ Lắk trước khi quay trở lại thành phố.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho bữa trưa.\",\n          \"suggestion\": \"Các nhà hàng nổi ven hồ hoặc quán ăn tại thị trấn Liên Sơn, Huyện Lắk. Sau đó di chuyển về lại Buôn Ma Thuột.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab để về Buôn Ma Thuột.\",\n          \"price\": \"100.000đ - 200.000đ/người (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Vườn quốc gia Yok Đôn\",\n          \"reason\": \"Vườn quốc gia Yok Đôn là điểm đến lý tưởng cho những ai muốn khám phá rừng nguyên sinh, tìm hiểu về hệ sinh thái đa dạng và có cơ hội ngắm nhìn voi rừng (nếu may mắn). Đây là hoạt động trekking và gần gũi với thiên nhiên theo sở thích của du khách.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho vé vào cổng và đóng góp vào quỹ bảo tồn.\",\n          \"suggestion\": \"Tham gia tour đi bộ trong rừng hoặc thuê xe đạp. Tuyệt đối không cưỡi voi để bảo vệ loài vật này.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Yok Đôn (khoảng 40km).\",\n          \"price\": \"60.000đ/người (vé vào cổng) + 50.000đ - 100.000đ (thuê xe đạp/dịch vụ khác)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và mua sắm đặc sản Đắk Lắk\",\n          \"reason\": \"Thưởng thức bữa tối cuối cùng tại Buôn Ma Thuột và mua sắm những món quà lưu niệm, đặc sản về làm quà.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho bữa tối và mua sắm đặc sản.\",\n          \"suggestion\": \"Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Mua sắm cà phê, thịt nai khô tại các cửa hàng đặc sản địa phương. Nghỉ đêm tại Mường Thanh Luxury Buôn Ma Thuột (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột) hoặc kết thúc hành trình.\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ.\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối) + 100.000đ - 500.000đ (mua sắm đặc sản)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 06:20:09'),
(28, 2, 'Lịch trình 5 ngày - thiên nhiên, trekking', 5, 'thiên nhiên, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Buôn Ma Thuột: Cà phê và Văn hóa Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại Làng Cà phê Trung Nguyên\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, bắt đầu ngày mới với trải nghiệm cà phê đặc sắc là cách tuyệt vời để hòa mình vào văn hóa địa phương. Làng Cà phê Trung Nguyên là điểm đến nổi tiếng với không gian đẹp và đa dạng sản phẩm cà phê.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho sản phẩm/dịch vụ cà phê địa phương.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên, 163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (100k-150k/ngày) hoặc taxi/Grab.\",\n          \"price\": \"100.000đ - 200.000đ (đồ uống, mua sắm cà phê)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan và nạp năng lượng với các món ăn đặc trưng của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi tại Mường Thanh Luxury Buôn Ma Thuột (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột).\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab.\",\n          \"price\": \"70.000đ - 150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - Buôn làng Ê Đê truyền thống\",\n          \"reason\": \"Khám phá văn hóa bản địa của người Ê Đê, tìm hiểu kiến trúc nhà dài truyền thống và cuộc sống của người dân.\",\n          \"community_impact\": \"Dự kiến 50.000đ - 100.000đ mua quà lưu niệm từ người dân địa phương (nếu có).\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ trung tâm thành phố.\",\n          \"price\": \"Free (chi phí tự nguyện nếu mua sắm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Dạo chợ đêm Buôn Ma Thuột, thưởng thức ẩm thực đường phố\",\n          \"reason\": \"Trải nghiệm không khí sôi động của chợ đêm, khám phá các món ăn vặt và đặc sản địa phương.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho các hộ kinh doanh tại chợ đêm.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại Lee\'s House (55 đ.số 3, Cư Bur, TP. Buôn Ma Thuột).\",\n          \"address\": \"Khu vực Chợ đêm Buôn Ma Thuột, đường Ngô Quyền\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối, mua sắm linh tinh)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Thác Dray Nur và Hồ Ea Kao: Thiên nhiên hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Khám phá Thác Dray Nur\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước đẹp và hùng vĩ nhất Tây Nguyên, phù hợp với sở thích thiên nhiên và trekking nhẹ.\",\n          \"community_impact\": \"Dự kiến 50.000đ - 100.000đ chi phí vào cổng/dịch vụ.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab di chuyển khoảng 30km từ Buôn Ma Thuột.\",\n          \"price\": \"30.000đ - 50.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại hoặc tại nhà hàng gần thác\",\n          \"reason\": \"Nghỉ ngơi và thưởng thức bữa trưa sau hoạt động tham quan thác.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn/nhà hàng địa phương.\",\n          \"suggestion\": \"Tìm nhà hàng địa phương gần khu vực Thác Dray Nur. Nghỉ trưa tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"Khu vực gần Thác Dray Nur hoặc trở về Buôn Ma Thuột\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab.\",\n          \"price\": \"100.000đ - 200.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 8,\n          \"activity\": \"Thư giãn tại Hồ Ea Kao\",\n          \"reason\": \"Hồ Ea Kao là một không gian rộng lớn, thoáng đãng, thích hợp để thư giãn, ngắm cảnh hoàng hôn hoặc cắm trại nhẹ (nếu có thời gian).\",\n          \"community_impact\": \"Dự kiến 50.000đ cho đồ uống/snack từ các quán nhỏ ven hồ.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ trung tâm thành phố.\",\n          \"price\": \"Free (chi phí tự nguyện nếu mua đồ ăn uống)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức đặc sản Tây Nguyên và nghỉ ngơi\",\n          \"reason\": \"Kết thúc một ngày khám phá thiên nhiên bằng bữa tối ngon miệng và chuẩn bị cho hành trình tiếp theo.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ đêm tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"150.000đ - 250.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Hồ Lắk và Núi Đá Voi Mẹ: Huyền thoại M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt lớn thứ hai Việt Nam, gắn liền với văn hóa M\'nông. Trải nghiệm chèo thuyền độc mộc và tìm hiểu cuộc sống bản địa.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho dịch vụ thuyền độc mộc và hỗ trợ cộng đồng M\'nông.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô (khoảng 50km từ Buôn Ma Thuột).\",\n          \"price\": \"100.000đ - 200.000đ (thuê thuyền độc mộc, tham quan làng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Hồ Lắk, thưởng thức đặc sản địa phương\",\n          \"reason\": \"Nghỉ ngơi và thưởng thức các món ăn đặc trưng của vùng hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn/nhà hàng địa phương.\",\n          \"suggestion\": \"Tìm nhà hàng địa phương gần Hồ Lắk. Nghỉ trưa tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Khu vực Hồ Lắk, Huyện Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ\",\n          \"reason\": \"Núi Đá Voi Mẹ là tảng đá nguyên khối lớn nhất Việt Nam với nhiều truyền thuyết kỳ bí, phù hợp với sở thích thiên nhiên và khám phá.\",\n          \"community_impact\": \"Dự kiến 20.000đ - 50.000đ hỗ trợ người dân giữ gìn khu vực.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô từ Hồ Lắk (gần đó).\",\n          \"price\": \"Free (chi phí tự nguyện nếu có)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và trải nghiệm văn hóa cồng chiêng (nếu có) hoặc nghỉ ngơi\",\n          \"reason\": \"Kết thúc ngày khám phá văn hóa M\'nông và thiên nhiên vùng Lắk.\",\n          \"community_impact\": \"Dự kiến 200.000đ - 500.000đ cho bữa tối và trải nghiệm văn hóa địa phương (nếu có).\",\n          \"suggestion\": \"Ăn tối tại nhà hàng của Lak Tented Camp hoặc quán ăn ven Hồ Lắk. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Ven Hồ Lắk, Huyện Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"200.000đ - 500.000đ (ăn tối, chi phí cồng chiêng nếu có)\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Vườn Quốc gia Yok Đôn và Buôn Đôn: Rừng xanh và Voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 5,\n          \"activity\": \"Khám phá Vườn quốc gia Yok Đôn và trải nghiệm trekking\",\n          \"reason\": \"Vườn quốc gia Yok Đôn là điểm đến lý tưởng cho những người yêu thiên nhiên và trekking. Đây là cơ hội để khám phá hệ sinh thái rừng khộp độc đáo và tìm hiểu về công tác bảo tồn voi.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 500.000đ cho vé vào cổng và dịch vụ hướng dẫn/trekking có trách nhiệm.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô từ Buôn Ma Thuột (khoảng 40km).\",\n          \"price\": \"60.000đ (vé vào cổng), 100.000đ - 300.000đ (hướng dẫn viên trekking)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Vườn quốc gia Yok Đôn hoặc Buôn Đôn\",\n          \"reason\": \"Nghỉ ngơi và nạp năng lượng sau buổi sáng trekking.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Tìm nhà hàng địa phương gần Vườn quốc gia Yok Đôn hoặc tại Buôn Đôn. Nghỉ trưa tại các homestay/nhà nghỉ trong khu vực Buôn Đôn.\",\n          \"address\": \"Khu vực Vườn quốc gia Yok Đôn hoặc Buôn Đôn\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn và tìm hiểu văn hóa săn bắt, thuần dưỡng voi\",\n          \"reason\": \"Buôn Đôn nổi tiếng với nghề săn bắt và thuần dưỡng voi. Khám phá cầu treo, nhà dài và tìm hiểu văn hóa địa phương (ưu tiên các hoạt động không cưỡi voi để bảo vệ động vật).\",\n          \"community_impact\": \"Dự kiến 100.000đ - 200.000đ cho vé tham quan và mua sắm quà lưu niệm từ người dân địa phương.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ từ Vườn quốc gia Yok Đôn (gần đó).\",\n          \"price\": \"40.000đ - 60.000đ (vé tham quan cầu treo, nhà dài)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Trở về Buôn Ma Thuột, ăn tối và nghỉ ngơi\",\n          \"reason\": \"Kết thúc hành trình khám phá Buôn Đôn và chuẩn bị cho ngày cuối cùng.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn tối với Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ đêm tại Khách sạn Mường Thanh (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột).\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về Buôn Ma Thuột.\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 5,\n      \"title\": \"Cà phê cuối hành trình và mua sắm đặc sản\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức cà phê đặc biệt tại một quán cà phê địa phương và mua sắm đặc sản\",\n          \"reason\": \"Tận hưởng những giây phút cuối cùng ở thủ phủ cà phê, mua sắm cà phê và các đặc sản khác làm quà.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 500.000đ cho cà phê và đặc sản địa phương.\",\n          \"suggestion\": \"Thưởng thức cà phê tại SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột). Mua sắm đặc sản (cà phê, thịt nai khô, mật ong) tại Chợ Trung tâm Buôn Ma Thuột hoặc các cửa hàng đặc sản uy tín.\",\n          \"address\": \"87 Nguyễn Khuyến, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"50.000đ - 100.000đ (đồ uống), 200.000đ - 500.000đ (mua sắm)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và chuẩn bị ra sân bay/bến xe\",\n          \"reason\": \"Bữa trưa cuối cùng trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại một nhà hàng yêu thích ở Buôn Ma Thuột. Ví dụ: Quán Cà Te (140 Lê Thánh Tông).\",\n          \"address\": \"TP. Buôn Ma Thuột\",\n          \"transport\": \"Taxi/Grab ra sân bay Buôn Ma Thuột hoặc bến xe.\",\n          \"price\": \"100.000đ - 200.000đ (ăn trưa), 100.000đ - 200.000đ (di chuyển ra sân bay/bến xe)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": null,\n          \"activity\": \"Di chuyển ra sân bay hoặc bến xe, kết thúc hành trình\",\n          \"reason\": \"Kết thúc chuyến đi Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 0đ (ngoại trừ chi phí vận chuyển)\",\n          \"suggestion\": \"\",\n          \"address\": \"Sân bay Buôn Ma Thuột hoặc Bến xe Buôn Ma Thuột\",\n          \"transport\": \"Taxi/Grab.\",\n          \"price\": \"100.000đ - 200.000đ (di chuyển)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Kết thúc chuyến đi\",\n          \"reason\": \"...\",\n          \"community_impact\": \"...\",\n          \"suggestion\": \"\",\n          \"address\": \"\",\n          \"transport\": \"\",\n          \"price\": \"0đ\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-16 06:25:00');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(29, NULL, 'Lịch trình 5 ngày - ẩm thực, trekking', 5, 'ẩm thực, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Buôn Ma Thuột - Thủ phủ cà phê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột và thưởng thức cà phê nguyên chất tại Làng cà phê Trung Nguyên\",\n          \"reason\": \"Ưu tiên sở thích ẩm thực và trải nghiệm đặc sản địa phương ngay khi đến. Thưởng thức cà phê Buôn Ma Thuột nổi tiếng.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho cơ sở sản xuất cà phê địa phương.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột)\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi\",\n          \"price\": \"50.000đ (cho đồ uống)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản bún đỏ và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức món ăn địa phương nổi tiếng và nghỉ ngơi sau buổi sáng di chuyển và tham quan.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột). Nghỉ ngơi tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"50.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, tìm hiểu văn hóa Ê Đê và ngắm hoàng hôn\",\n          \"reason\": \"Khám phá văn hóa bản địa, gần trung tâm thành phố và có thể ngắm hoàng hôn tại buôn làng yên bình.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua quà lưu niệm từ người dân địa phương.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và dạo phố đêm Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương vào buổi tối và thư giãn.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn và dịch vụ địa phương.\",\n          \"suggestion\": \"Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"100.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá đại ngàn và các thác nước hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking và khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên\",\n          \"reason\": \"Ưu tiên sở thích trekking và trải nghiệm thiên nhiên hùng vĩ vào buổi sáng sớm khi không khí còn trong lành và mát mẻ.\",\n          \"community_impact\": \"Dự kiến 50.000đ vé vào cửa hỗ trợ công tác bảo tồn.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi\",\n          \"price\": \"30.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại hoặc tại nhà hàng gần thác\",\n          \"reason\": \"Nghỉ ngơi và bổ sung năng lượng sau buổi trekking.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn/dịch vụ địa phương.\",\n          \"suggestion\": \"Tìm quán ăn địa phương gần khu vực thác Dray Nur. Nghỉ ngơi tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"Gần Thác Dray Nur\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"100.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 3,\n          \"activity\": \"Tham quan Thác Dray Sáp, chiêm ngưỡng \'nước khói\'\",\n          \"reason\": \"Thác Dray Sáp nằm gần Dray Nur, tiện lợi di chuyển và tiếp tục khám phá vẻ đẹp tự nhiên của thác nước.\",\n          \"community_impact\": \"Dự kiến 30.000đ vé vào cửa.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi\",\n          \"price\": \"20.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và thư giãn\",\n          \"reason\": \"Nghỉ ngơi sau một ngày dài khám phá thác nước.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) cho các món ăn địa phương. Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"100.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Ngắm bình minh trên Hồ Lắk, đi thuyền độc mộc và tìm hiểu văn hóa M\'nông\",\n          \"reason\": \"Ưu tiên hoạt động buổi sáng sớm để ngắm bình minh tuyệt đẹp trên hồ, trải nghiệm thuyền độc mộc và khám phá văn hóa địa phương M\'nông.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho dịch vụ thuyền độc mộc và người dân bản địa.\",\n          \"suggestion\": \"Có thể ở lại qua đêm tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk) để thuận tiện ngắm bình minh.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi đi từ Buôn Ma Thuột\",\n          \"price\": \"200.000đ (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa các món đặc sản địa phương tại Hồ Lắk\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Tìm nhà hàng/quán ăn tại khu vực Hồ Lắk. Nghỉ ngơi tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"100.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ, khám phá truyền thuyết kỳ bí\",\n          \"reason\": \"Điểm đến độc đáo, gần Hồ Lắk, thích hợp cho việc khám phá và chụp ảnh vào buổi chiều.\",\n          \"community_impact\": \"Dự kiến 0đ.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và trải nghiệm không gian yên bình của Hồ Lắk\",\n          \"reason\": \"Thư giãn và tận hưởng không khí trong lành, yên bình của vùng hồ.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho bữa tối tại khu nghỉ dưỡng hoặc quán ăn địa phương.\",\n          \"suggestion\": \"Ăn tối tại nhà hàng của Lak Tented Camp (ven Hồ Lắk, Huyện Lắk). Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ\",\n          \"price\": \"150.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Thăm Vườn quốc gia Yok Đôn và Buôn Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 5,\n          \"activity\": \"Trekking và khám phá Vườn quốc gia Yok Đôn, tìm hiểu hệ sinh thái rừng\",\n          \"reason\": \"Ưu tiên sở thích trekking và khám phá thiên nhiên, sinh thái rừng vào buổi sáng sớm để tránh nắng gắt và có cơ hội quan sát động vật hoang dã.\",\n          \"community_impact\": \"Dự kiến 100.000đ vé vào cổng hỗ trợ công tác bảo tồn.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi\",\n          \"price\": \"60.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Buôn Đôn với các món ăn đặc sản\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi sau buổi trekking.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Tìm quán ăn gần khu vực Buôn Đôn. Nghỉ ngơi tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"100.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu văn hóa voi và cầu treo\",\n          \"reason\": \"Khám phá làng văn hóa nổi tiếng với nghề săn bắt và thuần dưỡng voi, gần Vườn quốc gia Yok Đôn.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho các dịch vụ và quà lưu niệm từ người dân địa phương.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"40.000đ (vé tham quan)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối tại TP. Buôn Ma Thuột và thư giãn\",\n          \"reason\": \"Trở về trung tâm để tiện cho việc di chuyển ngày hôm sau và thưởng thức ẩm thực đa dạng.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ đêm tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi\",\n          \"price\": \"80.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 5,\n      \"title\": \"Thác Thủy Tiên và mua sắm đặc sản\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 15,\n          \"activity\": \"Trekking và khám phá Thác Thủy Tiên, ngắm nhìn tuyệt tác thiên nhiên ba tầng\",\n          \"reason\": \"Tiếp tục sở thích trekking và khám phá vẻ đẹp thiên nhiên hùng vĩ của Đắk Lắk vào buổi sáng.\",\n          \"community_impact\": \"Dự kiến 30.000đ vé vào cổng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Krông Năng, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi\",\n          \"price\": \"20.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại địa phương và nghỉ ngơi\",\n          \"reason\": \"Nghỉ ngơi và nạp năng lượng sau buổi trekking.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Tìm quán ăn địa phương gần Thác Thủy Tiên hoặc trên đường về Buôn Ma Thuột. Nghỉ ngơi tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"Krông Năng, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"80.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": null,\n          \"activity\": \"Mua sắm đặc sản Đắk Lắk làm quà\",\n          \"reason\": \"Mua sắm các sản phẩm địa phương nổi tiếng như cà phê, thịt nai khô, mật tự nhiên.\",\n          \"community_impact\": \"Dự kiến 500.000đ cho các sản phẩm OCOP và cửa hàng đặc sản địa phương.\",\n          \"suggestion\": \"Chợ Buôn Ma Thuột hoặc các cửa hàng đặc sản uy tín tại TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ\",\n          \"price\": \"Tùy chọn mua sắm\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối chia tay và chuẩn bị khởi hành\",\n          \"reason\": \"Thưởng thức bữa ăn cuối cùng tại Đắk Lắk và chuẩn bị cho chuyến đi tiếp theo hoặc về nhà.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) để thưởng thức cà phê và đồ ăn nhẹ. Nghỉ đêm tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột) hoặc di chuyển ra sân bay/bến xe.\",\n          \"address\": \"87 Nguyễn Khuyến, TP. Buôn Ma Thuột\",\n          \"transport\": \"Taxi hoặc xe máy\",\n          \"price\": \"150.000đ (ăn tối)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:25:02'),
(30, NULL, 'Lịch trình 5 ngày - trekking, chụp ảnh', 5, 'trekking, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Buôn Ma Thuột: Cà phê và Văn hóa Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại Làng Cà phê Trung Nguyên\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, Làng Cà phê Trung Nguyên là điểm đến biểu tượng để thưởng thức cà phê và tìm hiểu về quy trình sản xuất, rất phù hợp cho du khách thích khám phá văn hóa và ẩm thực.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho sản phẩm/dịch vụ tại Làng Cà phê Trung Nguyên.\",\n          \"suggestion\": \"Làng Cà phê Trung Nguyên, 163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (150.000đ/ngày) hoặc taxi/Grab để di chuyển linh hoạt.\",\n          \"price\": \"50.000đ - 100.000đ (chi phí cà phê và tham quan)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức bún đỏ đặc sản và nghỉ ngơi\",\n          \"reason\": \"Bún đỏ là món ăn nổi tiếng của Buôn Ma Thuột, mang hương vị đặc trưng. Nghỉ ngơi tại khách sạn để lấy lại sức cho buổi chiều.\",\n          \"community_impact\": \"Dự kiến 80.000đ cho quán ăn địa phương và 300.000đ cho khách sạn.\",\n          \"suggestion\": \"Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Khách sạn Sài Gòn - Ban Mê, 01-03 Phan Chu Trinh, TP. Buôn Ma Thuột.\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy đến quán ăn, sau đó về khách sạn nghỉ ngơi.\",\n          \"price\": \"50.000đ (bún đỏ) + 500.000đ (khách sạn/homestay)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột\",\n          \"reason\": \"Khám phá kiến trúc nhà dài truyền thống và văn hóa Ê Đê độc đáo, rất phù hợp cho du khách muốn tìm hiểu văn hóa và chụp ảnh. Địa điểm gần trung tâm thành phố, tiện di chuyển.\",\n          \"community_impact\": \"Dự kiến 50.000đ hỗ trợ cộng đồng/mua sắm sản phẩm lưu niệm.\",\n          \"suggestion\": \"Không có gợi ý cụ thể, buôn làng là chính.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 10-15 phút từ trung tâm).\",\n          \"price\": \"Free (tham quan) + 50.000đ (mua sắm nhỏ)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên và nghỉ ngơi\",\n          \"reason\": \"Khám phá thêm các món ăn đặc sản vùng miền. Nghỉ ngơi tại khách sạn để chuẩn bị cho ngày hôm sau.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương và 500.000đ cho khách sạn.\",\n          \"suggestion\": \"Quán Cà Te, 140 Lê Thánh Tông, TP. Buôn Ma Thuột. Khách sạn Mường Thanh, 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột.\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối) + 500.000đ (ngủ đêm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình đại ngàn: Thác nước hùng vĩ và Rừng quốc gia\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking và khám phá Thác Dray Nur hùng vĩ\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước đẹp và hùng vĩ nhất Tây Nguyên, rất phù hợp cho du khách thích trekking và chụp ảnh. Gần thành phố, tiện di chuyển.\",\n          \"community_impact\": \"Dự kiến 30.000đ cho vé vào cửa.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab (khoảng 30km từ Buôn Ma Thuột).\",\n          \"price\": \"30.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi tại khu vực gần thác\",\n          \"reason\": \"Ăn trưa với các món ăn địa phương sau khi trekking. Nghỉ ngơi để tiếp tục hành trình.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương. Có thể chọn nghỉ tại homestay gần thác.\",\n          \"suggestion\": \"Các quán ăn nhỏ tại khu vực Thác Dray Nur. Homestay Cư H\'Lăm Restaurant & Homestay, Ea Pốk, Buôn Đôn.\",\n          \"address\": \"Khu vực Thác Dray Nur, Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy trong khu vực.\",\n          \"price\": \"80.000đ - 150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 5,\n          \"activity\": \"Khám phá Vườn quốc gia Yok Đôn, tìm hiểu về voi rừng và hệ sinh thái\",\n          \"reason\": \"Vườn quốc gia Yok Đôn là nơi sinh sống của voi rừng và là vườn quốc gia lớn nhất Việt Nam, mang đến trải nghiệm thiên nhiên độc đáo, rất phù hợp cho những người yêu sinh thái và chụp ảnh. Có các hoạt động trekking nhẹ trong rừng.\",\n          \"community_impact\": \"Dự kiến 40.000đ cho vé vào cửa và 500.000đ cho dịch vụ hướng dẫn/thuê xe nếu có.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 40km từ Thác Dray Nur).\",\n          \"price\": \"40.000đ (vé vào cổng) + 300.000đ - 500.000đ (nếu có thuê hướng dẫn/xe đặc biệt)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và nghỉ đêm tại Buôn Ma Thuột\",\n          \"reason\": \"Quay về trung tâm Buôn Ma Thuột để tiện nghỉ ngơi và chuẩn bị cho ngày tiếp theo.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương và 500.000đ cho khách sạn.\",\n          \"suggestion\": \"Phở hai tô 52, 52 Ngô Quyền, TP. Buôn Ma Thuột. Khách sạn Elephants, 142 Hai Bà Trưng, TP. Buôn Ma Thuột.\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về Buôn Ma Thuột.\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối) + 500.000đ (ngủ đêm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Văn hóa Hồ Lắk và Núi Đá Voi kỳ bí\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk, đi thuyền độc mộc và tìm hiểu văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt lớn thứ 2 Việt Nam, gắn liền với văn hóa M\'nông. Trải nghiệm thuyền độc mộc và chụp ảnh khung cảnh yên bình là điểm nhấn. Phù hợp cho du khách thích thiên nhiên, văn hóa và chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho người dân địa phương (chèo thuyền độc mộc, mua sắm thổ cẩm).\",\n          \"suggestion\": \"Có thể chọn nghỉ dưỡng tại Lak Tented Camp, ven Hồ Lắk, nếu muốn trải nghiệm sâu hơn.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab (khoảng 50km từ Buôn Ma Thuột).\",\n          \"price\": \"50.000đ (vé tham quan) + 150.000đ - 200.000đ (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với đặc sản địa phương ven Hồ Lắk và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức các món ăn đặc sản của người M\'nông và nghỉ ngơi tại khu vực hồ.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Các quán ăn ven Hồ Lắk. Có thể nghỉ ngơi tại Lak Tented Camp (nếu đã đặt phòng).\",\n          \"address\": \"Khu vực Hồ Lắk, Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy trong khu vực.\",\n          \"price\": \"100.000đ - 200.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ và lắng nghe truyền thuyết\",\n          \"reason\": \"Núi Đá Voi Mẹ là một tảng đá nguyên khối khổng lồ với truyền thuyết kỳ bí, rất lý tưởng để trekking nhẹ, chụp ảnh và chiêm ngưỡng toàn cảnh. Gần Hồ Lắk, tiện di chuyển.\",\n          \"community_impact\": \"Dự kiến free.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 10km từ Hồ Lắk).\",\n          \"price\": \"Free\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và nghỉ đêm tại Buôn Ma Thuột\",\n          \"reason\": \"Kết thúc hành trình khám phá Lắk và trở về trung tâm thành phố để tiện nghỉ ngơi, chuẩn bị cho ngày tiếp theo di chuyển đến Phú Yên.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương và 500.000đ cho khách sạn.\",\n          \"suggestion\": \"Bánh ướt chồng dĩa 45, 45 Lê Thánh Tông, TP. Buôn Ma Thuột. Khách sạn Hai Bà Trưng, 8 Hai Bà Trưng, TP. Buôn Ma Thuột.\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về Buôn Ma Thuột.\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối) + 500.000đ (ngủ đêm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Chuyển mình ra biển: Từ Tây Nguyên đến Phú Yên\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": null,\n          \"activity\": \"Di chuyển từ Buôn Ma Thuột đi Tuy Hòa (Phú Yên)\",\n          \"reason\": \"Bắt đầu hành trình chuyển đổi cảnh quan từ rừng núi Tây Nguyên hùng vĩ sang biển cả bao la của Phú Yên. Chọn phương tiện phù hợp với sức khỏe và thời gian.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 400.000đ cho nhà xe/tài xế.\",\n          \"suggestion\": \"Xe khách hoặc thuê xe riêng (khoảng 4-5 tiếng di chuyển).\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Xe khách giường nằm hoặc xe dịch vụ riêng.\",\n          \"price\": \"200.000đ - 400.000đ (chi phí di chuyển)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Phú Yên và nhận phòng khách sạn tại Tuy Hòa\",\n          \"reason\": \"Thưởng thức các món hải sản tươi ngon của Phú Yên và nghỉ ngơi sau hành trình di chuyển dài.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn hải sản và 500.000đ cho khách sạn.\",\n          \"suggestion\": \"Quán hải sản ven biển Tuy Hòa. Khách sạn Kaya Hotel, 238 Hùng Vương, Tuy Hòa, Phú Yên.\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Taxi/Grab từ bến xe/ga tàu đến khách sạn và quán ăn.\",\n          \"price\": \"150.000đ - 300.000đ (ăn trưa) + 500.000đ (khách sạn/homestay)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 13,\n          \"activity\": \"Tham quan Tháp Nghinh Phong - biểu tượng mới của Tuy Hòa và dạo biển\",\n          \"reason\": \"Tháp Nghinh Phong là biểu tượng kiến trúc độc đáo, rất phù hợp để chụp ảnh. Sau đó, dạo biển Tuy Hòa để tận hưởng không khí biển cả.\",\n          \"community_impact\": \"Dự kiến free.\",\n          \"suggestion\": \"Tháp Nghinh Phong, Tuy Hòa, Phú Yên\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Taxi/Grab hoặc xe máy thuê (100.000đ/ngày).\",\n          \"price\": \"Free\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức hải sản tươi sống và dạo phố biển Tuy Hòa\",\n          \"reason\": \"Phú Yên nổi tiếng với hải sản tươi ngon. Dạo phố biển vào buổi tối để cảm nhận nhịp sống của thành phố biển.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho quán hải sản địa phương và 500.000đ cho khách sạn.\",\n          \"suggestion\": \"Quán hải sản đường Độc Lập hoặc Lê Duẩn, Tuy Hòa. Khách sạn Sala Grand Tuy Hoa, 51 Độc Lập, Tuy Hòa, Phú Yên.\",\n          \"address\": \"Độc Lập, Tuy Hòa, Phú Yên\",\n          \"transport\": \"Đi bộ hoặc taxi/Grab.\",\n          \"price\": \"200.000đ - 400.000đ (ăn tối) + 500.000đ (ngủ đêm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 5,\n      \"title\": \"Kiệt tác thiên nhiên và Bình minh đầu tiên\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 12,\n          \"activity\": \"Đón bình minh tại Bãi Môn - Mũi Điện\",\n          \"reason\": \"Đón bình minh đầu tiên trên đất liền Việt Nam là một trải nghiệm độc đáo và đáng nhớ, rất lý tưởng cho du khách thích chụp ảnh và khám phá.\",\n          \"community_impact\": \"Dự kiến 20.000đ cho phí tham quan.\",\n          \"suggestion\": \"\",\n          \"address\": \"chưa cập nhật\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab (khoảng 35km từ Tuy Hòa, cần xuất phát rất sớm).\",\n          \"price\": \"20.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Vịnh Vũng Rô và nghỉ ngơi\",\n          \"reason\": \"Sau khi đón bình minh, di chuyển đến khu vực Vịnh Vũng Rô để ăn trưa và nghỉ ngơi trước khi tiếp tục hành trình.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Các quán ăn hải sản tại Vịnh Vũng Rô.\",\n          \"address\": \"Khu vực Vịnh Vũng Rô, Phú Yên\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"100.000đ - 250.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 9,\n          \"activity\": \"Tham quan Gành Đá Đĩa - Kiệt tác thiên nhiên độc đáo\",\n          \"reason\": \"Gành Đá Đĩa là một trong những kiệt tác thiên nhiên độc đáo nhất Việt Nam với các khối đá hình lăng trụ, rất lý tưởng để chụp ảnh và chiêm ngưỡng cảnh đẹp. Đây là điểm nhấn không thể bỏ qua ở Phú Yên.\",\n          \"community_impact\": \"Dự kiến 20.000đ cho vé vào cửa.\",\n          \"suggestion\": \"\",\n          \"address\": \"chưa cập nhật\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab (khoảng 50km từ Tuy Hòa, theo hướng Bắc).\",\n          \"price\": \"20.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và chuẩn bị kết thúc chuyến đi\",\n          \"reason\": \"Thưởng thức bữa tối cuối cùng với đặc sản Phú Yên và chuẩn bị cho việc trở về.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Quán ăn tại Tuy Hòa. Có thể chọn mua quà đặc sản địa phương (hải sản khô, nước mắm).\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Taxi/Grab.\",\n          \"price\": \"150.000đ - 300.000đ (ăn tối)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:30:41'),
(31, NULL, 'Lịch trình 5 ngày - văn hoá, chụp ảnh', 5, 'văn hoá, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Buôn Làng và Cà phê Đặc trưng\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột.\",\n          \"reason\": \"Buôn Akô Dhông là buôn làng Ê Đê lâu đời, còn giữ nguyên nét kiến trúc nhà dài truyền thống và không gian văn hóa đặc sắc, lý tưởng để chụp ảnh và tìm hiểu văn hóa bản địa một cách chân thực.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho sản phẩm thủ công/dịch vụ văn hóa của người dân.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab đến buôn Akô Dhông (khoảng 15-20 phút từ trung tâm).\",\n          \"price\": \"50.000đ (phí gửi xe nếu có, hoặc tip cho người dân nếu có tương tác)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi.\",\n          \"reason\": \"Trải nghiệm hương vị ẩm thực đặc trưng của Buôn Ma Thuột và nghỉ ngơi sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa Cà phê Buôn Ma Thuột và tham quan bảo tàng cà phê.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, khám phá văn hóa cà phê sẽ giúp bạn hiểu sâu hơn về một phần quan trọng của địa phương. Làng cà phê Trung Nguyên là điểm đến nổi bật.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho sản phẩm cà phê địa phương.\",\n          \"suggestion\": \"Tham quan Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab đến Làng cà phê Trung Nguyên.\",\n          \"price\": \"50.000đ - 100.000đ (chi phí đồ uống, quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và tự do khám phá Buôn Ma Thuột về đêm.\",\n          \"reason\": \"Thưởng thức đặc sản Buôn Ma Thuột và khám phá không khí thành phố về đêm.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và 500.000đ cho homestay.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ đêm tại Lee\'s House (55 đ.số 3, Cư Bur, TP. Buôn Ma Thuột).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab.\",\n          \"price\": \"200.000đ (ăn tối) + 500.000đ (lưu trú)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình khám phá Hồ Lắk và Núi Đá Voi Mẹ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Tham quan Hồ Lắk, trải nghiệm chèo thuyền độc mộc và tìm hiểu văn hóa M\'nông.\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, mang vẻ đẹp hoang sơ và văn hóa M\'nông độc đáo, rất phù hợp cho những ai muốn khám phá văn hóa và chụp ảnh phong cảnh độc đáo. Thuyền độc mộc là trải nghiệm hiếm có.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho dịch vụ thuyền độc mộc của người dân địa phương.\",\n          \"suggestion\": \"Tìm đến các buôn làng ven hồ như Buôn Jun, Buôn Lê để trải nghiệm dịch vụ thuyền độc mộc và mua sắm thổ cẩm.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc ô tô di chuyển từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km).\",\n          \"price\": \"30.000đ (vé vào cổng nếu có) + 150.000đ - 250.000đ (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với đặc sản địa phương tại Hồ Lắk và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức ẩm thực đặc trưng của vùng Hồ Lắk và nghỉ ngơi trong không gian yên bình.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Cư H\'Lăm Restaurant & Homestay (xã Ea Pốk, Huyện Cư M\'gar, gần Hồ Lắk).\",\n          \"address\": \"Ea Pốk, Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc đi bộ quanh khu vực hồ.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ - tảng đá nguyên khối lớn nhất Việt Nam, gắn liền với truyền thuyết bí ẩn.\",\n          \"reason\": \"Núi Đá Voi Mẹ là một điểm đến ít người biết đến, độc đáo với vẻ đẹp hùng vĩ và câu chuyện văn hóa thú vị, lý tưởng cho những ai muốn khám phá \'góc khuất\' và chụp ảnh độc đáo.\",\n          \"community_impact\": \"Dự kiến 50.000đ hỗ trợ cộng đồng địa phương nếu có.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy từ Hồ Lắk đến Núi Đá Voi Mẹ (khoảng 10-15 phút).\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và nghỉ ngơi tại Hồ Lắk.\",\n          \"reason\": \"Trải nghiệm không gian yên tĩnh, hòa mình vào thiên nhiên Hồ Lắk vào buổi tối.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và 600.000đ cho homestay.\",\n          \"suggestion\": \"Ăn tối tại nhà hàng địa phương gần Hồ Lắk. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk, Đắk Lắk) để trải nghiệm không gian độc đáo.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy gần khu vực lưu trú.\",\n          \"price\": \"200.000đ (ăn tối) + 600.000đ (lưu trú)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Khám phá Buôn Đôn và Thác Dray Nur hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Khám phá Buôn Đôn - làng văn hóa nổi tiếng với nghề săn bắt và thuần dưỡng voi.\",\n          \"reason\": \"Buôn Đôn mang đậm nét văn hóa Tây Nguyên, với những ngôi nhà dài truyền thống, cầu treo và câu chuyện về voi rừng. Đây là cơ hội để bạn tương tác với văn hóa địa phương và chụp những bức ảnh độc đáo.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho dịch vụ tham quan/sản phẩm thủ công của người dân.\",\n          \"suggestion\": \"Thăm quan Nhà sàn cổ, Cầu treo Buôn Đôn, thưởng thức cơm lam, gà nướng.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô từ Hồ Lắk về Buôn Đôn (khoảng 60-70km).\",\n          \"price\": \"50.000đ - 100.000đ (vé tham quan cầu treo, nhà sàn)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Buôn Đôn và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức đặc sản Buôn Đôn như gà nướng, cơm lam, cá lăng.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại các nhà hàng dọc đường vào Buôn Đôn.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur - một trong những thác nước hùng vĩ nhất Tây Nguyên.\",\n          \"reason\": \"Thác Dray Nur mang vẻ đẹp hoang sơ, hùng vĩ, tạo nên khung cảnh ấn tượng cho những bức ảnh. Trải nghiệm trekking nhẹ nhàng khám phá xung quanh thác cũng rất thú vị.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho dịch vụ địa phương (nếu có).\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy từ Buôn Đôn đến Thác Dray Nur (khoảng 40-50km).\",\n          \"price\": \"30.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Trở về Buôn Ma Thuột, ăn tối và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức ẩm thực thành phố và chuẩn bị cho chuyến đi Phú Yên vào ngày hôm sau.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và 500.000đ cho khách sạn.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại Khách sạn Hai Bà Trưng (8 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab về trung tâm Buôn Ma Thuột.\",\n          \"price\": \"200.000đ (ăn tối) + 500.000đ (lưu trú)\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Chuyển tiếp đến Phú Yên và khám phá Gành Đá Đĩa\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": null,\n          \"activity\": \"Di chuyển từ Buôn Ma Thuột đến Phú Yên.\",\n          \"reason\": \"Bắt đầu hành trình khám phá biển Phú Yên.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho xe khách/xe riêng.\",\n          \"suggestion\": \"Đặt vé xe khách giường nằm từ Buôn Ma Thuột đi Tuy Hòa (Phú Yên).\",\n          \"address\": \"Bến xe Buôn Ma Thuột\",\n          \"transport\": \"Xe khách giường nằm hoặc xe riêng.\",\n          \"price\": \"200.000đ - 250.000đ (vé xe khách)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Tuy Hòa và nhận phòng khách sạn.\",\n          \"reason\": \"Nghỉ ngơi sau chuyến đi và thưởng thức ẩm thực biển Phú Yên.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng hải sản ở Tuy Hòa. Nhận phòng Khách sạn Sài Gòn - Ban Mê (01-03 Phan Chu Trinh, Tuy Hòa) hoặc tương đương.\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Taxi/Grab từ bến xe đến khách sạn.\",\n          \"price\": \"150.000đ (ăn trưa) + 500.000đ (lưu trú)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 9,\n          \"activity\": \"Tham quan Gành Đá Đĩa - kiệt tác thiên nhiên độc đáo của Phú Yên.\",\n          \"reason\": \"Gành Đá Đĩa là một điểm đến \'độc nhất vô nhị\' với các khối đá hình lăng trụ xếp chồng lên nhau, tạo nên khung cảnh ấn tượng cho việc chụp ảnh và khám phá địa chất.\",\n          \"community_impact\": \"Dự kiến 30.000đ cho phí vào cổng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Tuy An, Phú Yên\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô từ Tuy Hòa đến Gành Đá Đĩa (khoảng 30-40km).\",\n          \"price\": \"20.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối hải sản tươi sống và dạo biển Tuy Hòa.\",\n          \"reason\": \"Thưởng thức hải sản tươi ngon của Phú Yên và tận hưởng không khí biển về đêm.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho quán ăn hải sản.\",\n          \"suggestion\": \"Ăn tối tại các quán hải sản ven biển Tuy Hòa. Nghỉ đêm tại khách sạn đã nhận phòng.\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"300.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 5,\n      \"title\": \"Đón Bình Minh Mũi Điện và khám phá Tháp Nghinh Phong\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 12,\n          \"activity\": \"Đón bình minh đầu tiên trên đất liền Việt Nam tại Bãi Môn - Mũi Điện (Hải đăng Đại Lãnh).\",\n          \"reason\": \"Trải nghiệm độc đáo này mang lại cảm giác chinh phục và những khoảnh khắc tuyệt đẹp để chụp ảnh bình minh trên biển, một trải nghiệm ít người có được.\",\n          \"community_impact\": \"Dự kiến 20.000đ cho phí bảo trì.\",\n          \"suggestion\": \"\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô từ Tuy Hòa đến Mũi Điện (khoảng 30km, nên đi từ 4h sáng).\",\n          \"price\": \"20.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Phú Yên và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi sau buổi sáng sớm.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại các quán ăn gần trung tâm Tuy Hòa. Kiểm tra hành lý và chuẩn bị ra sân bay/bến xe.\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 13,\n          \"activity\": \"Tham quan Tháp Nghinh Phong - biểu tượng kiến trúc độc đáo của Tuy Hòa.\",\n          \"reason\": \"Tháp Nghinh Phong là một công trình kiến trúc hiện đại, lấy cảm hứng từ Gành Đá Đĩa, rất phù hợp để chụp ảnh và là điểm check-in mới lạ của thành phố.\",\n          \"community_impact\": \"Miễn phí.\",\n          \"suggestion\": \"\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc đi bộ từ trung tâm Tuy Hòa.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Kết thúc hành trình, di chuyển ra sân bay/bến xe.\",\n          \"reason\": \"Khép lại chuyến đi với nhiều trải nghiệm văn hóa và thiên nhiên độc đáo.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho taxi/Grab ra sân bay/bến xe.\",\n          \"suggestion\": \"Di chuyển ra sân bay Tuy Hòa hoặc bến xe Tuy Hòa để về lại điểm xuất phát.\",\n          \"address\": \"Tuy Hòa, Phú Yên\",\n          \"transport\": \"Taxi/Grab.\",\n          \"price\": \"100.000đ (di chuyển ra sân bay/bến xe)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:33:37');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(32, NULL, 'Lịch trình 4 ngày - trekking, chụp ảnh', 4, 'trekking, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Thác nước hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Khám phá văn hóa cà phê Buôn Ma Thuột. Thăm quan Bảo tàng Cà phê và thưởng thức hương vị cà phê đặc trưng.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, phù hợp để tìm hiểu văn hóa địa phương và thưởng thức đặc sản. Chi phí thấp, thoải mái cho buổi sáng đầu tiên.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho nông sản địa phương/quán cà phê.\",\n          \"suggestion\": \"Thưởng thức cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ) hoặc Arul Coffee (17 Trần Nhật Duật).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (150.000đ/ngày) hoặc taxi để di chuyển giữa các quán cà phê.\",\n          \"price\": \"50.000đ - 100.000đ (phí tham quan bảo tàng nếu có, cà phê)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Buôn Ma Thuột và nghỉ ngơi.\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan, chuẩn bị năng lượng cho buổi chiều trekking.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn bún đỏ tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi tại Mường Thanh Luxury Buôn Ma Thuột (81 Nguyễn Tất Thành).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi.\",\n          \"price\": \"80.000đ - 150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking và khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Chụp ảnh phong cảnh và trải nghiệm không khí trong lành.\",\n          \"reason\": \"Thác Dray Nur là điểm đến lý tưởng cho sở thích trekking và chụp ảnh, mang lại trải nghiệm thiên nhiên hùng vĩ.\",\n          \"community_impact\": \"Dự kiến 30.000đ cho phí vào cổng ủng hộ du lịch địa phương.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô thuê từ Buôn Ma Thuột (khoảng 30km).\",\n          \"price\": \"30.000đ (vé vào cổng) + 50.000đ (xăng xe)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và trải nghiệm ẩm thực địa phương tại Buôn Ma Thuột. Tự do dạo phố hoặc nghỉ ngơi.\",\n          \"reason\": \"Thư giãn sau ngày dài tham quan, thưởng thức các món ăn đặc trưng.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và khách sạn địa phương.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông). Nghỉ đêm tại Khách sạn Sài Gòn - Ban Mê (01-03 Phan Chu Trinh).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc đi bộ.\",\n          \"price\": \"100.000đ - 250.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình khám phá văn hóa voi và hồ nước lớn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu văn hóa săn bắt và thuần dưỡng voi của người Ê Đê và M\'nông. Trải nghiệm cầu treo Buôn Đôn.\",\n          \"reason\": \"Buôn Đôn mang đậm bản sắc văn hóa Tây Nguyên, phù hợp với sở thích khám phá văn hóa. Gần Vườn Quốc gia Yok Đôn.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho các dịch vụ tại buôn làng (cầu treo, tham quan nhà dài).\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô thuê từ Buôn Ma Thuột (khoảng 40km).\",\n          \"price\": \"40.000đ (vé vào cổng) + 30.000đ (cầu treo)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Buôn Đôn với các món ăn đặc sản rừng núi và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương sau buổi sáng tham quan, nghỉ ngơi lấy sức.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Tìm nhà hàng gần khu vực Buôn Đôn phục vụ các món cá sông, gà nướng. Nghỉ ngơi tại Cư H\'Lăm Restaurant & Homestay (Ea Pốk) nếu muốn trải nghiệm sinh thái hoặc Elephants Hotel (142 Hai Bà Trưng) nếu về lại trung tâm.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Trải nghiệm thuyền độc mộc trên hồ, tìm hiểu văn hóa M\'nông và chụp ảnh hoàng hôn.\",\n          \"reason\": \"Hồ Lắk mang vẻ đẹp thiên nhiên yên bình, là nơi lý tưởng để chụp ảnh và tìm hiểu văn hóa dân tộc. Tối ưu lộ trình di chuyển theo vòng cung.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho dịch vụ thuyền độc mộc của người dân địa phương.\",\n          \"suggestion\": \"Trải nghiệm thuyền độc mộc của người dân M\'nông. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk) để có trải nghiệm độc đáo.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô thuê từ Buôn Đôn (khoảng 60km, đi theo đường ven hồ để ngắm cảnh).\",\n          \"price\": \"Miễn phí (tham quan hồ) + 50.000đ - 100.000đ (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối tại Hồ Lắk, thưởng thức các món ăn địa phương và nghỉ ngơi tại homestay ven hồ.\",\n          \"reason\": \"Trải nghiệm ẩm thực và không gian yên bình của Hồ Lắk. Chuẩn bị cho ngày tiếp theo.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng và homestay địa phương.\",\n          \"suggestion\": \"Ăn tối tại nhà hàng của Lak Tented Camp hoặc các quán ăn ven hồ. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy trong khu vực Hồ Lắk.\",\n          \"price\": \"150.000đ - 300.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Chinh phục núi đá Voi Mẹ và thác Thủy Tiên\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ, tảng đá nguyên khối lớn nhất Việt Nam. Trải nghiệm leo núi và chụp ảnh toàn cảnh khu vực Hồ Lắk.\",\n          \"reason\": \"Núi Đá Voi Mẹ là điểm đến độc đáo cho sở thích trekking và chụp ảnh, mang lại tầm nhìn tuyệt đẹp. Gần Hồ Lắk, tối ưu di chuyển.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho phí gửi xe/hỗ trợ người dân địa phương.\",\n          \"suggestion\": \"Mang giày thể thao thoải mái và nước uống.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy từ Hồ Lắk (khoảng 10km).\",\n          \"price\": \"Miễn phí (tham quan) + 10.000đ (gửi xe)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Lắk hoặc trên đường di chuyển đến Krông Năng. Nghỉ ngơi.\",\n          \"reason\": \"Bổ sung năng lượng sau buổi sáng leo núi, chuẩn bị cho buổi chiều khám phá thác.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Tìm quán ăn ven đường hoặc quay lại khu vực Hồ Lắk để ăn trưa. Nếu có thể, chuẩn bị đồ ăn nhẹ để picnic.\",\n          \"address\": \"Khu vực Lắk\",\n          \"transport\": \"Xe máy.\",\n          \"price\": \"80.000đ - 150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 15,\n          \"activity\": \"Thăm quan Thác Thủy Tiên, tuyệt tác thiên nhiên ba tầng giữa chốn đại ngàn Krông Năng. Tắm mát và chụp ảnh phong cảnh.\",\n          \"reason\": \"Thác Thủy Tiên mang vẻ đẹp hoang sơ, hùng vĩ, phù hợp với sở thích trekking và chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 20.000đ cho phí vệ sinh/ủng hộ địa phương.\",\n          \"suggestion\": \"Mang theo đồ bơi và khăn tắm nếu muốn trải nghiệm tắm thác. Cẩn thận khi di chuyển dưới thác.\",\n          \"address\": \"Krông Năng, Đắk Lắk\",\n          \"transport\": \"Xe máy từ Lắk đến Krông Năng (khoảng 70km).\",\n          \"price\": \"Miễn phí (tham quan) + 10.000đ (gửi xe)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Quay về Buôn Ma Thuột, ăn tối và nghỉ ngơi tại trung tâm thành phố.\",\n          \"reason\": \"Kết thúc hành trình khám phá thiên nhiên, quay về trung tâm để thuận tiện cho việc di chuyển vào ngày cuối.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng và khách sạn địa phương.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô từ Krông Năng về Buôn Ma Thuột (khoảng 60km).\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Văn hóa Ê Đê và mua sắm đặc sản\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa sinh hoạt của người Ê Đê. Chụp ảnh lưu niệm.\",\n          \"reason\": \"Buôn Akô Dhông gần trung tâm, dễ dàng di chuyển, mang lại cái nhìn sâu sắc về văn hóa Ê Đê. Phù hợp cho sở thích chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho quà lưu niệm/ủng hộ văn hóa địa phương.\",\n          \"suggestion\": \"Thăm nhà dài cổ, tìm hiểu về dệt thổ cẩm.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (tham quan)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Buôn Ma Thuột và mua sắm đặc sản làm quà.\",\n          \"reason\": \"Thưởng thức bữa trưa cuối cùng tại Buôn Ma Thuột và mua sắm quà lưu niệm trước khi rời đi.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho quán ăn và cửa hàng đặc sản địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông). Mua sắm cà phê, thịt nai khô, mật tự nhiên tại các cửa hàng đặc sản uy tín trong thành phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi.\",\n          \"price\": \"100.000đ - 500.000đ (ăn trưa và mua sắm quà)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": null,\n          \"activity\": \"Tự do khám phá thêm hoặc di chuyển ra sân bay/bến xe, kết thúc hành trình.\",\n          \"reason\": \"Tùy chọn hoạt động theo lịch trình cá nhân hoặc chuẩn bị rời đi.\",\n          \"community_impact\": \"0\",\n          \"suggestion\": \"\",\n          \"address\": \"\",\n          \"transport\": \"Taxi hoặc xe ôm ra sân bay/bến xe.\",\n          \"price\": \"Tùy thuộc vào phương tiện di chuyển\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Kết thúc hành trình.\",\n          \"reason\": \"\",\n          \"community_impact\": \"0\",\n          \"suggestion\": \"\",\n          \"address\": \"\",\n          \"transport\": \"\",\n          \"price\": \"0\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:34:06'),
(33, NULL, 'Lịch trình 2 ngày - ẩm thực', 2, 'ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hương vị cà phê Buôn Ma Thuột và khám phá văn hóa Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức cà phê Buôn Ma Thuột và khám phá văn hóa cà phê\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, bắt đầu ngày mới với ly cà phê đậm chất Tây Nguyên là trải nghiệm không thể bỏ qua, đặc biệt phù hợp với sở thích ẩm thực. Buổi sáng sớm là thời điểm lý tưởng để cảm nhận không khí trong lành và sự yên bình của các quán cà phê.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán cà phê địa phương.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên, 163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"50.000đ - 100.000đ (chi phí cà phê)\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, tìm hiểu văn hóa Ê Đê\",\n          \"reason\": \"Tiếp nối trải nghiệm văn hóa, Buôn Akô Dhông là buôn làng Ê Đê lâu đời và đẹp nhất, giúp du khách hiểu sâu hơn về nếp sống, kiến trúc nhà dài truyền thống của người bản địa. Địa điểm gần trung tâm thành phố, tiện di chuyển sau khi uống cà phê.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho sản phẩm thủ công địa phương (nếu có).\",\n          \"suggestion\": \"Có thể mua các sản phẩm dệt thổ cẩm truyền thống tại buôn làng.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Buôn Ma Thuột và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Bún đỏ cô Thu, Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột. Nghỉ ngơi tại Mường Thanh Luxury Buôn Ma Thuột, 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"80.000đ - 150.000đ (chi phí ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 8,\n          \"activity\": \"Thư giãn tại Hồ Ea Kao, ngắm hoàng hôn\",\n          \"reason\": \"Hồ Ea Kao là điểm đến lý tưởng để thư giãn, ngắm cảnh thiên nhiên và đặc biệt là ngắm hoàng hôn lãng mạn. Đây là lựa chọn tuyệt vời để kết thúc một ngày khám phá văn hóa, mang lại sự yên bình trước khi chuẩn bị cho buổi tối.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho dịch vụ giải khát tại hồ (nếu có).\",\n          \"suggestion\": \"Có thể mang theo đồ ăn nhẹ và nước uống để cắm trại nhỏ tại đây.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi\",\n          \"reason\": \"Khám phá thêm các món ăn đêm của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Phở hai tô 52, 52 Ngô Quyền, TP. Buôn Ma Thuột. Lưu trú tại Elephants Hotel, 142 Hai Bà Trưng, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"100.000đ - 200.000đ (chi phí ăn tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình khám phá thác nước hùng vĩ và văn hóa voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"destination_id\": 16,\n          \"activity\": \"Ngắm bình minh và check-in Núi Đá Voi Mẹ\",\n          \"reason\": \"Núi Đá Voi Mẹ là một địa điểm độc đáo với truyền thuyết kỳ bí và tầm nhìn rộng mở, rất thích hợp để ngắm bình minh và chụp ảnh đẹp. Đây là một trải nghiệm thiên nhiên độc đáo trước khi tham quan các thác nước.\",\n          \"community_impact\": \"Miễn phí\",\n          \"suggestion\": \"Mang theo nước uống và đồ ăn nhẹ. Cẩn thận khi leo trèo.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy (khoảng 1 tiếng từ Buôn Ma Thuột)\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk và trải nghiệm thuyền độc mộc\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, mang vẻ đẹp hoang sơ và văn hóa M\'nông đặc sắc. Trải nghiệm thuyền độc mộc vào buổi sáng sớm sẽ giúp du khách tận hưởng không khí trong lành và vẻ đẹp yên bình của hồ.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho dịch vụ thuyền độc mộc của người dân địa phương.\",\n          \"suggestion\": \"Thuê thuyền độc mộc của người M\'nông tại buôn Jun hoặc buôn Lê.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/ô tô\",\n          \"price\": \"100.000đ - 200.000đ (thuê thuyền độc mộc, vé tham quan)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa món ăn địa phương và nghỉ ngơi tại khu vực Hồ Lắk\",\n          \"reason\": \"Thưởng thức các món ăn dân dã đặc trưng của vùng Hồ Lắk, tiện lợi sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Các nhà hàng quanh Hồ Lắk phục vụ cơm lam, gà nướng. Nghỉ ngơi tại Lak Tented Camp, ven Hồ Lắk, Huyện Lắk, Đắk Lắk.\",\n          \"address\": \"Quanh Hồ Lắk, Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"100.000đ - 150.000đ (chi phí ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur, ngắm hoàng hôn\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước hùng vĩ nhất Tây Nguyên, mang đến trải nghiệm thiên nhiên hùng vĩ. Buổi chiều, đặc biệt là lúc hoàng hôn, ánh nắng sẽ tạo nên khung cảnh tuyệt đẹp cho thác nước. Địa điểm không quá xa Hồ Lắk, thuận tiện di chuyển về lại Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 30.000đ vé vào cửa.\",\n          \"suggestion\": \"Có thể tham gia các hoạt động trekking nhẹ quanh thác. Đừng quên mang theo máy ảnh.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/ô tô\",\n          \"price\": \"30.000đ (vé vào cửa)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và thưởng thức cà phê Buôn Ma Thuột\",\n          \"reason\": \"Kết thúc chuyến đi với bữa tối ngon miệng và ly cà phê cuối cùng tại thủ phủ cà phê.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng và quán cà phê.\",\n          \"suggestion\": \"Bánh ướt chồng dĩa 45, 45 Lê Thánh Tông, TP. Buôn Ma Thuột. Sau đó ghé SOUL Roastery, 87 Nguyễn Khuyến, TP. Buôn Ma Thuột để thưởng thức cà phê. Lưu trú tại Sài Gòn - Ban Mê Hotel, 01-03 Phan Chu Trinh, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"100.000đ - 200.000đ (chi phí ăn tối và cà phê)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:36:03'),
(34, NULL, 'Lịch trình 2 ngày - gia đình', 2, 'gia đình', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Buôn Ma Thuột và văn hóa Tây Nguyên\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Khám phá Văn hóa Cà phê Buôn Ma Thuột và tham quan bảo tàng\",\n          \"reason\": \"Hoạt động nhẹ nhàng phù hợp cho gia đình, giúp tìm hiểu văn hóa đặc trưng của thủ phủ cà phê Việt Nam. Vị trí trung tâm thành phố tiện lợi cho việc di chuyển sau đó.\",\n          \"community_impact\": \"Dự kiến 0đ cho người dân/Cơ sở OCOP (chủ yếu là chi phí mua sắm cà phê, quà lưu niệm nếu có)\",\n          \"suggestion\": \"Gợi ý: Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (100k-150k/ngày) hoặc taxi/Grab để di chuyển trong thành phố.\",\n          \"price\": \"50.000đ - 100.000đ (cho đồ uống và phí tham quan bảo tàng nếu có)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan, thưởng thức các món ăn đặc trưng của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 500.000đ cho quán ăn/nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa: Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi: Khách sạn Sài Gòn - Ban Mê (01-03 Phan Chu Trinh, TP. Buôn Ma Thuột).\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc đi bộ tùy khoảng cách.\",\n          \"price\": \"200.000đ - 400.000đ (cho bữa trưa gia đình)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông\",\n          \"reason\": \"Trải nghiệm văn hóa Ê Đê truyền thống tại buôn làng đẹp nhất Buôn Ma Thuột, phù hợp cho gia đình khám phá văn hóa bản địa.\",\n          \"community_impact\": \"Dự kiến 0đ (nếu không mua sắm quà lưu niệm từ người dân địa phương).\",\n          \"suggestion\": \"Không có gợi ý cụ thể.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (nếu không mua sắm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và dạo phố Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức ẩm thực đa dạng và trải nghiệm không khí buổi tối của thành phố.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 500.000đ cho quán ăn/nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn tối: Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột). Lưu trú qua đêm: Mường Thanh Luxury Buôn Ma Thuột (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"300.000đ - 500.000đ (ăn tối gia đình), 800.000đ - 1.500.000đ (khách sạn/homestay)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá hồ Lắk và đại ngàn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n          \"reason\": \"Hồ nước ngọt lớn với cảnh quan tuyệt đẹp, trải nghiệm văn hóa M\'nông và thuyền độc mộc, phù hợp cho hoạt động gia đình.\",\n          \"community_impact\": \"Dự kiến 200.000đ - 500.000đ cho thuê thuyền độc mộc/dịch vụ của người dân địa phương.\",\n          \"suggestion\": \"Gợi ý lưu trú tại Lak Tented Camp (ven Hồ Lắk) nếu muốn trải nghiệm nghỉ dưỡng gần hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê ô tô hoặc xe máy từ Buôn Ma Thuột (khoảng 50km).\",\n          \"price\": \"100.000đ - 300.000đ (vé tham quan, thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi tại khu vực Hồ Lắk\",\n          \"reason\": \"Tiện lợi cho việc nghỉ ngơi và ăn uống sau buổi sáng tham quan hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 500.000đ cho quán ăn/nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại các nhà hàng địa phương ven hồ Lắk. Nghỉ ngơi tại Cư H\'Lăm Restaurant & Homestay (Ea Pốk, Buôn Ma Thuột) nếu muốn quay về gần Buôn Ma Thuột hơn cho buổi chiều.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy trong khu vực Hồ Lắk.\",\n          \"price\": \"200.000đ - 400.000đ (cho bữa trưa gia đình)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ\",\n          \"reason\": \"Điểm đến độc đáo với tảng đá nguyên khối lớn nhất Việt Nam và truyền thuyết kỳ bí, phù hợp cho gia đình khám phá.\",\n          \"community_impact\": \"Dự kiến 0đ (nếu không mua sắm quà lưu niệm).\",\n          \"suggestion\": \"Không có gợi ý cụ thể.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô từ Hồ Lắk (khoảng 15-20km).\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và chuẩn bị kết thúc hành trình\",\n          \"reason\": \"Thưởng thức bữa ăn cuối cùng tại Đắk Lắk và nghỉ ngơi trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 500.000đ cho quán ăn/nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn tối: Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột) nếu đã quay về thành phố. Lưu trú: Khách sạn Hai Bà Trưng (8 Hai Bà Trưng, TP. Buôn Ma Thuột) hoặc Homestay Lee\'s House (55 đ.số 3, Cư Bur, TP. Buôn Ma Thuột) để tiện di chuyển ra sân bay hoặc bến xe vào ngày hôm sau.\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về lại Buôn Ma Thuột.\",\n          \"price\": \"300.000đ - 500.000đ (ăn tối gia đình), 600.000đ - 1.200.000đ (khách sạn/homestay)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:38:09'),
(35, NULL, 'Lịch trình 2 ngày - văn hoá, chụp ảnh', 2, 'văn hoá, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Văn hóa Tây Nguyên & Hoàng hôn Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống, văn hóa và đời sống của người Ê Đê. Chụp ảnh lưu niệm với khung cảnh bản làng cổ kính.\",\n          \"reason\": \"Buôn Akô Dhông là điểm đến lý tưởng để khám phá văn hóa Ê Đê, với kiến trúc nhà dài độc đáo và không gian yên bình, rất thích hợp để chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua đồ lưu niệm hoặc ủng hộ cộng đồng.\",\n          \"suggestion\": \"Arul Coffee (17 Trần Nhật Duật) hoặc SOUL Roastery (87 Nguyễn Khuyến) để thưởng thức cà phê đặc trưng sau khi tham quan.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (100k-150k/ngày) hoặc taxi/Grab để di chuyển đến buôn. Từ trung tâm thành phố chỉ khoảng 5-10 phút.\",\n          \"price\": \"50.000đ (Chi phí cá nhân mua sắm/đồ uống)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi tại trung tâm Buôn Ma Thuột.\",\n          \"reason\": \"Nghỉ ngơi và nạp năng lượng sau buổi sáng khám phá, chuẩn bị cho hành trình buổi chiều.\",\n          \"community_impact\": \"Dự kiến 150.000đ - 200.000đ cho bữa trưa tại nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi tại Mường Thanh Luxury Buôn Ma Thuột (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột) hoặc Homestay Zan (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab\",\n          \"price\": \"150.000đ - 200.000đ (Bữa trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 1,\n          \"activity\": \"Di chuyển đến Hồ Lắk. Chèo thuyền độc mộc trên hồ, ngắm cảnh hoàng hôn tuyệt đẹp trên hồ Lắk. Tham quan buôn làng M\'nông ven hồ.\",\n          \"reason\": \"Hồ Lắk nổi tiếng với vẻ đẹp lãng mạn vào buổi hoàng hôn và văn hóa M\'nông độc đáo, rất thích hợp cho những người yêu văn hóa và thích chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 300.000đ - 500.000đ cho dịch vụ thuyền độc mộc và giao lưu văn hóa cộng đồng.\",\n          \"suggestion\": \"Lak Tented Camp (ven Hồ Lắk, Huyện Lắk) là lựa chọn tuyệt vời để có trải nghiệm nghỉ dưỡng gần thiên nhiên.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km, ~1.5 giờ di chuyển).\",\n          \"price\": \"300.000đ - 500.000đ (Thuê thuyền độc mộc, chi phí tham quan)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối với đặc sản địa phương tại Hồ Lắk, tận hưởng không khí yên bình của núi rừng. Nghỉ đêm tại Hồ Lắk.\",\n          \"reason\": \"Trải nghiệm ẩm thực và nghỉ ngơi tại chỗ để tận hưởng trọn vẹn vẻ đẹp của Hồ Lắk, đặc biệt là vào buổi sáng hôm sau.\",\n          \"community_impact\": \"Dự kiến 200.000đ - 300.000đ cho bữa tối tại các nhà hàng địa phương ven hồ. Đóng góp vào chi phí lưu trú của các homestay địa phương.\",\n          \"suggestion\": \"Ăn tối tại nhà hàng ven hồ. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk) hoặc Cư H\'Lăm Restaurant & Homestay (Ea Pốk, Buôn Ma Thuột, cách Hồ Lắk không xa).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy trong khu vực Hồ Lắk\",\n          \"price\": \"200.000đ - 300.000đ (Bữa tối) + Chi phí lưu trú (tùy chọn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Thác nước hùng vĩ & Văn hóa voi Buôn Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ vào buổi sáng sớm để ngắm bình minh và chụp ảnh. Tìm hiểu truyền thuyết về tảng đá nguyên khối lớn nhất Việt Nam.\",\n          \"reason\": \"Núi Đá Voi Mẹ mang vẻ đẹp hùng vĩ và câu chuyện văn hóa, đặc biệt là vào buổi sáng sớm khi không khí trong lành và ít khách du lịch, rất lý tưởng để chụp ảnh và khám phá.\",\n          \"community_impact\": \"Dự kiến 50.000đ - 100.000đ mua đồ lưu niệm hoặc ủng hộ người dân địa phương.\",\n          \"suggestion\": \"Sau đó, di chuyển về hướng Buôn Ma Thuột để ăn sáng tại một quán phở hoặc bún bò.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy từ Hồ Lắk đến Núi Đá Voi Mẹ (khoảng 10-15 phút).\",\n          \"price\": \"0đ (Miễn phí tham quan) + 50.000đ (Chi phí cá nhân)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực gần Thác Dray Nur hoặc trên đường về Buôn Ma Thuột, thưởng thức đặc sản địa phương.\",\n          \"reason\": \"Nạp lại năng lượng sau buổi sáng khám phá và chuẩn bị cho hành trình buổi chiều.\",\n          \"community_impact\": \"Dự kiến 150.000đ - 200.000đ cho bữa trưa tại quán ăn địa phương.\",\n          \"suggestion\": \"Quán ăn địa phương gần khu vực thác hoặc Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) nếu quay về thành phố sớm hơn.\",\n          \"address\": \"Gần Thác Dray Nur, Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab\",\n          \"price\": \"150.000đ - 200.000đ (Bữa trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Đi bộ ngắm cảnh, chụp ảnh với phong cảnh thiên nhiên hoang sơ.\",\n          \"reason\": \"Thác Dray Nur mang vẻ đẹp tự nhiên hùng vĩ, là địa điểm tuyệt vời để chụp ảnh và tận hưởng không khí trong lành của núi rừng.\",\n          \"community_impact\": \"Dự kiến 30.000đ cho vé vào cổng.\",\n          \"suggestion\": \"Có thể kết hợp tham quan Thác Dray Sáp (ID: 3) ở gần đó nếu còn thời gian và sức khỏe.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab từ Núi Đá Voi Mẹ đến Thác Dray Nur (khoảng 30-40 phút).\",\n          \"price\": \"30.000đ (Vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối tại Buôn Ma Thuột, thưởng thức các món ăn đặc trưng của phố núi. Mua sắm quà lưu niệm (cà phê, thịt nai khô, mật ong).\",\n          \"reason\": \"Kết thúc chuyến đi bằng bữa tối ngon miệng và mua sắm quà lưu niệm trước khi rời đi.\",\n          \"community_impact\": \"Dự kiến 200.000đ - 300.000đ cho bữa tối. Góp phần vào kinh tế địa phương thông qua việc mua sắm quà lưu niệm.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Mua cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab trong thành phố\",\n          \"price\": \"200.000đ - 300.000đ (Bữa tối) + Chi phí mua sắm quà lưu niệm\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:42:13'),
(36, NULL, 'Lịch trình 2 ngày - trekking, chụp ảnh', 2, 'trekking, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Trekking Rừng đại ngàn và Săn hoàng hôn Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"destination_id\": 5,\n          \"activity\": \"Khám phá Vườn Quốc gia Yok Đôn - Trekking và chụp ảnh hệ sinh thái rừng. Du khách sẽ có cơ hội ngắm bình minh trong rừng, tìm hiểu về đa dạng sinh học và có thể bắt gặp các loài động vật hoang dã (từ xa).\",\n          \"reason\": \"Ưu tiên hoạt động buổi sáng sớm theo yêu cầu, thích hợp cho sở thích trekking và chụp ảnh với ánh sáng đẹp. Yok Đôn là điểm đến lý tưởng để trải nghiệm thiên nhiên hùng vĩ của Tây Nguyên.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho vé vào cửa, đóng góp vào công tác bảo tồn và phát triển du lịch bền vững.\",\n          \"suggestion\": \"Nên đặt tour trekking có hướng dẫn viên địa phương từ trước. Mang theo nước uống, đồ ăn nhẹ và trang phục thoải mái, giày đi bộ tốt. Sau trekking có thể thưởng thức cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ) trên đường về BMT.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (khoảng 150.000đ/ngày) hoặc taxi/Grab từ Buôn Ma Thuột đến Yok Đôn (khoảng 40km). Di chuyển bằng xe jeep trong vườn quốc gia để đến các điểm trekking.\",\n          \"price\": \"Vé vào cửa: 60.000đ/người. Chi phí hướng dẫn viên/xe jeep: Tùy gói trekking, khoảng 300.000 - 500.000đ/nhóm.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Tây Nguyên và nghỉ ngơi tại Buôn Ma Thuột.\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng trekking mệt mỏi và thưởng thức ẩm thực địa phương.\",\n          \"community_impact\": \"Dự kiến 150.000đ/người cho bữa trưa tại nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông) với các món ăn truyền thống. Nghỉ ngơi tại khách sạn Sài Gòn - Ban Mê (01-03 Phan Chu Trinh) hoặc Homestay Zan Homestay (37 Hồ Giáo) để tiện di chuyển cho buổi chiều.\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk (Quán Cà Te)\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"Ăn trưa: 100.000 - 150.000đ/người. Chi phí nghỉ trưa (nếu có): Tùy loại hình lưu trú.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ và chụp ảnh hoàng hôn tại Hồ Lắk. Đây là cơ hội tuyệt vời để chụp những bức ảnh độc đáo với cảnh quan thiên nhiên hùng vĩ và ánh sáng hoàng hôn.\",\n          \"reason\": \"Kết hợp tham quan danh thắng độc đáo với yêu cầu chụp ảnh hoàng hôn đẹp. Núi Đá Voi Mẹ mang vẻ đẹp kỳ vĩ và gần Hồ Lắk, thuận tiện di chuyển.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho các dịch vụ nhỏ tại khu vực Đá Voi (nếu có).\",\n          \"suggestion\": \"Nên đến Đá Voi Mẹ khoảng 15h30-16h00 để có đủ thời gian tham quan và di chuyển sang Hồ Lắk trước hoàng hôn. Chuẩn bị máy ảnh sẵn sàng.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô cá nhân từ Buôn Ma Thuột đến Đá Voi Mẹ (khoảng 50km). Từ Đá Voi Mẹ di chuyển khoảng 15km đến Hồ Lắk.\",\n          \"price\": \"Vé tham quan Đá Voi Mẹ: Free. Chi phí gửi xe (nếu có): 10.000đ.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": 1,\n          \"activity\": \"Thưởng thức ẩm thực địa phương bên Hồ Lắk và trải nghiệm văn hóa M\'nông.\",\n          \"reason\": \"Tận hưởng không khí yên bình, thưởng thức đặc sản và tìm hiểu văn hóa bản địa sau buổi hoàng hôn lãng mạn.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho bữa tối tại các nhà hàng ven hồ, hỗ trợ kinh tế địa phương. Có thể mua các sản phẩm thủ công của người dân M\'nông.\",\n          \"suggestion\": \"Ăn tối tại Cư H\'Lăm Restaurant & Homestay (Ea Pốk) hoặc các quán ăn dân dã ven Hồ Lắk. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk) để có trải nghiệm hòa mình vào thiên nhiên và văn hóa bản địa.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bộ hoặc xe máy đến các nhà hàng ven hồ. Di chuyển đến chỗ lưu trú.\",\n          \"price\": \"Ăn tối: 150.000 - 250.000đ/người. Lưu trú Lak Tented Camp: Từ 1.500.000đ/đêm (tùy loại phòng).\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Bình minh Hồ Lắk và Khám phá Thác Dray Nur\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"destination_id\": 1,\n          \"activity\": \"Đón bình minh trên Hồ Lắk, trải nghiệm chèo thuyền độc mộc và khám phá văn hóa M\'nông. Đây là cơ hội tuyệt vời để chụp những bức ảnh bình minh huyền ảo trên mặt hồ.\",\n          \"reason\": \"Ưu tiên hoạt động buổi sáng sớm, phù hợp với sở thích chụp ảnh và tìm hiểu văn hóa địa phương. Hồ Lắk lúc bình minh rất yên bình và thơ mộng.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho dịch vụ chèo thuyền độc mộc của người dân địa phương.\",\n          \"suggestion\": \"Thức dậy sớm để ngắm bình minh. Nên đặt trước dịch vụ chèo thuyền độc mộc qua homestay hoặc người dân bản địa. Thưởng thức bữa sáng nhẹ tại chỗ lưu trú hoặc các quán ăn địa phương.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy đến bờ hồ.\",\n          \"price\": \"Chèo thuyền độc mộc: 50.000 - 100.000đ/người. Ăn sáng: 30.000 - 50.000đ/người.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Di chuyển về Buôn Ma Thuột, ăn trưa và nghỉ ngơi.\",\n          \"reason\": \"Di chuyển về trung tâm để tiện cho các hoạt động buổi chiều và nghỉ ngơi sau buổi sáng sớm.\",\n          \"community_impact\": \"Dự kiến 150.000đ/người cho bữa trưa tại Buôn Ma Thuột.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) hoặc Phở hai tô 52 (52 Ngô Quyền). Sau đó, nghỉ ngơi tại khách sạn Mường Thanh (81 Nguyễn Tất Thành) hoặc Elephants (142 Hai Bà Trưng).\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột, Đắk Lắk (Bún đỏ cô Thu)\",\n          \"transport\": \"Xe máy hoặc ô tô cá nhân từ Hồ Lắk về Buôn Ma Thuột (khoảng 50km).\",\n          \"price\": \"Ăn trưa: 70.000 - 120.000đ/người.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur và Thác Dray Sáp, trải nghiệm trekking nhẹ và chụp ảnh tại một trong những thác nước hùng vĩ nhất Tây Nguyên.\",\n          \"reason\": \"Thỏa mãn sở thích trekking và chụp ảnh với cảnh quan thiên nhiên hùng vĩ của thác nước. Dray Nur và Dray Sáp nằm gần nhau, thuận tiện di chuyển.\",\n          \"community_impact\": \"Dự kiến 30.000đ/người cho vé vào cổng, đóng góp vào việc bảo trì khu du lịch.\",\n          \"suggestion\": \"Mang giày thể thao thoải mái để đi bộ khám phá các khu vực quanh thác. Cẩn thận khi di chuyển gần bờ thác. Có thể mua cà phê hoặc đặc sản địa phương tại các cửa hàng nhỏ gần thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Thác Dray Nur (khoảng 25km). Có cầu nối sang Thác Dray Sáp.\",\n          \"price\": \"Vé vào cửa Thác Dray Nur: 30.000đ/người. Vé vào cửa Thác Dray Sáp: 30.000đ/người.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối đặc sản Buôn Ma Thuột và mua sắm quà lưu niệm.\",\n          \"reason\": \"Kết thúc hành trình bằng việc thưởng thức ẩm thực và mua sắm đặc sản làm quà.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho bữa tối và 300.000đ cho mua sắm đặc sản (cà phê, thịt nai khô, mật ong).\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông) hoặc thưởng thức Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Mua sắm cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ) hoặc các cửa hàng đặc sản địa phương. Nghỉ đêm tại Khách sạn Hai Bà Trưng (8 Hai Bà Trưng) hoặc Đam San Hotel (212 Nguyễn Công Trứ) để tiện di chuyển ra sân bay hoặc bến xe vào sáng hôm sau.\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk (Bánh ướt chồng dĩa 45)\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong thành phố.\",\n          \"price\": \"Ăn tối: 100.000 - 200.000đ/người. Mua sắm quà: Tùy nhu cầu.\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:54:50'),
(37, NULL, 'Lịch trình 2 ngày - cà phê, chụp ảnh', 2, 'cà phê, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Thác nước hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức cà phê Buôn Ma Thuột và tìm hiểu văn hóa cà phê tại Làng cà phê Trung Nguyên\",\n          \"reason\": \"Buổi sáng tại thủ phủ cà phê sẽ giúp du khách hòa mình vào không khí đặc trưng, thưởng thức hương vị cà phê và có nhiều góc \'sống ảo\' đẹp.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho sản phẩm cà phê địa phương\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên, 163 Lý Thái Tổ, TP. Buôn Ma Thuột. Hoặc SOUL Roastery, 87 Nguyễn Khuyến, TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (100k-150k/ngày) hoặc taxi/Grab để di chuyển trong thành phố.\",\n          \"price\": \"50.000đ - 100.000đ (chi phí cà phê)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi tại trung tâm thành phố Buôn Ma Thuột\",\n          \"reason\": \"Nghỉ ngơi lấy lại sức để chuẩn bị cho buổi chiều khám phá thác nước.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương\",\n          \"suggestion\": \"Ăn trưa: Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi: Elephants Hotel, 142 Hai Bà Trưng, TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy/taxi/đi bộ\",\n          \"price\": \"100.000đ - 150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur, chiêm ngưỡng vẻ đẹp hùng vĩ và chụp ảnh \'check-in\'\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước đẹp nhất Tây Nguyên, rất thích hợp để chụp ảnh và tận hưởng thiên nhiên hùng vĩ.\",\n          \"community_impact\": \"Dự kiến 30.000đ vé vào cổng cho người dân địa phương\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi (khoảng 30km từ trung tâm BMT)\",\n          \"price\": \"30.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và tự do khám phá Buôn Ma Thuột về đêm, sau đó nhận phòng khách sạn\",\n          \"reason\": \"Buổi tối là thời gian thích hợp để thưởng thức ẩm thực địa phương và thư giãn.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và 500.000đ cho khách sạn địa phương\",\n          \"suggestion\": \"Ăn tối: Phở hai tô 52 (52 Ngô Quyền). Nghỉ đêm: Khách sạn Sài Gòn - Ban Mê, 01-03 Phan Chu Trinh, TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy/taxi/đi bộ\",\n          \"price\": \"150.000đ - 250.000đ (ăn tối), 500.000đ - 1.000.000đ (khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá Hồ Lắk và Văn hóa M\'Nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk, đi thuyền độc mộc và tìm hiểu văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, có cảnh quan đẹp và văn hóa đặc sắc, rất lý tưởng để chụp ảnh và trải nghiệm văn hóa bản địa.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho dịch vụ thuyền độc mộc của người dân và sản phẩm lưu niệm\",\n          \"suggestion\": \"Lak Tented Camp (nếu muốn trải nghiệm lưu trú gần hồ), ven Hồ Lắk, Huyện Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi (khoảng 50km từ TP. Buôn Ma Thuột)\",\n          \"price\": \"50.000đ - 100.000đ (chi phí đi thuyền)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa các món đặc sản địa phương gần Hồ Lắk hoặc trên đường về Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương\",\n          \"suggestion\": \"Tìm quán ăn gần khu vực Hồ Lắk hoặc dọc QL27 về lại BMT. Khách sạn/Homestay gợi ý nghỉ trưa: Cư H\'Lăm Restaurant & Homestay, Ea Pốk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy/taxi\",\n          \"price\": \"100.000đ - 150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ, chụp ảnh với tảng đá nguyên khối khổng lồ\",\n          \"reason\": \"Núi Đá Voi Mẹ mang vẻ đẹp độc đáo và những câu chuyện truyền thuyết thú vị, là điểm chụp ảnh rất ấn tượng.\",\n          \"community_impact\": \"Dự kiến đóng góp phí giữ xe nhỏ cho người dân địa phương\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi (trên đường về BMT)\",\n          \"price\": \"Free (có thể phát sinh phí gửi xe 10.000đ)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối chia tay và mua sắm đặc sản Đắk Lắk\",\n          \"reason\": \"Kết thúc chuyến đi bằng bữa tối ngon miệng và mua sắm quà lưu niệm.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và 200.000đ cho sản phẩm địa phương\",\n          \"suggestion\": \"Ăn tối: Quán Cà Te (140 Lê Thánh Tông). Mua sắm: Cà phê, thịt nai khô tại các cửa hàng đặc sản.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy/taxi\",\n          \"price\": \"150.000đ - 250.000đ (ăn tối), từ 200.000đ (mua sắm quà)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-19 06:57:39');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(38, 2, 'Lịch trình 5 ngày - văn hoá, ẩm thực, chụp ảnh', 5, 'văn hoá, ẩm thực, chụp ảnh', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá văn hóa cà phê và buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại Làng Cà phê Trung Nguyên\",\n          \"reason\": \"Du khách có sở thích văn hóa và ẩm thực, Làng Cà phê Trung Nguyên là nơi lý tưởng để bắt đầu hành trình khám phá thủ phủ cà phê Việt Nam.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho sản phẩm/dịch vụ cà phê địa phương.\",\n          \"suggestion\": \"Làng Cà phê Trung Nguyên, 163 Lý Thái Tổ, TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (100k-150k/ngày) hoặc taxi/Grab.\",\n          \"price\": \"150.000đ - 250.000đ (bao gồm đồ uống và trải nghiệm).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan và nạp năng lượng với đặc sản địa phương.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ ngơi tại Mường Thanh Luxury Buôn Ma Thuột (81 Nguyễn Tất Thành).\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"70.000đ - 120.000đ.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột\",\n          \"reason\": \"Phù hợp với sở thích văn hóa, du khách sẽ được tìm hiểu kiến trúc nhà dài truyền thống và đời sống của người Ê Đê. Đây cũng là điểm đẹp để chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 50.000đ ủng hộ cộng đồng địa phương (nếu có).\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"Miễn phí (tùy vào các dịch vụ phát sinh).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và tự do khám phá phố đêm Buôn Ma Thuột\",\n          \"reason\": \"Kết thúc ngày đầu tiên với ẩm thực đặc sắc và không khí sôi động của thành phố.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và cửa hàng địa phương.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ.\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá thác nước hùng vĩ và văn hóa voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur - một trong những thác nước hùng vĩ nhất Tây Nguyên\",\n          \"reason\": \"Phù hợp với sở thích chụp ảnh, thiên nhiên, và trekking nhẹ. Thác Dray Nur mang vẻ đẹp hoang sơ, hùng vĩ.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho vé vào cổng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy (khoảng 30km từ trung tâm BMT) hoặc taxi.\",\n          \"price\": \"30.000đ - 50.000đ (vé vào cổng).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại hoặc tại nhà hàng gần khu vực thác\",\n          \"reason\": \"Nghỉ ngơi và thưởng thức bữa trưa giữa không gian thiên nhiên trong lành.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Có thể mang theo đồ ăn nhẹ để dã ngoại hoặc tìm nhà hàng quanh khu vực Dray Nur - Dray Sáp. Nghỉ ngơi tại Cư H\'Lăm Restaurant & Homestay (Thôn 1, Ea Pốk, Cư M\'gar).\",\n          \"address\": \"Gần khu vực Thác Dray Nur, Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy.\",\n          \"price\": \"80.000đ - 150.000đ.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Khám phá Buôn Đôn - Làng văn hoá săn bắt và thuần dưỡng voi\",\n          \"reason\": \"Tiếp tục hành trình khám phá văn hóa địa phương, đặc biệt là về loài voi và kiến trúc nhà dài truyền thống. Đây là một điểm đến độc đáo để chụp ảnh.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho dịch vụ tham quan và trải nghiệm văn hóa.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 50km từ Thác Dray Nur).\",\n          \"price\": \"50.000đ - 100.000đ (vé vào cổng, tùy dịch vụ).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và nghỉ ngơi tại Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức ẩm thực phong phú của Buôn Ma Thuột sau một ngày dài khám phá.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại Sài Gòn - Ban Mê Hotel (01-03 Phan Chu Trinh, TP. Buôn Ma Thuột).\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"80.000đ - 150.000đ.\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Bình yên Hồ Lắk và Núi Đá Voi Mẹ kỳ bí\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Tham quan Hồ Lắk - Hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, trải nghiệm thuyền độc mộc và văn hóa M\'nông\",\n          \"reason\": \"Cảnh quan thiên nhiên tươi đẹp, mang đậm bản sắc văn hóa M\'nông. Phù hợp cho việc chụp ảnh và tìm hiểu văn hóa địa phương.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho dịch vụ thuyền độc mộc và hướng dẫn viên địa phương.\",\n          \"suggestion\": \"Thuê thuyền độc mộc để tham quan hồ và ghé các buôn làng ven hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 50km từ Buôn Ma Thuột).\",\n          \"price\": \"100.000đ - 250.000đ (bao gồm vé vào cổng và thuyền độc mộc).\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản ven Hồ Lắk và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương với các món cá nước ngọt và nghỉ ngơi trong khung cảnh yên bình.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Các nhà hàng ven Hồ Lắk phục vụ đặc sản. Nghỉ ngơi tại Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ - Tảng đá nguyên khối lớn nhất Việt Nam\",\n          \"reason\": \"Trải nghiệm độc đáo và cơ hội chụp ảnh cảnh quan hùng vĩ, gắn liền với những truyền thuyết kỳ bí của người dân tộc thiểu số.\",\n          \"community_impact\": \"Dự kiến 30.000đ cho phí gửi xe/dịch vụ nhỏ lẻ.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (gần Hồ Lắk).\",\n          \"price\": \"Miễn phí (chỉ tốn phí gửi xe).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Quay về Buôn Ma Thuột, ăn tối và tự do dạo phố\",\n          \"reason\": \"Thưởng thức ẩm thực đa dạng của thành phố và nghỉ ngơi sau một ngày di chuyển.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ đêm tại Khách sạn Hai Bà Trưng (8 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"80.000đ - 150.000đ.\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Mua sắm đặc sản và trải nghiệm chợ truyền thống\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": null,\n          \"activity\": \"Tham quan Chợ Trung tâm Buôn Ma Thuột, mua sắm đặc sản địa phương\",\n          \"reason\": \"Khám phá văn hóa chợ truyền thống, tìm hiểu đời sống người dân địa phương và mua sắm các đặc sản như cà phê, mật ong, thịt nai khô về làm quà. Phù hợp với sở thích ẩm thực và văn hóa.\",\n          \"community_impact\": \"Dự kiến 500.000đ cho các sản phẩm địa phương và người bán hàng tại chợ.\",\n          \"suggestion\": \"\",\n          \"address\": \"Nguyễn Tất Thành, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi gần khách sạn.\",\n          \"price\": \"Tùy thuộc vào sản phẩm mua sắm.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và thưởng thức cà phê địa phương\",\n          \"reason\": \"Nghỉ ngơi, thưởng thức ẩm thực và cà phê đặc trưng của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng/quán cà phê.\",\n          \"suggestion\": \"Ăn trưa tại một nhà hàng gần chợ. Thưởng thức cà phê tại Arul Coffee (17 Trần Nhật Duật, TP. Buôn Ma Thuột). Nghỉ ngơi tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột).\",\n          \"address\": \"17 Trần Nhật Duật, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc đi bộ.\",\n          \"price\": \"80.000đ - 150.000đ.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 8,\n          \"activity\": \"Thư giãn tại Hồ Ea Kao\",\n          \"reason\": \"Không gian yên bình, thoáng đãng, thích hợp để nghỉ ngơi, chụp ảnh hoàng hôn và chuẩn bị cho bữa tối.\",\n          \"community_impact\": \"Dự kiến 0đ (nếu không sử dụng dịch vụ).\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (cách trung tâm khoảng 12km).\",\n          \"price\": \"Miễn phí.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Tiệc tối chia tay Đắk Lắk\",\n          \"reason\": \"Thưởng thức bữa tối đặc biệt để kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng.\",\n          \"suggestion\": \"Ăn tối tại nhà hàng KoTam Resort (789 Phạm Văn Đồng, TP. Buôn Ma Thuột) để thưởng thức không gian sinh thái. Nghỉ đêm tại Đam San Hotel (212 Nguyễn Công Trứ, TP. Buôn Ma Thuột).\",\n          \"address\": \"789 Phạm Văn Đồng, TP. Buôn Ma Thuột\",\n          \"transport\": \"Taxi/Grab hoặc xe máy.\",\n          \"price\": \"150.000đ - 300.000đ.\"\n        }\n      ]\n    },\n    {\n      \"day\": 5,\n      \"title\": \"Tạm biệt Đắk Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức bữa sáng nhẹ nhàng và mua sắm quà lưu niệm\",\n          \"reason\": \"Có thêm thời gian để mua sắm những món quà cuối cùng hoặc thưởng thức một bữa sáng đặc trưng trước khi rời đi.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán ăn và cửa hàng lưu niệm.\",\n          \"suggestion\": \"Bữa sáng tại SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) để thưởng thức cà phê đặc biệt. Mua sắm tại các cửa hàng đặc sản gần trung tâm.\",\n          \"address\": \"87 Nguyễn Khuyến, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"50.000đ - 100.000đ.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và di chuyển ra sân bay/bến xe\",\n          \"reason\": \"Hoàn tất thủ tục và di chuyển ra sân bay hoặc bến xe để kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán ăn.\",\n          \"suggestion\": \"Ăn trưa tại một nhà hàng tiện đường ra sân bay/bến xe.\",\n          \"address\": \"...\",\n          \"transport\": \"Taxi/Grab hoặc xe ôm ra sân bay Buôn Ma Thuột (khoảng 30 phút).\",\n          \"price\": \"80.000đ - 150.000đ (bao gồm bữa trưa và di chuyển).\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": null,\n          \"activity\": \"Khởi hành\",\n          \"reason\": \"Kết thúc hành trình tại Đắk Lắk.\",\n          \"community_impact\": \"\",\n          \"suggestion\": \"\",\n          \"address\": \"\",\n          \"transport\": \"\",\n          \"price\": \"\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"...\",\n          \"reason\": \"...\",\n          \"community_impact\": \"...\",\n          \"suggestion\": \"...\",\n          \"address\": \"...\",\n          \"transport\": \"...\",\n          \"price\": \"...\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-20 07:37:41'),
(39, 2, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá văn hóa Ê Đê và thưởng thức cà phê nguyên bản\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống, văn hóa và phong tục của người Ê Đê.\",\n          \"reason\": \"Buôn Akô Dhông là một trong những buôn làng hiếm hoi còn giữ được nét văn hóa truyền thống Ê Đê ngay trong lòng thành phố, mang đến trải nghiệm độc đáo và ít người biết.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho các sản phẩm thủ công địa phương nếu có.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab đến buôn. Sau đó đi bộ để khám phá.\",\n          \"price\": \"50.000đ (Chi phí gửi xe và tự nguyện ủng hộ buôn làng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi.\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan và nạp năng lượng với các món ăn đặc trưng của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông) với các món cơm niêu, sau đó nghỉ tại An Homestay (137/91 Thôi Hữu).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk (Quán Cà Te); 137/91 Thôi Hữu, TP. Buôn Ma Thuột, Đắk Lắk (An Homestay)\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab.\",\n          \"price\": \"150.000đ (Ăn trưa) + 300.000đ (Nghỉ trưa tại homestay nếu cần)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột. Thăm một quán cà phê địa phương để tìm hiểu quy trình rang xay và thưởng thức những ly cà phê nguyên chất theo phong cách Tây Nguyên.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, đây là cơ hội để khám phá \'góc khuất\' của văn hóa cà phê, không chỉ uống mà còn hiểu về nó, tránh các quán cà phê thương mại quá đông đúc.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán cà phê địa phương.\",\n          \"suggestion\": \"Thưởng thức cà phê tại SOUL Roastery (87 Nguyễn Khuyến) hoặc Arul Coffee (17 Trần Nhật Duật) để có trải nghiệm cà phê specialty.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk (SOUL Roastery); 17 Trần Nhật Duật, TP. Buôn Ma Thuột, Đắk Lắk (Arul Coffee)\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"50.000đ - 80.000đ (Chi phí cà phê)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và khám phá ẩm thực đường phố Buôn Ma Thuột. Tự do dạo phố, khám phá các món ăn vặt đêm.\",\n          \"reason\": \"Trải nghiệm ẩm thực đêm là một phần quan trọng của văn hóa địa phương, mang lại cái nhìn chân thực về cuộc sống của người dân.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương và người bán hàng rong.\",\n          \"suggestion\": \"Ăn tối bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ đêm tại Zan Homestay (37 Hồ Giáo) để trải nghiệm không gian địa phương.\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột, Đắk Lắk (Bún đỏ cô Thu); 37 Hồ Giáo, TP. Buôn Ma Thuột, Đắk Lắk (Zan Homestay)\",\n          \"transport\": \"Đi bộ hoặc xe máy/Grab.\",\n          \"price\": \"100.000đ - 150.000đ (Ăn tối) + 350.000đ - 500.000đ (Homestay qua đêm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá huyền thoại Tây Nguyên và trải nghiệm hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ, tảng đá nguyên khối lớn nhất Việt Nam. Nghe những câu chuyện truyền thuyết kỳ bí gắn liền với tảng đá và ngắm cảnh quan xung quanh.\",\n          \"reason\": \"Núi Đá Voi Mẹ là một điểm đến độc đáo, mang đậm yếu tố văn hóa tâm linh và huyền thoại của người dân tộc, không quá đông đúc như các thác lớn.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho người dân địa phương trông giữ xe hoặc bán hàng rong nhỏ.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô đến Đá Voi Mẹ (khoảng 50km từ BMT).\",\n          \"price\": \"30.000đ (Chi phí gửi xe)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với các món đặc sản địa phương tại khu vực Hồ Lắk.\",\n          \"reason\": \"Thưởng thức ẩm thực mang đậm hương vị núi rừng Tây Nguyên sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng hoặc quán ăn địa phương quanh Hồ Lắk.\",\n          \"suggestion\": \"Ăn trưa tại các nhà hàng địa phương gần Hồ Lắk, chuyên về cá nước ngọt hoặc cơm lam. Có thể nghỉ trưa tại Cư H\'Lăm Restaurant & Homestay (Ea Pốk, gần Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk (Nhà hàng quanh Hồ Lắk); Ea Pốk, Huyện Cư M\'gar, Đắk Lắk (Cư H\'Lăm Restaurant & Homestay)\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi.\",\n          \"price\": \"150.000đ - 200.000đ (Ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk. Trải nghiệm đi thuyền độc mộc trên hồ, tìm hiểu văn hóa của người M\'nông, và thưởng thức không gian yên bình của hồ nước ngọt tự nhiên lớn thứ hai Việt Nam.\",\n          \"reason\": \"Hồ Lắk là một điểm đến mang đậm bản sắc văn hóa M\'nông và cảnh quan thiên nhiên hoang sơ, ít bị du lịch hóa hơn các điểm khác, cho phép trải nghiệm sâu sắc văn hóa bản địa.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho dịch vụ thuyền độc mộc của người dân địa phương.\",\n          \"suggestion\": \"Tìm đến các làng của người M\'nông quanh Hồ Lắk để trải nghiệm thuyền độc mộc và giao lưu văn hóa.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô đến khu vực Hồ Lắk, sau đó đi bộ hoặc xe ôm địa phương.\",\n          \"price\": \"100.000đ - 150.000đ (Đi thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Quay về Buôn Ma Thuột. Ăn tối và mua sắm đặc sản làm quà (cà phê, thịt nai khô).\",\n          \"reason\": \"Kết thúc chuyến đi bằng việc thưởng thức thêm ẩm thực địa phương và mua sắm quà lưu niệm.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và các cơ sở sản xuất đặc sản địa phương.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Mua sắm cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ).\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột, Đắk Lắk (Phở hai tô 52); 45 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk (Bánh ướt chồng dĩa 45); 163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk (Làng cà phê Trung Nguyên)\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về Buôn Ma Thuột.\",\n          \"price\": \"100.000đ - 200.000đ (Ăn tối) + Tùy chọn (Mua sắm quà)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-20 07:41:20'),
(40, 2, 'Lịch trình 4 ngày - thiên nhiên, gia đình', 4, 'thiên nhiên, gia đình', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk bằng thuyền độc mộc và tìm hiểu văn hóa M\'nông.\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, có cảnh quan thiên nhiên tuyệt đẹp và là trung tâm của văn hóa M\'nông, rất phù hợp cho gia đình muốn khám phá thiên nhiên và văn hóa.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho người dân chèo thuyền độc mộc/hướng dẫn viên địa phương.\",\n          \"suggestion\": \"Lak Tented Camp (ven Hồ Lắk) nếu muốn lưu trú gần hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê ô tô hoặc xe máy từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km).\",\n          \"price\": \"Vé tham quan: 30.000đ/người. Thuê thuyền độc mộc: 150.000đ - 200.000đ/chuyến.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với các món đặc sản địa phương tại Hồ Lắk và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương ngay tại khu vực Hồ Lắk để tiết kiệm thời gian di chuyển và trải nghiệm hương vị núi rừng.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Nhà hàng Cư H\'Lăm (Ea Pốk) hoặc các quán ăn ven Hồ Lắk. Homestay: Cư H\'Lăm Restaurant & Homestay (Ea Pốk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe cá nhân.\",\n          \"price\": \"150.000đ - 250.000đ/người cho bữa trưa.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ và tìm hiểu truyền thuyết.\",\n          \"reason\": \"Núi Đá Voi Mẹ là một tảng đá nguyên khối lớn nhất Việt Nam, mang vẻ đẹp hoang sơ và câu chuyện truyền thuyết hấp dẫn, phù hợp cho gia đình khám phá.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho các dịch vụ nhỏ lẻ tại khu vực.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô từ Hồ Lắk (khoảng 10-15km).\",\n          \"price\": \"Miễn phí (chi phí gửi xe nếu có: 10.000đ - 20.000đ).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Di chuyển về Buôn Ma Thuột, ăn tối và tự do khám phá thành phố.\",\n          \"reason\": \"Về trung tâm thành phố để tiện nghỉ ngơi và có nhiều lựa chọn ăn uống hơn sau một ngày khám phá.\",\n          \"community_impact\": \"Dự kiến 400.000đ cho nhà hàng và khách sạn/homestay.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Khách sạn: Mường Thanh (81 Nguyễn Tất Thành) hoặc Elephants (142 Hai Bà Trưng).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê ô tô hoặc xe máy từ Hồ Lắk về Buôn Ma Thuột.\",\n          \"price\": \"Ăn tối: 100.000đ - 150.000đ/người. Lưu trú: 500.000đ - 1.000.000đ/đêm.\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hùng vĩ thác nước và văn hóa voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Khám phá Thác Dray Nur hùng vĩ.\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước đẹp và hùng vĩ nhất Tây Nguyên, mang đến trải nghiệm thiên nhiên ấn tượng cho cả gia đình.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho các dịch vụ nhỏ lẻ tại khu vực.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô từ Buôn Ma Thuột (khoảng 25-30km).\",\n          \"price\": \"Vé vào cổng: 30.000đ/người.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại hoặc tại nhà hàng gần thác và nghỉ ngơi.\",\n          \"reason\": \"Tận hưởng bữa trưa giữa không gian thiên nhiên trong lành, gần thác nước để có thể nghỉ ngơi và tiếp tục hành trình.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Các quán ăn ven Thác Dray Nur. Homestay: An Homestay (137/91 Thôi Hữu, Buôn Ma Thuột) nếu muốn về thành phố nghỉ.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe cá nhân.\",\n          \"price\": \"100.000đ - 150.000đ/người cho bữa trưa.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu nghề săn bắt và thuần dưỡng voi.\",\n          \"reason\": \"Buôn Đôn là làng văn hóa nổi tiếng với lịch sử gắn liền với voi, mang đến trải nghiệm văn hóa độc đáo và ý nghĩa cho gia đình.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho người dân Buôn Đôn (ví dụ: mua sắm đồ lưu niệm, dịch vụ tại chỗ).\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô từ Thác Dray Nur đến Buôn Đôn (khoảng 35-40km).\",\n          \"price\": \"Vé vào cổng: 40.000đ/người. Đi cầu treo: 30.000đ/người. (Không khuyến khích cưỡi voi vì lý do bảo tồn).\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và tự do khám phá ẩm thực Buôn Ma Thuột.\",\n          \"reason\": \"Trải nghiệm thêm các món ăn đặc sắc của Buôn Ma Thuột vào buổi tối.\",\n          \"community_impact\": \"Dự kiến 400.000đ cho nhà hàng và khách sạn/homestay.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền). Khách sạn: Sài Gòn - Ban Mê (01-03 Phan Chu Trinh) hoặc Đam San Hotel (212 Nguyễn Công Trứ).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"Ăn tối: 100.000đ - 150.000đ/người. Lưu trú: 500.000đ - 1.000.000đ/đêm.\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Thủ phủ cà phê và buôn làng cổ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Khám phá văn hóa cà phê Buôn Ma Thuột.\",\n          \"reason\": \"Trải nghiệm không gian cà phê đặc trưng của thủ phủ cà phê Việt Nam, rất thích hợp cho gia đình muốn tìm hiểu về văn hóa bản địa.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán cà phê địa phương/mua cà phê.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên (163 Lý Thái Tổ) hoặc Arul Coffee (17 Trần Nhật Duật) để thưởng thức cà phê và mua sắm.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"Miễn phí tham quan, chi phí cà phê: 50.000đ - 100.000đ/người.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với đặc sản Bánh ướt chồng dĩa.\",\n          \"reason\": \"Thưởng thức món ăn độc đáo và nổi tiếng của Buôn Ma Thuột, mang lại trải nghiệm ẩm thực địa phương chân thực.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Homestay: Lee\'s House (55 đ.số 3, Cư Bur) để nghỉ ngơi trong không gian yên tĩnh.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ.\",\n          \"price\": \"50.000đ - 80.000đ/người cho bữa trưa.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làn