      \"price\": \"Vé vào cổng: 20.000đ/người.\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại nhà hàng địa phương gần thác và nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức các món ăn dân dã, đặc trưng của vùng Krông Năng, tiện lợi cho việc nghỉ ngơi trước khi trở về.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Các quán ăn ven đường hoặc gần Thác Thủy Tiên. Homestay: Zan Homestay (37 Hồ Giáo, Buôn Ma Thuột) nếu muốn nghỉ lại thành phố.\",\n          \"address\": \"Krông Năng, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe cá nhân.\",\n          \"price\": \"100.000đ - 150.000đ/người cho bữa trưa.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": null,\n          \"activity\": \"Mua sắm đặc sản Đắk Lắk làm quà.\",\n          \"reason\": \"Chọn mua những món quà đặc trưng của Đắk Lắk như cà phê, thịt nai khô, mật ong rừng để mang về tặng người thân và bạn bè.\",\n          \"community_impact\": \"Dự kiến 500.000đ - 1.000.000đ cho các cửa hàng đặc sản địa phương/OCOP.\",\n          \"suggestion\": \"Chợ Buôn Ma Thuột hoặc các cửa hàng đặc sản uy tín trong thành phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"Tùy thuộc vào sản phẩm mua sắm.\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối chia tay Đắk Lắk và chuẩn bị khởi hành/về lại.\",\n          \"reason\": \"Thưởng thức bữa ăn cuối cùng tại Buôn Ma Thuột trước khi kết thúc hành trình.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng.\",\n          \"suggestion\": \"Các nhà hàng đặc sản địa phương hoặc nhà hàng trong khách sạn. Khách sạn: Khu nghỉ dưỡng sinh thái KoTam (789 Phạm Văn Đồng) nếu muốn trải nghiệm không gian xanh trước khi