         \"community_impact\": \"Dự kiến 50.000đ cho sản phẩm thủ công/người dân địa phương.\",\n          \"suggestion\": \"Hãy trò chuyện với người dân địa phương để hiểu thêm về văn hóa Ê Đê.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 15-20 phút từ trung tâm).\",\n          \"price\": \"Miễn phí (chi phí di chuyển tự túc)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Dùng bữa tối và khám phá Buôn Ma Thuột về đêm\",\n          \"reason\": \"Thưởng thức ẩm thực đường phố và cảm nhận không khí thành phố về đêm.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn địa phương/chợ đêm.\",\n          \"suggestion\": \"Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột). Lưu trú: Khách sạn Sài Gòn - Ban Mê (01-03 Phan Chu Trinh, TP. Buôn Ma Thuột).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"150.000đ - 250.000đ (chi phí bữa tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình về miền hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, gắn liền với văn hóa M\'nông. Hoạt động này đáp ứng sở thích văn hóa và khám phá thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho dịch vụ thuyền độc mộc/người dân M\'nông.\",\n          \"suggestion\": \"Trải nghiệm chèo thuyền độc mộc trên Hồ Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 1.5 - 2 tiếng di chuyển từ Buôn Ma Thuột).\",\n          \"price\": \"50.000đ - 200.000đ (vé tham quan, chèo thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Hồ Lắk và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức đặc sản địa phương tại Hồ Lắk và nghỉ ngơi sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Các quán ăn ven hồ Lắk. Lưu trú: Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ (chi phí bữa trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ\",\n          \"reason\": \"Khám phá tảng đá nguyên khối lớn nhất Việt Nam với những truyền thuyết kỳ bí, gần Hồ Lắk, giúp du khách hiểu thêm về văn hóa và địa chất địa phương.\",\n          \"community_impact\": \"Dự kiến 0đ.\",\n          \"suggestion\": \"Chuẩn bị giày dép thoải mái để leo núi.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 15-20 phút từ Hồ Lắk).\",\n          \"price\": \"Miễn phí (chi phí di chuyển tự túc)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và trải nghiệm lưu trú tại Hồ Lắk\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và trải nghiệm không gian yên bình của Hồ Lắk về đêm.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng/homestay địa phương.\",\n          \"suggestion\": \"Ăn tối tại các nhà hàng ven Hồ Lắk. Lưu trú: Lak Tented Camp (ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"150.000đ - 250.000đ (chi phí bữa tối)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Khám phá Buôn Đôn và Văn hóa Voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn và tìm hiểu văn hóa voi\",\n          \"reason\": \"Buôn Đôn nổi tiếng với nghề săn bắt và thuần dưỡng voi, là điểm đến lý tưởng để khám phá văn hóa độc đáo của người dân bản địa, phù hợp với sở thích văn hóa.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho người dân/cơ sở dịch vụ tại Buôn Đôn.\",\n          \"suggestion\": \"Trải nghiệm đi cầu treo và tham quan nhà dài truyền thống.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 1.5 tiếng từ Hồ Lắk về Buôn Ma Thuột, sau đó 1 tiếng từ Buôn Ma Thuột đến Buôn Đôn).\",\n          \"price\": \"50.000đ - 100.000đ (vé tham quan, cầu treo)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Buôn Đôn và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức ẩm thực đặc sản Buôn Đôn, nghỉ ngơi trước khi quay lại Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Thưởng thức món gà nướng Bản Đôn. Lưu trú: Quay về Buôn Ma Thuột để nghỉ ngơi tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ - 200.000đ (chi phí bữa trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 5,\n          \"activity\": \"Tham quan Vườn quốc gia Yok Đôn (hoạt động nhẹ nhàng)\",\n          \"reason\": \"Vườn quốc gia Yok Đôn là nơi sinh sống của voi rừng, du khách có thể tham quan nhẹ nhàng để cảm nhận không khí rừng, phù hợp với sở thích thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho vé vào cửa.\",\n          \"suggestion\": \"Có thể chọn tour đi bộ ngắn hoặc tham quan trung tâm cứu hộ động vật.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 15-20 phút từ trung tâm Buôn Đôn).\",\n          \"price\": \"60.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối đặc sản và mua sắm quà lưu niệm\",\n          \"reason\": \"Thưởng thức bữa ăn cuối cùng tại Đắk Lắk và mua sắm quà lưu niệm đặc sản.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng/cửa hàng đặc sản địa phương.\",\n          \"suggestion\": \"Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Mua cà phê, thịt nai khô tại các cửa hàng đặc sản. Lưu trú: Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"150.000đ - 300.000đ (bữa tối và mua sắm quà)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-27 04:19:39'),
(42, 7, 'Lịch trình 2 ngày - thiên nhiên, văn hoá', 2, 'thiên nhiên, văn hoá', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa và Thiên nhiên M\'nông tại Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Trải nghiệm văn hóa M\'nông tại Hồ Lắk, đi thuyền độc mộc ngắm cảnh hồ và các buôn làng ven hồ. Thăm quan nhà dài truyền thống.\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, gắn liền với văn hóa M\'nông độc đáo, mang đến trải nghiệm thiên nhiên và văn hóa ít người biết, khám phá góc khuất của địa phương.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho người dân địa phương cung cấp dịch vụ thuyền độc mộc và giao lưu văn hóa.\",\n          \"suggestion\": \"Nên thuê thuyền độc mộc của người dân địa phương tại buôn Jun hoặc buôn Lê. Có thể nghỉ đêm tại Lak Tented Camp, ven Hồ Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (150.000đ/ngày) hoặc taxi/Grab từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km). Di chuyển bằng thuyền độc mộc quanh hồ.\",\n          \"price\": \"100.000đ (vé tham quan, thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản địa phương (cơm lam, cá nướng Hồ Lắk) và nghỉ ngơi tại khu vực Hồ Lắk.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương, hỗ trợ kinh tế cộng đồng và có thời gian nghỉ ngơi trước khi tiếp tục hành trình.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Quán ăn tại các buôn làng ven Hồ Lắk. Có thể nghỉ ngơi tại Lak Tented Camp, ven Hồ Lắk (đặt trước nếu có ý định nghỉ trưa hoặc qua đêm).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy đến quán ăn.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ, tìm hiểu truyền thuyết kỳ bí và chiêm ngưỡng tảng đá nguyên khối lớn nhất Việt Nam.\",\n          \"reason\": \"Núi Đá Voi Mẹ là một điểm đến độc đáo, ít người biết với truyền thuyết văn hóa gắn liền với người dân bản địa, phù hợp với sở thích khám phá góc khuất.\",\n          \"community_impact\": \"Free (chi phí tự nguyện cho người dân nếu có hướng dẫn)\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy từ Hồ Lắk đến Núi Đá Voi Mẹ (khoảng 10km).\",\n          \"price\": \"0đ (vé vào cửa, có thể phát sinh chi phí nhỏ nếu sử dụng dịch vụ địa phương)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và nghỉ ngơi tại Buôn Ma Thuột.\",\n          \"reason\": \"Kết thúc ngày khám phá Hồ Lắk và Đá Voi Mẹ, trở về trung tâm Buôn Ma Thuột để tiện di chuyển cho ngày hôm sau và tận hưởng các dịch vụ tiện ích.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng và 500.000đ cho khách sạn.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Lắk về Buôn Ma Thuột.\",\n          \"price\": \"700.000đ (ăn tối, khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá Đại ngàn và Văn hóa Cà phê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 5,\n          \"activity\": \"Khám phá Vườn quốc gia Yok Đôn, trải nghiệm đi bộ trong rừng, tìm hiểu về hệ sinh thái đa dạng và văn hóa voi rừng (không cưỡi voi).\",\n          \"reason\": \"Vườn quốc gia Yok Đôn là vườn quốc gia lớn nhất Việt Nam, mang đến trải nghiệm thiên nhiên hùng vĩ và tìm hiểu văn hóa voi một cách bền vững, tránh các hoạt động gây ảnh hưởng đến động vật.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho phí vào cửa và hướng dẫn viên địa phương.\",\n          \"suggestion\": \"Nên đi cùng hướng dẫn viên của Vườn quốc gia để có trải nghiệm tốt nhất và hiểu sâu hơn về văn hóa voi rừng. Mang theo giày đi bộ thoải mái và nước uống.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Vườn quốc gia Yok Đôn (khoảng 40km). Di chuyển bằng xe chuyên dụng hoặc đi bộ trong vườn.\",\n          \"price\": \"200.000đ (vé vào cổng, phí bảo tồn)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Buôn Đôn với các món ăn đặc sản địa phương, sau đó nghỉ ngơi.\",\n          \"reason\": \"Thưởng thức ẩm thực đặc trưng của Buôn Đôn, hỗ trợ kinh tế địa phương và có thời gian thư giãn sau buổi sáng khám phá Vườn quốc gia.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Các quán ăn tại khu du lịch Buôn Đôn hoặc gần Vườn quốc gia Yok Đôn.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy đến quán ăn.\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức cà phê Buôn Ma Thuột và tìm hiểu văn hóa cà phê đặc sắc tại một quán cà phê địa phương.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, trải nghiệm này giúp du khách hiểu sâu hơn về văn hóa cà phê độc đáo, một khía cạnh quan trọng của địa phương.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán cà phê địa phương.\",\n          \"suggestion\": \"Ghé Arul Coffee (17 Trần Nhật Duật, TP. Buôn Ma Thuột) hoặc SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) để trải nghiệm cà phê rang xay tại chỗ.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Buôn Đôn về Buôn Ma Thuột.\",\n          \"price\": \"50.000đ - 100.000đ (chi phí cà phê)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối đặc sản Buôn Ma Thuột và mua sắm quà lưu niệm (cà phê, thịt nai khô).\",\n          \"reason\": \"Kết thúc chuyến đi bằng việc thưởng thức ẩm thực địa phương và mua sắm những món quà đặc trưng của Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng và 300.000đ cho cửa hàng đặc sản.\",\n          \"suggestion\": \"Ăn tối bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Mua sắm cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột) hoặc các cửa hàng đặc sản địa phương.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab.\",\n          \"price\": \"500.000đ (ăn tối, mua sắm quà)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-27 07:59:29');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(43, 7, 'Lịch trình 4 ngày - thiên nhiên, văn hoá', 4, 'thiên nhiên, văn hoá', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Tham quan Hồ Lắk, đi thuyền độc mộc và tìm hiểu văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, gắn liền với văn hóa M\'nông đặc sắc, phù hợp với sở thích thiên nhiên và văn hóa của du khách.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho người dân địa phương (dịch vụ thuyền độc mộc, hướng dẫn viên)\",\n          \"suggestion\": \"Nghỉ tại Lak Tented Camp, ven Hồ Lắk, Huyện Lắk, Đắk Lắk\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km).\",\n          \"price\": \"Vé vào cổng làng/khu vực Hồ Lắk (tùy điểm dừng): 50.000đ. Thuê thuyền độc mộc: 200.000đ/thuyền\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Hồ Lắk (cá nướng, gà nướng) và nghỉ ngơi tại Homestay\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương tươi ngon sau buổi sáng khám phá.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng/homestay địa phương\",\n          \"suggestion\": \"Nhà hàng tại Lak Tented Camp hoặc các quán ăn dân dã ven hồ. Nghỉ trưa tại Lak Tented Camp, ven Hồ Lắk, Huyện Lắk, Đắk Lắk\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"Ăn trưa: 200.000đ - 300.000đ/người. Chi phí nghỉ trưa tại homestay đã bao gồm trong chi phí lưu trú.\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Khám phá Núi Đá Voi Mẹ và nghe kể truyền thuyết\",\n          \"reason\": \"Núi Đá Voi Mẹ là tảng đá nguyên khối lớn nhất Việt Nam, mang vẻ đẹp thiên nhiên độc đáo và câu chuyện văn hóa thú vị, gần Hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho người dân địa phương (nếu có dịch vụ trông xe/hướng dẫn)\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Hồ Lắk đến Núi Đá Voi Mẹ (khoảng 10km)\",\n          \"price\": \"Miễn phí. Chi phí gửi xe: 10.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và trải nghiệm văn hóa cồng chiêng (nếu có tổ chức) hoặc nghỉ ngơi\",\n          \"reason\": \"Kết thúc ngày đầu tiên với trải nghiệm văn hóa địa phương hoặc thư giãn sau một ngày dài.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng/cộng đồng tổ chức cồng chiêng\",\n          \"suggestion\": \"Ăn tối tại nhà hàng ven Hồ Lắk. Ngủ qua đêm tại Lak Tented Camp, ven Hồ Lắk, Huyện Lắk, Đắk Lắk\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"Ăn tối: 200.000đ - 300.000đ/người. Chi phí xem cồng chiêng (nếu có): 100.000đ - 150.000đ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá Thác nước hùng vĩ và Buôn Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur, chiêm ngưỡng vẻ đẹp hùng vĩ của thác nước Tây Nguyên\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước đẹp và hùng vĩ nhất, phù hợp với sở thích thiên nhiên, mang lại trải nghiệm trekking nhẹ nhàng.\",\n          \"community_impact\": \"Dự kiến 30.000đ cho vé vào cổng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Từ Hồ Lắk, di chuyển bằng xe máy hoặc taxi/Grab đến Thác Dray Nur (khoảng 30km).\",\n          \"price\": \"Vé vào cổng: 30.000đ/người\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa gần khu vực thác hoặc di chuyển về Buôn Ma Thuột để ăn trưa và nghỉ ngơi.\",\n          \"reason\": \"Nạp năng lượng sau buổi sáng khám phá thác, sau đó di chuyển về trung tâm thành phố để tiện cho buổi chiều.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn địa phương\",\n          \"suggestion\": \"Quán ăn ven đường gần Thác Dray Nur hoặc Quán Cà Te, 140 Lê Thánh Tông, TP. Buôn Ma Thuột. Nghỉ trưa tại Elephants Hotel, 142 Hai Bà Trưng, TP. Buôn Ma Thuột\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"Ăn trưa: 150.000đ - 250.000đ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, khám phá văn hóa nhà dài, cầu treo và tìm hiểu về voi\",\n          \"reason\": \"Buôn Đôn nổi tiếng với văn hóa voi và nhà dài truyền thống, đáp ứng sở thích văn hóa và thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho cộng đồng Buôn Đôn (vé vào cổng, dịch vụ)\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Từ Buôn Ma Thuột, thuê xe máy hoặc taxi/Grab đến Buôn Đôn (khoảng 50km).\",\n          \"price\": \"Vé vào cổng khu du lịch: 40.000đ/người. Tham quan nhà dài/cầu treo: 30.000đ - 50.000đ/người\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối đặc sản Buôn Ma Thuột và dạo phố\",\n          \"reason\": \"Thưởng thức ẩm thực đa dạng của thủ phủ Tây Nguyên và thư giãn buổi tối.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng địa phương\",\n          \"suggestion\": \"Bún đỏ cô Thu, Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột. Ngủ qua đêm tại Elephants Hotel, 142 Hai Bà Trưng, TP. Buôn Ma Thuột\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc taxi/Grab\",\n          \"price\": \"Ăn tối: 150.000đ - 250.000đ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Văn hóa cà phê và buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Tham quan và thưởng thức cà phê tại Làng cà phê Trung Nguyên hoặc Arul Coffee, tìm hiểu về văn hóa cà phê\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, trải nghiệm này giúp du khách hiểu sâu hơn về văn hóa và ẩm thực đặc trưng của vùng.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán cà phê địa phương\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên, 163 Lý Thái Tổ, TP. Buôn Ma Thuột hoặc Arul Coffee, 17 Trần Nhật Duật, TP. Buôn Ma Thuột\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab\",\n          \"price\": \"Miễn phí vào cổng. Chi phí đồ uống: 50.000đ - 100.000đ/người\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa món địa phương và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức ẩm thực đa dạng của Buôn Ma Thuột và nghỉ ngơi sau buổi sáng.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương\",\n          \"suggestion\": \"Phở hai tô 52, 52 Ngô Quyền, TP. Buôn Ma Thuột. Nghỉ trưa tại Mường Thanh Luxury Buôn Ma Thuột, 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"Ăn trưa: 100.000đ - 200.000đ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê cổ truyền đẹp nhất Buôn Ma Thuột\",\n          \"reason\": \"Khám phá kiến trúc nhà dài truyền thống và đời sống văn hóa của người Ê Đê ngay trong lòng thành phố.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho người dân/cộng đồng (nếu có mua sắm quà lưu niệm)\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"Miễn phí. Chi phí mua sắm quà lưu niệm (nếu có)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và tự do khám phá Buôn Ma Thuột về đêm hoặc mua sắm đặc sản\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương và mua sắm quà lưu niệm trước khi rời Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng/cửa hàng đặc sản\",\n          \"suggestion\": \"Bánh ướt chồng dĩa 45, 45 Lê Thánh Tông, TP. Buôn Ma Thuột. Ngủ qua đêm tại Mường Thanh Luxury Buôn Ma Thuột, 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc taxi/Grab\",\n          \"price\": \"Ăn tối: 150.000đ - 250.000đ/người. Chi phí mua sắm: Tùy nhu cầu\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Thư giãn tại Hồ Ea Kao và mua sắm trước khi kết thúc hành trình\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 8,\n          \"activity\": \"Tham quan Hồ Ea Kao, hít thở không khí trong lành và thư giãn\",\n          \"reason\": \"Hồ Ea Kao là một không gian xanh mát, rộng lớn gần trung tâm thành phố, thích hợp để thư giãn và tận hưởng thiên nhiên trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 0đ\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa các món đặc sản còn lại và mua sắm quà lưu niệm\",\n          \"reason\": \"Kết thúc chuyến đi bằng việc thưởng thức những món ăn yêu thích và mua sắm quà tặng cho người thân.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho quán ăn/cửa hàng đặc sản\",\n          \"suggestion\": \"Các quán ăn gần trung tâm thành phố Buôn Ma Thuột. Mua sắm cà phê, thịt nai khô tại Chợ Buôn Ma Thuột hoặc các cửa hàng đặc sản.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc taxi/Grab\",\n          \"price\": \"Ăn trưa: 150.000đ - 250.000đ/người. Chi phí mua sắm: Tùy nhu cầu\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": null,\n          \"activity\": \"Di chuyển ra sân bay hoặc bến xe, kết thúc hành trình\",\n          \"reason\": \"Đảm bảo thời gian di chuyển và làm thủ tục cho chuyến bay/xe về.\",\n          \"community_impact\": \"Dự kiến 0đ\",\n          \"suggestion\": \"\",\n          \"address\": \"\",\n          \"transport\": \"Taxi/Grab\",\n          \"price\": \"Chi phí taxi/Grab ra sân bay/bến xe: 100.000đ - 200.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Không có hoạt động, du khách đã rời đi\",\n          \"reason\": \"...\",\n          \"community_impact\": \"...\",\n          \"suggestion\": \"\",\n          \"address\": \"\",\n          \"transport\": \"\",\n          \"price\": \"\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-27 08:07:09'),
(44, 7, 'Lịch trình 3 ngày - thiên nhiên, văn hoá', 3, 'thiên nhiên, văn hoá', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk, đi thuyền độc mộc và tìm hiểu văn hóa M\'nông tại buôn Jun hoặc buôn Lê.\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, mang đậm bản sắc văn hóa M\'nông, phù hợp với sở thích thiên nhiên và văn hóa của du khách. Di chuyển đến đây đầu tiên để tận hưởng không khí trong lành buổi sáng.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho người dân/Cơ sở văn hóa cộng đồng địa phương.\",\n          \"suggestion\": \"Lak Tented Camp (ven Hồ Lắk) để trải nghiệm không gian nghỉ dưỡng gần gũi thiên nhiên.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy (150k/ngày) hoặc taxi/ô tô riêng từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km).\",\n          \"price\": \"200.000đ (bao gồm vé tham quan và chi phí thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với đặc sản địa phương tại Hồ Lắk và nghỉ ngơi tại homestay gần hồ.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương để cảm nhận trọn vẹn văn hóa vùng miền và nghỉ ngơi sau buổi sáng tham quan.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn/nhà hàng địa phương.\",\n          \"suggestion\": \"Cơm lam, cá lăng nướng tại nhà hàng ven Hồ Lắk. Nghỉ ngơi tại Lak Tented Camp (ven Hồ Lắk).\",\n          \"address\": \"Ven Hồ Lắk, Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"250.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ, tìm hiểu truyền thuyết kỳ bí.\",\n          \"reason\": \"Địa điểm độc đáo với tảng đá nguyên khối lớn nhất Việt Nam, gần Hồ Lắk, phù hợp để tiếp tục khám phá thiên nhiên và văn hóa truyền thuyết địa phương.\",\n          \"community_impact\": \"Dự kiến 0đ (phí vào cửa miễn phí, có thể mua sắm đồ lưu niệm nhỏ).\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô từ Hồ Lắk đến Núi Đá Voi Mẹ (khoảng 15km).\",\n          \"price\": \"50.000đ (phí gửi xe nếu có)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối tại Buôn Ma Thuột, tự do khám phá thành phố về đêm.\",\n          \"reason\": \"Di chuyển về Buôn Ma Thuột để nghỉ ngơi và chuẩn bị cho ngày hôm sau, đồng thời thưởng thức ẩm thực đa dạng của thành phố.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng/quán ăn địa phương.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ đêm tại Mường Thanh (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk) hoặc Elephants (142 Hai Bà Trưng, TP. Buôn Ma Thuột, Đắk Lắk).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi hoặc xe máy từ Hồ Lắk về Buôn Ma Thuột (khoảng 50km).\",\n          \"price\": \"500.000đ (ăn tối, chi phí di chuyển)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Thám hiểm thác nước hùng vĩ và trải nghiệm văn hóa Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur - một trong những thác nước hùng vĩ nhất Tây Nguyên.\",\n          \"reason\": \"Thác Dray Nur mang vẻ đẹp thiên nhiên hoang sơ, hùng vĩ, phù hợp với sở thích khám phá thiên nhiên của du khách. Vị trí gần Buôn Ma Thuột, tiện lợi cho việc di chuyển.\",\n          \"community_impact\": \"Dự kiến 30.000đ cho ban quản lý khu du lịch.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô từ Buôn Ma Thuột đến thác (khoảng 25km).\",\n          \"price\": \"30.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại hoặc tại nhà hàng gần thác, nghỉ ngơi tại khu vực thác nước.\",\n          \"reason\": \"Tận hưởng không khí trong lành của thác nước, tiếp thêm năng lượng cho buổi chiều. Có thể chuẩn bị đồ ăn nhẹ để dã ngoại.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán ăn địa phương hoặc mua sắm đồ ăn nhẹ.\",\n          \"suggestion\": \"Nhà hàng nhỏ gần thác Dray Nur. Có thể mang theo đồ ăn nhẹ để picnic. Nghỉ ngơi tại khu vực nghỉ mát của thác.\",\n          \"address\": \"Khu vực Thác Dray Nur, Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - buôn làng Ê Đê đẹp nhất Buôn Ma Thuột.\",\n          \"reason\": \"Tìm hiểu văn hóa truyền thống của người Ê Đê, kiến trúc nhà dài và cuộc sống sinh hoạt của người dân bản địa, đáp ứng sở thích văn hóa.\",\n          \"community_impact\": \"Dự kiến 0đ (có thể mua sắm thổ cẩm, quà lưu niệm hỗ trợ cộng đồng).\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Thác Dray Nur về Buôn Ma Thuột.\",\n          \"price\": \"50.000đ (mua sắm quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên và khám phá Làng cà phê Trung Nguyên.\",\n          \"reason\": \"Trải nghiệm văn hóa cà phê đặc trưng của Buôn Ma Thuột và thưởng thức đặc sản ẩm thực.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng/quán cà phê.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông). Uống cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk). Nghỉ đêm tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột, Đắk Lắk).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc Grab/taxi\",\n          \"price\": \"300.000đ (ăn tối, cà phê)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Khám phá Buôn Đôn và văn hóa voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, khám phá làng văn hóa nổi tiếng với nghề săn bắt và thuần dưỡng voi.\",\n          \"reason\": \"Buôn Đôn là điểm đến độc đáo với văn hóa voi đặc sắc, cầu treo và nhà dài truyền thống, phù hợp với sở thích về văn hóa và thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho người dân/Cơ sở du lịch cộng đồng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô từ Buôn Ma Thuột đến Buôn Đôn (khoảng 50km).\",\n          \"price\": \"100.000đ (vé vào cổng, tham quan cầu treo)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với các món đặc sản tại Buôn Đôn.\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương ngay tại Buôn Đôn, tiết kiệm thời gian di chuyển.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Gỏi lá, cơm lam, cá sông Sêrêpôk tại nhà hàng trong khu vực Buôn Đôn. Nghỉ ngơi tại nhà sàn địa phương nếu có dịch vụ.\",\n          \"address\": \"Buôn Đôn, Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ\",\n          \"price\": \"200.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 5,\n          \"activity\": \"Khám phá Vườn quốc gia Yok Đôn, nơi sinh sống của voi rừng và hệ sinh thái đa dạng.\",\n          \"reason\": \"Vườn quốc gia Yok Đôn là điểm đến lý tưởng cho những ai yêu thích thiên nhiên và động vật hoang dã, đặc biệt là voi.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho ban quản lý Vườn quốc gia.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô từ Buôn Đôn đến Vườn quốc gia Yok Đôn (khoảng 5km).\",\n          \"price\": \"50.000đ (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Mua sắm đặc sản Đắk Lắk và ăn tối trước khi kết thúc hành trình.\",\n          \"reason\": \"Mua quà lưu niệm và thưởng thức bữa tối cuối cùng tại Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho các cửa hàng đặc sản/quán ăn địa phương.\",\n          \"suggestion\": \"Mua cà phê, thịt nai khô tại các cửa hàng đặc sản TP. Buôn Ma Thuột. Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột, Đắk Lắk).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc Grab/taxi\",\n          \"price\": \"400.000đ (ăn tối, mua sắm đặc sản)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-27 08:08:13'),
(45, 7, 'Lịch trình 3 ngày - thiên nhiên, văn hoá', 3, 'thiên nhiên, văn hoá', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hành trình khám phá văn hóa và thiên nhiên Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, mang đậm dấu ấn văn hóa M\'nông, rất phù hợp với sở thích thiên nhiên và văn hóa của du khách. Trải nghiệm thuyền độc mộc và tìm hiểu đời sống bản địa.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho dịch vụ thuyền độc mộc của người dân địa phương và các sản phẩm văn hóa.\",\n          \"suggestion\": \"Thuê thuyền độc mộc của người M\'nông để khám phá hồ. Có thể ghé thăm buôn làng gần đó để tìm hiểu thêm về văn hóa.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km).\",\n          \"price\": \"200.000đ (thuê xe máy), 150.000đ (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi tại Hồ Lắk\",\n          \"reason\": \"Nghỉ ngơi và thưởng thức ẩm thực địa phương sau buổi sáng khám phá.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng và homestay địa phương.\",\n          \"suggestion\": \"Ăn trưa tại các nhà hàng ven hồ Lắk với các món ăn đặc sản địa phương. Nghỉ ngơi tại Lak Tented Camp, địa chỉ: ven Hồ Lắk.\",\n          \"address\": \"Ven Hồ Lắk, Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ\",\n          \"reason\": \"Núi Đá Voi Mẹ là một tảng đá nguyên khối lớn nhất Việt Nam, mang truyền thuyết kỳ bí, phù hợp với sở thích khám phá thiên nhiên và văn hóa tâm linh.\",\n          \"community_impact\": \"Dự kiến 0đ (không có phí vào cửa, chủ yếu là chi phí di chuyển).\",\n          \"suggestion\": \"Lên đỉnh núi để ngắm nhìn toàn cảnh Hồ Lắk và khu vực xung quanh. Chuẩn bị giày thể thao để dễ dàng di chuyển.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Hồ Lắk (khoảng 10km).\",\n          \"price\": \"50.000đ (xăng xe/taxi)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và nghỉ ngơi tại Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức ẩm thực và chuẩn bị cho hành trình ngày hôm sau tại trung tâm thành phố.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng và khách sạn/homestay.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu, địa chỉ: Ngã 4 Phan Đình Giót - Lê Hồng Phong. Nghỉ đêm tại Khách sạn Mường Thanh, địa chỉ: 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về lại Buôn Ma Thuột (khoảng 50km).\",\n          \"price\": \"100.000đ (ăn tối), 500.000đ (khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá thác nước hùng vĩ và văn hóa cà phê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Thăm quan Thác Dray Nur\",\n          \"reason\": \"Thác Dray Nur là một trong những thác nước hùng vĩ nhất Tây Nguyên, mang vẻ đẹp thiên nhiên hoang sơ, rất phù hợp với sở thích khám phá thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 50.000đ vé vào cửa, đóng góp cho việc bảo tồn cảnh quan.\",\n          \"suggestion\": \"Tận hưởng không khí trong lành, chụp ảnh và cảm nhận sự hùng vĩ của thác nước. Nên đi vào buổi sáng để tránh đông đúc và nắng gắt.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Thác Dray Nur (khoảng 30km).\",\n          \"price\": \"30.000đ (vé vào cổng), 100.000đ (xăng xe/taxi)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi gần khu vực thác\",\n          \"reason\": \"Nghỉ ngơi và thưởng thức ẩm thực sau buổi sáng trekking tại thác.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại các nhà hàng ven đường gần Thác Dray Nur. Nghỉ ngơi tại một quán cà phê hoặc homestay có không gian yên tĩnh.\",\n          \"address\": \"Khu vực gần Thác Dray Nur\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"100.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa Cà phê Buôn Ma Thuột\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê Việt Nam, trải nghiệm văn hóa cà phê đặc sắc là điều không thể bỏ qua, phù hợp với sở thích văn hóa và ẩm thực.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho sản phẩm cà phê và dịch vụ tại quán.\",\n          \"suggestion\": \"Tham quan Làng cà phê Trung Nguyên (163 Lý Thái Tổ) hoặc thưởng thức cà phê tại SOUL Roastery (87 Nguyễn Khuyến) để hiểu rõ hơn về quy trình sản xuất cà phê và thưởng thức hương vị đặc trưng.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về lại TP. Buôn Ma Thuột.\",\n          \"price\": \"50.000đ (cà phê), 50.000đ (xăng xe/taxi)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và dạo phố\",\n          \"reason\": \"Khám phá ẩm thực đa dạng của Buôn Ma Thuột và tận hưởng không khí buổi tối.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng và dịch vụ giải trí.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te, địa chỉ: 140 Lê Thánh Tông với các món ăn đặc trưng Tây Nguyên. Sau đó, dạo quanh chợ đêm Buôn Ma Thuột. Nghỉ đêm tại Khách sạn Elephants, địa chỉ: 142 Hai Bà Trưng, TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"150.000đ (ăn tối), 500.000đ (khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Khám phá văn hóa Buôn Đôn và buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn - Làng văn hóa voi\",\n          \"reason\": \"Buôn Đôn nổi tiếng với nghề săn bắt và thuần dưỡng voi, mang đậm bản sắc văn hóa Tây Nguyên, rất phù hợp với sở thích văn hóa và thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho dịch vụ tham quan và các sản phẩm thủ công mỹ nghệ của người dân.\",\n          \"suggestion\": \"Tham quan nhà sàn cổ, cầu treo Buôn Đôn. Tìm hiểu về văn hóa voi của người M\'nông. (Lưu ý không khuyến khích cưỡi voi để bảo vệ loài voi).\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Buôn Đôn (khoảng 40km).\",\n          \"price\": \"50.000đ (vé vào cổng), 150.000đ (xăng xe/taxi)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Buôn Đôn\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương sau buổi sáng khám phá văn hóa Buôn Đôn.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại các nhà hàng đặc sản ở Buôn Đôn, thử các món ăn như cơm lam, gà nướng. Nghỉ ngơi tại một quán cà phê gần đó.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"120.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Khám phá Buôn Akô Dhông\",\n          \"reason\": \"Buôn Akô Dhông là buôn làng Ê Đê đẹp nhất Buôn Ma Thuột, nơi lưu giữ kiến trúc nhà dài truyền thống và văn hóa bản địa, phù hợp với sở thích văn hóa.\",\n          \"community_impact\": \"Dự kiến 0đ (không có phí vào cửa, chủ yếu là chi phí di chuyển).\",\n          \"suggestion\": \"Đi bộ quanh buôn làng, chiêm ngưỡng kiến trúc nhà dài truyền thống, giao lưu với người dân địa phương. Mua sắm các sản phẩm thủ công mỹ nghệ.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ Buôn Đôn về lại TP. Buôn Ma Thuột (khoảng 40km), sau đó di chuyển trong thành phố.\",\n          \"price\": \"50.000đ (xăng xe/taxi)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và kết thúc hành trình\",\n          \"reason\": \"Thưởng thức bữa tối cuối cùng và chuẩn bị rời Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52, địa chỉ: 52 Ngô Quyền hoặc Bánh ướt chồng dĩa 45, địa chỉ: 45 Lê Thánh Tông để thưởng thức ẩm thực đặc trưng. Sau đó, di chuyển ra sân bay/bến xe.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi/Grab ra sân bay Buôn Ma Thuột hoặc bến xe liên tỉnh.\",\n          \"price\": \"80.000đ (ăn tối), 100.000đ (taxi ra sân bay/bến xe)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-27 08:13:43'),
(46, 7, 'Lịch trình 2 ngày - văn hoá', 2, 'văn hoá', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hành trình khám phá Văn hóa M\'nông và Cà phê Ban Mê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Đón bình minh trên Hồ Lắk và tìm hiểu văn hóa M\'nông\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt lớn thứ 2 Việt Nam, cảnh quan bình minh trên hồ rất đẹp. Đây là cơ hội tuyệt vời để tìm hiểu văn hóa M\'nông bản địa, đặc biệt là văn hóa thuyền độc mộc truyền thống.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho người dân địa phương khi trải nghiệm thuyền độc mộc và tìm hiểu văn hóa.\",\n          \"suggestion\": \"Nên ở lại Homestay Lak Tented Camp để tiện ngắm bình minh và trải nghiệm Hồ Lắk sớm nhất. Địa chỉ: ven Hồ Lắk, Huyện Lắk, Đắk Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi từ trung tâm Buôn Ma Thuột đến Hồ Lắk (khoảng 50km). Di chuyển bằng thuyền độc mộc trên hồ.\",\n          \"price\": \"50.000đ (vé vào cổng) + 150.000đ (thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Hồ Lắk và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức các món ăn địa phương tươi ngon sau buổi sáng hoạt động, nghỉ ngơi lấy lại sức.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho các nhà hàng địa phương quanh Hồ Lắk.\",\n          \"suggestion\": \"Nghỉ trưa tại Lak Tented Camp hoặc nhà hàng ven Hồ Lắk. Gợi ý khách sạn để ngủ qua đêm: Mường Thanh Luxury Buôn Ma Thuột, địa chỉ: 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"150.000đ - 200.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ và di chuyển về Buôn Ma Thuột\",\n          \"reason\": \"Núi Đá Voi Mẹ là tảng đá nguyên khối lớn nhất Việt Nam, gắn liền với nhiều truyền thuyết văn hóa địa phương, tạo điểm nhấn độc đáo cho hành trình văn hóa.\",\n          \"community_impact\": \"Dự kiến 0đ (tham quan miễn phí).\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi từ Hồ Lắk đến Núi Đá Voi Mẹ, sau đó di chuyển về TP. Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê Buôn Ma Thuột và thưởng thức ẩm thực địa phương\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, buổi tối là thời điểm lý tưởng để thư giãn và khám phá các quán cà phê độc đáo, đồng thời thưởng thức ẩm thực đa dạng của thành phố.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho các quán cà phê và nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Thưởng thức cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ) hoặc SOUL Roastery (87 Nguyễn Khuyến). Ngủ qua đêm tại Mường Thanh Luxury Buôn Ma Thuột, địa chỉ: 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc Grab/taxi\",\n          \"price\": \"100.000đ - 200.000đ (ăn tối) + 50.000đ - 100.000đ (cà phê)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Khám phá Buôn làng Ê Đê và Di sản Voi Rừng\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông và tìm hiểu văn hóa Ê Đê\",\n          \"reason\": \"Buôn Akô Dhông là buôn làng Ê Đê đẹp nhất Buôn Ma Thuột, giữ gìn nét văn hóa truyền thống với nhà dài và không gian sống độc đáo. Buổi sáng là thời điểm yên bình nhất để cảm nhận.\",\n          \"community_impact\": \"Dự kiến 0đ (tham quan miễn phí).\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc Grab/taxi\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Buôn Ma Thuột\",\n          \"reason\": \"Thưởng thức ẩm thực đa dạng của thành phố sau buổi sáng tham quan văn hóa.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho các nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Phở hai tô 52 (52 Ngô Quyền) hoặc Quán Cà Te (140 Lê Thánh Tông). Gợi ý khách sạn để nghỉ ngơi buổi trưa: Mường Thanh Luxury Buôn Ma Thuột, địa chỉ: 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc Grab/taxi\",\n          \"price\": \"100.000đ - 150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Khám phá Buôn Đôn - Làng văn hóa voi\",\n          \"reason\": \"Buôn Đôn nổi tiếng với nghề săn bắt và thuần dưỡng voi, là nơi tuyệt vời để tìm hiểu về mối quan hệ giữa con người và loài voi ở Tây Nguyên. Buổi chiều mát mẻ hơn để đi bộ khám phá.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho các dịch vụ du lịch tại Buôn Đôn, hỗ trợ cộng đồng địa phương.\",\n          \"suggestion\": \"Có thể mua quà lưu niệm đặc sản Buôn Đôn tại đây.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi từ TP. Buôn Ma Thuột đến Buôn Đôn (khoảng 40km).\",\n          \"price\": \"40.000đ (vé vào cổng) + 100.000đ - 150.000đ (trải nghiệm cầu treo/nhà dài)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và kết thúc hành trình\",\n          \"reason\": \"Thưởng thức bữa tối cuối cùng tại Đắk Lắk với những món ăn đậm chất Tây Nguyên trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn tối tại nhà hàng ở TP. Buôn Ma Thuột. Có thể mua cà phê hoặc đặc sản địa phương khác làm quà. Gợi ý khách sạn để ngủ qua đêm: Mường Thanh Luxury Buôn Ma Thuột, địa chỉ: 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc Grab/taxi\",\n          \"price\": \"150.000đ - 250.000đ (ăn tối)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-27 08:40:24'),
(47, NULL, 'Lịch trình 2 ngày - ẩm thực, trekking', 2, 'ẩm thực, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Thác Nước Hùng Vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức cà phê Buôn Ma Thuột và tìm hiểu văn hóa cà phê\",\n          \"reason\": \"Ưu tiên sở thích ẩm thực và trải nghiệm văn hóa địa phương. Buổi sáng sớm là thời điểm lý tưởng để thưởng thức cà phê và cảm nhận không khí trong lành.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho quán cà phê địa phương.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên, 163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk. Hoặc SOUL Roastery, 87 Nguyễn Khuyến, TP. Buôn Ma Thuột, Đắk Lắk.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab để di chuyển trong thành phố.\",\n          \"price\": \"50.000đ - 100.000đ (cho đồ uống và mua sắm nhỏ)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Buôn Ma Thuột và nghỉ ngơi\",\n          \"reason\": \"Nạp năng lượng cho buổi chiều khám phá.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Bún đỏ cô Thu, Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột, Đắk Lắk. Nghỉ ngơi tại Mường Thanh Luxury Buôn Ma Thuột, 81 Nguyễn Tất Thành, TP. Buôn Ma Thuột.\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc đi bộ tùy địa điểm ăn trưa.\",\n          \"price\": \"100.000đ - 150.000đ (cho bữa ăn)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking và khám phá Thác Dray Nur\",\n          \"reason\": \"Thỏa mãn sở thích trekking và chiêm ngưỡng vẻ đẹp hùng vĩ của thác nước vào buổi chiều, tránh nắng gắt.\",\n          \"community_impact\": \"Dự kiến 50.000đ tiền vé vào cổng cho người dân địa phương quản lý.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến thác (khoảng 30km).\",\n          \"price\": \"30.000đ (vé vào cổng) + 100.000đ (thuê xe máy)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và tự do khám phá Buôn Ma Thuột về đêm\",\n          \"reason\": \"Kết thúc một ngày khám phá bằng ẩm thực địa phương và nghỉ ngơi chuẩn bị cho ngày tiếp theo.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng/quán ăn địa phương và dịch vụ lưu trú.\",\n          \"suggestion\": \"Quán Cà Te, 140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk. Ngủ qua đêm tại Elephants Hotel, 142 Hai Bà Trưng, TP. Buôn Ma Thuột.\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi.\",\n          \"price\": \"150.000đ - 250.000đ (ăn tối) + 400.000đ - 700.000đ (khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hồ Lắk - Văn hóa M\'nông và Hoàng hôn Núi Voi Mẹ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk, trải nghiệm thuyền độc mộc và văn hóa M\'nông\",\n          \"reason\": \"Buổi sáng sớm là thời điểm lý tưởng để ngắm cảnh hồ, tránh nắng gắt và cảm nhận vẻ đẹp thanh bình của Hồ Lắk. Ưu tiên trải nghiệm văn hóa địa phương.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho dịch vụ thuyền độc mộc và giao lưu văn hóa M\'nông.\",\n          \"suggestion\": \"Lak Tented Camp (nếu muốn nghỉ dưỡng), ven Hồ Lắk, Huyện Lắk, Đắk Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Hồ Lắk (khoảng 50km).\",\n          \"price\": \"50.000đ (vé tham quan) + 100.000đ - 150.000đ (thuê thuyền độc mộc) + 150.000đ (chi phí di chuyển)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Hồ Lắk và nghỉ ngơi\",\n          \"reason\": \"Nạp lại năng lượng sau buổi sáng tham quan hồ.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng/quán ăn địa phương gần Hồ Lắk.\",\n          \"suggestion\": \"Cư H\'Lăm Restaurant & Homestay, Ea Pốk, Buôn Ma Thuột (trên đường về BMT). Hoặc các quán ăn nhỏ ven Hồ Lắk.\",\n          \"address\": \"Gần Hồ Lắk hoặc trên đường về Buôn Ma Thuột\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"120.000đ - 180.000đ (cho bữa ăn)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Ngắm hoàng hôn tại Núi Đá Voi Mẹ\",\n          \"reason\": \"Trải nghiệm ngắm hoàng hôn theo yêu cầu, tại một địa điểm có cảnh quan độc đáo và truyền thuyết kỳ bí, không quá xa Hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 0đ (phí tham quan miễn phí).\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi từ Hồ Lắk đến Núi Đá Voi Mẹ (gần Hồ Lắk).\",\n          \"price\": \"0đ (vé vào cổng, chỉ có chi phí xăng xe)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối chia tay Đắk Lắk và chuẩn bị kết thúc hành trình\",\n          \"reason\": \"Thưởng thức ẩm thực cuối cùng trước khi rời Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng đặc sản.\",\n          \"suggestion\": \"Phở hai tô 52, 52 Ngô Quyền, TP. Buôn Ma Thuột, Đắk Lắk. Ngủ qua đêm tại An Homestay, 137/91 Thôi Hữu, TP. Buôn Ma Thuột (nếu muốn ở lại thêm).\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab về lại Buôn Ma Thuột.\",\n          \"price\": \"150.000đ - 250.000đ (ăn tối)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-28 02:12:47');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(48, 7, 'Lịch trình 3 ngày - thiên nhiên, gia đình', 3, 'thiên nhiên, gia đình', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk và trải nghiệm thuyền độc mộc, tìm hiểu văn hóa M\'nông.\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, thích hợp cho gia đình muốn khám phá thiên nhiên và văn hóa bản địa. Hoạt động nhẹ nhàng phù hợp mọi lứa tuổi.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho dịch vụ thuyền độc mộc của người dân địa phương.\",\n          \"suggestion\": \"Lak Tented Camp (ven Hồ Lắk) - nếu muốn có trải nghiệm độc đáo và gần gũi thiên nhiên.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe ô tô hoặc xe máy di chuyển từ Buôn Ma Thuột đến Hồ Lắk (~50km).\",\n          \"price\": \"300.000đ (bao gồm vé vào cổng, dịch vụ thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi tại khu vực Hồ Lắk.\",\n          \"reason\": \"Nghỉ ngơi sau buổi sáng tham quan, thưởng thức ẩm thực địa phương.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Nhà hàng tại Lak Tented Camp hoặc Cư H\'Lăm Restaurant & Homestay (Ea Pốk) nếu muốn tìm chỗ nghỉ có không gian riêng tư hơn. Cư H\'Lăm Restaurant & Homestay (Ea Pốk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe cá nhân.\",\n          \"price\": \"250.000đ/người (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ, khám phá truyền thuyết và chụp ảnh.\",\n          \"reason\": \"Một điểm đến độc đáo với cảnh quan thiên nhiên hùng vĩ và câu chuyện văn hóa hấp dẫn, phù hợp cho gia đình.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho người dân địa phương trông giữ xe hoặc dịch vụ nhỏ.\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy/ô tô từ Hồ Lắk.\",\n          \"price\": \"50.000đ (phí gửi xe)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Di chuyển về Buôn Ma Thuột, ăn tối và nhận phòng khách sạn.\",\n          \"reason\": \"Nghỉ ngơi tại trung tâm thành phố để tiện di chuyển các điểm tham quan vào ngày hôm sau.\",\n          \"community_impact\": \"Dự kiến 500.000đ cho nhà hàng địa phương và 1.000.000đ cho khách sạn.\",\n          \"suggestion\": \"Quán Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) cho bữa tối. Khách sạn Mường Thanh (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk) hoặc Khách sạn Elephants (142 Hai Bà Trưng, TP. Buôn Ma Thuột, Đắk Lắk) để nghỉ đêm.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe ô tô hoặc taxi từ Hồ Lắk về Buôn Ma Thuột.\",\n          \"price\": \"300.000đ/người (ăn tối), 1.000.000đ/đêm (khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Thám hiểm Thác nước hùng vĩ và văn hóa Cà phê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur, khám phá vẻ đẹp hùng vĩ của một trong những thác nước lớn nhất Tây Nguyên.\",\n          \"reason\": \"Thích hợp cho gia đình yêu thiên nhiên, muốn trải nghiệm cảnh quan hùng vĩ và đi bộ nhẹ nhàng.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho người dân địa phương bán đồ lưu niệm.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô từ trung tâm Buôn Ma Thuột (~25km).\",\n          \"price\": \"30.000đ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với đặc sản địa phương và nghỉ ngơi.\",\n          \"reason\": \"Nghỉ ngơi và nạp năng lượng sau buổi sáng tham quan thác nước.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Nhà hàng tại khu vực Thác Dray Nur hoặc di chuyển về gần trung tâm để có nhiều lựa chọn hơn. Nghỉ ngơi tại khách sạn đã đặt đêm qua hoặc tìm một quán cà phê yên tĩnh.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng xe cá nhân.\",\n          \"price\": \"200.000đ/người (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 6,\n          \"activity\": \"Khám phá văn hóa cà phê Buôn Ma Thuột, thưởng thức cà phê và mua sắm đặc sản.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, hoạt động này giúp gia đình tìm hiểu về đặc trưng văn hóa và thư giãn.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho quán cà phê và cửa hàng đặc sản địa phương.\",\n          \"suggestion\": \"Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk) hoặc SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột, Đắk Lắk).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi trong thành phố.\",\n          \"price\": \"100.000đ/người (thức uống), 200.000đ (mua sắm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và dạo phố Buôn Ma Thuột.\",\n          \"reason\": \"Tận hưởng không khí buổi tối của thành phố, thưởng thức ẩm thực đa dạng.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng địa phương và 1.000.000đ cho khách sạn.\",\n          \"suggestion\": \"Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk) cho bữa tối. Tiếp tục lưu trú tại Khách sạn Mường Thanh (81 Nguyễn Tất Thành, TP. Buôn Ma Thuột, Đắk Lắk) hoặc Khách sạn Elephants (142 Hai Bà Trưng, TP. Buôn Ma Thuột, Đắk Lắk).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc taxi trong thành phố.\",\n          \"price\": \"250.000đ/người (ăn tối), 1.000.000đ/đêm (khách sạn)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Văn hóa Tây Nguyên và cảnh quan sinh thái\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Thăm Buôn Đôn, tìm hiểu văn hóa săn bắt và thuần dưỡng voi, khám phá nhà dài truyền thống và cầu treo.\",\n          \"reason\": \"Hoạt động mang tính văn hóa và giáo dục cao, phù hợp với gia đình, giúp hiểu hơn về phong tục tập quán của người dân tộc bản địa.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho các dịch vụ du lịch tại Buôn Đôn của người dân địa phương.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy hoặc taxi/ô tô từ Buôn Ma Thuột đến Buôn Đôn (~40km).\",\n          \"price\": \"150.000đ/người (vé vào cổng và các hoạt động)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại Buôn Đôn hoặc quay về Buôn Ma Thuột.\",\n          \"reason\": \"Nghỉ ngơi và thưởng thức ẩm thực đặc trưng sau buổi tham quan Buôn Đôn.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Thưởng thức các món ăn từ thịt rừng (nếu có) tại Buôn Đôn. Nếu về Buôn Ma Thuột, có thể thử Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột, Đắk Lắk).\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe cá nhân.\",\n          \"price\": \"200.000đ/người (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê lâu đời và đẹp nhất Buôn Ma Thuột.\",\n          \"reason\": \"Hoạt động nhẹ nhàng cuối chuyến đi, khám phá kiến trúc nhà dài truyền thống và không gian văn hóa đặc sắc ngay trong thành phố.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho các sản phẩm thủ công nhỏ nếu mua.\",\n          \"suggestion\": \"\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi trong thành phố.\",\n          \"price\": \"Free\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối, mua sắm quà lưu niệm và kết thúc chuyến đi.\",\n          \"reason\": \"Thưởng thức bữa ăn cuối cùng tại Đắk Lắk và chuẩn bị rời đi.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng địa phương và các cửa hàng đặc sản.\",\n          \"suggestion\": \"Quán Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk). Mua cà phê, thịt nai khô tại các cửa hàng đặc sản trung tâm thành phố. Khách sạn Đam San Hotel (212 Nguyễn Công Trứ, TP. Buôn Ma Thuột, Đắk Lắk) nếu cần thêm một đêm nghỉ trước khi rời đi.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc taxi trong thành phố.\",\n          \"price\": \"250.000đ/người (ăn tối), 300.000đ (mua sắm)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-28 02:19:37'),
(49, 7, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Exploring Buon Ma Thuot\'s Culture and Coffee Heritage\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 6,\n          \"activity\": \"Experience the coffee culture at Buon Ma Thuot Coffee\",\n          \"reason\": \"Buon Ma Thuot is the coffee capital of Vietnam, perfect for experiencing the local culture and taste. This aligns with the \'văn hoá\' and \'ẩm thực\' preferences.\",\n          \"community_impact\": \"Expected 100,000 VND to locals for coffee and souvenirs.\",\n          \"suggestion\": \"Visit Trung Nguyen Coffee Village, 163 Ly Thai To, Buon Ma Thuot. Try various local coffee blends.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike or taxi\",\n          \"price\": \"50,000 VND - 100,000 VND (coffee tasting)\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch and rest\",\n          \"reason\": \"Enjoy local cuisine and relax after the morning\'s activities.\",\n          \"community_impact\": \"Expected 150,000 VND to locals for lunch.\",\n          \"suggestion\": \"Lunch at Bun do Co Thu, Phan Dinh Giot - Le Hong Phong, Buon Ma Thuot. For rest, consider checking into Elephants Hotel, 142 Hai Ba Trung, Buon Ma Thuot, for convenience.\",\n          \"address\": \"Phan Dinh Giot - Le Hong Phong, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike or walking\",\n          \"price\": \"80,000 VND - 150,000 VND (lunch)\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 7,\n          \"activity\": \"Visit Ako Dhong Village\",\n          \"reason\": \"To immerse in the traditional E De culture, aligning with the \'văn hoá\' preference, and it\'s conveniently located within the city.\",\n          \"community_impact\": \"Expected 50,000 VND - 100,000 VND to locals for small purchases or donations.\",\n          \"suggestion\": \"Explore the longhouses and learn about the local customs. Consider buying traditional crafts.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike or taxi\",\n          \"price\": \"Free (entrance), 50,000 VND - 100,000 VND (optional souvenir)\"\n        },\n        {\n          \"time\": \"Evening\",\n          \"destination_id\": null,\n          \"activity\": \"Dinner and relaxing\",\n          \"reason\": \"Enjoy more local flavors and unwind.\",\n          \"community_impact\": \"Expected 200,000 VND to locals for dinner and accommodation.\",\n          \"suggestion\": \"Dinner at Quan Ca Te, 140 Le Thanh Tong, Buon Ma Thuot, for local dishes. Stay at Elephants Hotel, 142 Hai Ba Trung, Buon Ma Thuot.\",\n          \"address\": \"140 Le Thanh Tong, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike or walking\",\n          \"price\": \"150,000 VND - 250,000 VND (dinner), 500,000 VND - 1,000,000 VND (hotel)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Lak Lake\'s Serenity and M\'nong Heritage\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 1,\n          \"activity\": \"Explore Lak Lake and M\'nong culture\",\n          \"reason\": \"Lak Lake is Vietnam\'s second-largest natural freshwater lake, offering beautiful scenery and a deep connection to M\'nong culture, fitting the \'văn hoá\' and \'thiên nhiên\' preferences.\",\n          \"community_impact\": \"Expected 200,000 VND to locals for boat rides or cultural experiences.\",\n          \"suggestion\": \"Enjoy a traditional dugout canoe ride on the lake. Visit local M\'nong villages around the lake.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Car or motorbike (approx. 1 hour 30 min drive from Buon Ma Thuot)\",\n          \"price\": \"50,000 VND - 150,000 VND (boat ride, village entrance)\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch and rest near Lak Lake\",\n          \"reason\": \"Convenient for a break after exploring the lake and enjoying local food.\",\n          \"community_impact\": \"Expected 150,000 VND to locals for lunch.\",\n          \"suggestion\": \"Enjoy lunch at a local restaurant by Lak Lake. Consider a short rest at Lak Tented Camp, Lak Lake, for scenic views and comfort.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Walking\",\n          \"price\": \"80,000 VND - 150,000 VND (lunch)\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 16,\n          \"activity\": \"Visit Mother Elephant Rock (Núi Đá Voi Mẹ)\",\n          \"reason\": \"A significant natural landmark with local legends, offering unique cultural and natural beauty. It\'s relatively close to Lak Lake, avoiding extensive travel.\",\n          \"community_impact\": \"Expected 20,000 VND to locals for parking or small snacks.\",\n          \"suggestion\": \"Climb the rock for panoramic views of the surrounding landscape. Learn about the legends associated with the rock.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Motorbike or car (short drive from Lak Lake)\",\n          \"price\": \"Free (entrance), 10,000 VND - 20,000 VND (parking)\"\n        },\n        {\n          \"time\": \"Evening\",\n          \"destination_id\": null,\n          \"activity\": \"Return to Buon Ma Thuot for dinner and departure/rest\",\n          \"reason\": \"Enjoy a final local meal and prepare for departure or a comfortable night\'s rest.\",\n          \"community_impact\": \"Expected 200,000 VND to locals for dinner and accommodation.\",\n          \"suggestion\": \"Dinner at Pho 52, 52 Ngo Quyen, Buon Ma Thuot. If staying, consider Elephants Hotel, 142 Hai Ba Trung, Buon Ma Thuot, for consistency.\",\n          \"address\": \"52 Ngo Quyen, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Car or motorbike (return journey to Buon Ma Thuot)\",\n          \"price\": \"100,000 VND - 200,000 VND (dinner), 500,000 VND - 1,000,000 VND (optional hotel)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-29 06:00:08'),
(50, 7, 'Lịch trình 3 ngày - văn hoá, trekking', 3, 'văn hoá, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Hồ Lắk và văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Đạp xe hoặc đi bộ ven Hồ Lắk, chiêm ngưỡng bình minh trên hồ và tìm hiểu văn hóa M\'nông. Trải nghiệm chèo thuyền độc mộc trên hồ.\",\n          \"reason\": \"Hồ Lắk là hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, mang vẻ đẹp hùng vĩ của Tây Nguyên và văn hóa đặc trưng của người M\'nông. Bình minh trên hồ rất đẹp.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho thuê thuyền độc mộc/hướng dẫn viên địa phương.\",\n          \"suggestion\": \"Nghỉ ngơi tại Lak Tented Camp, ven Hồ Lắk để tiện ngắm bình minh và hoàng hôn.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy từ Buôn Ma Thuột đi Hồ Lắk (khoảng 50km). Sau đó di chuyển bằng xe đạp hoặc đi bộ quanh hồ.\",\n          \"price\": \"200.000đ (thuê xe máy) + 150.000đ (chèo thuyền)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương tại khu vực Hồ Lắk và nghỉ ngơi.\",\n          \"reason\": \"Trải nghiệm ẩm thực địa phương sau buổi sáng tham quan năng động.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Nhà hàng tại Lak Tented Camp hoặc các quán ăn nhỏ ven hồ. Nghỉ trưa tại Lak Tented Camp (ven Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Tham quan Núi Đá Voi Mẹ, tìm hiểu truyền thuyết kỳ bí và ngắm hoàng hôn từ đỉnh núi.\",\n          \"reason\": \"Núi Đá Voi Mẹ là một biểu tượng thiên nhiên độc đáo của Đắk Lắk, mang trong mình những câu chuyện văn hóa thú vị. Ngắm hoàng hôn tại đây rất ấn tượng.\",\n          \"community_impact\": \"Dự kiến 0đ (phí vào cửa miễn phí).\",\n          \"suggestion\": \"\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy từ Hồ Lắk đến Núi Đá Voi Mẹ (khoảng 10km)\",\n          \"price\": \"50.000đ (gửi xe nếu có)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và nghỉ ngơi tại Hồ Lắk, trải nghiệm không gian yên bình của núi rừng.\",\n          \"reason\": \"Tiếp tục tận hưởng không khí trong lành, mát mẻ tại Hồ Lắk, chuẩn bị cho ngày tiếp theo.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn địa phương và 500.000đ cho homestay/khách sạn.\",\n          \"suggestion\": \"Ăn tối tại nhà hàng địa phương ven Hồ Lắk. Nghỉ đêm tại Lak Tented Camp (ven Hồ Lắk) hoặc Cư H\'Lăm Restaurant & Homestay (Ea Pốk, Buôn Ma Thuột - nếu muốn di chuyển về gần trung tâm hơn).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ\",\n          \"price\": \"200.000đ (ăn tối) + 500.000đ (ngủ đêm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình khám phá thác nước hùng vĩ và văn hóa Buôn Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking và khám phá Thác Dray Nur hùng vĩ. Ngắm cảnh và chụp ảnh tại một trong những thác nước đẹp nhất Tây Nguyên.\",\n          \"reason\": \"Thác Dray Nur là một điểm đến thiên nhiên ấn tượng, phù hợp với sở thích trekking và mang lại trải nghiệm khám phá đáng giá vào buổi sáng sớm.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho vé vào cổng.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy từ Hồ Lắk về hướng Buôn Ma Thuột rồi rẽ đi Thác Dray Nur (khoảng 50km).\",\n          \"price\": \"30.000đ (vé vào cổng) + 10.000đ (gửi xe)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi tại khu vực gần Thác Dray Nur hoặc di chuyển về Buôn Ma Thuột.\",\n          \"reason\": \"Nạp lại năng lượng sau buổi sáng trekking.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Quán ăn địa phương gần thác hoặc nhà hàng tại Buôn Ma Thuột. Nghỉ trưa tại Khách sạn Elephants (142 Hai Bà Trưng) hoặc Homestay Lee\'s House (55 đ.số 3, Cư Bur) tại Buôn Ma Thuột.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk hoặc TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu văn hóa nhà dài, cầu treo và nghề săn bắt voi truyền thống.\",\n          \"reason\": \"Buôn Đôn là cái nôi của văn hóa voi rừng Tây Nguyên, nơi du khách có thể khám phá những nét văn hóa độc đáo của đồng bào Ê Đê, M\'nông.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho vé tham quan và mua sắm sản phẩm địa phương.\",\n          \"suggestion\": \"Thưởng thức cà phê Buôn Đôn tại các quán nhỏ trong buôn.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy từ Thác Dray Nur hoặc Buôn Ma Thuột đến Buôn Đôn (khoảng 20-30km).\",\n          \"price\": \"50.000đ (vé vào cổng khu du lịch Buôn Đôn) + 10.000đ (gửi xe)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối và trải nghiệm văn hóa cà phê Buôn Ma Thuột.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê, không thể bỏ qua trải nghiệm thưởng thức cà phê và ẩm thực đặc trưng tại đây.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho quán ăn và 50.000đ cho quán cà phê.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) hoặc Phở hai tô 52 (52 Ngô Quyền). Thưởng thức cà phê tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ) hoặc SOUL Roastery (87 Nguyễn Khuyến). Nghỉ đêm tại Khách sạn Elephants (142 Hai Bà Trưng) hoặc Mường Thanh (81 Nguyễn Tất Thành).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"250.000đ (ăn tối & cà phê) + 700.000đ (ngủ đêm)\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Thiên nhiên xanh mát và mua sắm đặc sản\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 5,\n          \"activity\": \"Khám phá Vườn Quốc gia Yok Đôn. Tham gia các hoạt động sinh thái như đi bộ đường dài, ngắm cảnh rừng nguyên sinh.\",\n          \"reason\": \"Vườn Quốc gia Yok Đôn là nơi bảo tồn đa dạng sinh học lớn nhất Việt Nam, phù hợp với sở thích thiên nhiên và trekking của du khách. Buổi sáng là thời điểm lý tưởng để khám phá.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho vé vào cổng và dịch vụ hướng dẫn viên.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy từ Buôn Ma Thuột đến Vườn Quốc gia Yok Đôn (khoảng 40km).\",\n          \"price\": \"60.000đ (vé vào cổng) + 10.000đ (gửi xe)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa tại khu vực Vườn Quốc gia Yok Đôn hoặc quay về Buôn Ma Thuột.\",\n          \"reason\": \"Nạp năng lượng sau buổi sáng đi bộ dài trong rừng.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho quán ăn địa phương.\",\n          \"suggestion\": \"Quán ăn trong khu vực Vườn Quốc gia hoặc các nhà hàng tại Buôn Ma Thuột.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk hoặc TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"150.000đ (ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, tìm hiểu văn hóa Ê Đê và mua sắm đặc sản địa phương.\",\n          \"reason\": \"Buôn Akô Dhông là một buôn làng truyền thống đẹp ngay trong lòng thành phố, thuận tiện cho việc tham quan và mua sắm quà lưu niệm trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho mua sắm đặc sản (cà phê, thịt nai khô, mật tự nhiên).\",\n          \"suggestion\": \"Mua cà phê tại các cửa hàng đặc sản địa phương. Các sản phẩm OCOP cũng rất đáng để tham khảo.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (tham quan) + 200.000đ (mua sắm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối, tự do mua sắm và chuẩn bị ra sân bay/bến xe.\",\n          \"reason\": \"Thưởng thức bữa tối cuối cùng tại Buôn Ma Thuột và mua những món quà lưu niệm còn sót lại.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho bữa tối.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te (140 Lê Thánh Tông) để thử các món ăn địa phương.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"200.000đ (ăn tối)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-29 06:13:23'),
(51, 7, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Buôn Ma Thuột và Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông, tìm hiểu văn hóa Ê Đê truyền thống, kiến trúc nhà dài và cuộc sống sinh hoạt của người dân bản địa.\",\n          \"reason\": \"Buôn Akô Dhông là buôn làng Ê Đê đẹp nhất Buôn Ma Thuột, đáp ứng sở thích tìm hiểu văn hóa của du khách.\",\n          \"community_impact\": \"Dự kiến 100.000đ mua các sản phẩm lưu niệm thủ công của người dân.\",\n          \"suggestion\": \"Thuê xe máy để di chuyển tự do trong thành phố. Giá thuê xe máy khoảng 100.000 - 150.000đ/ngày.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"50.000đ (Chi phí thuê xe máy một nửa ngày)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực địa phương và nghỉ ngơi.\",\n          \"reason\": \"Trải nghiệm các món ăn đặc trưng của Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho bữa trưa tại quán ăn địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Bún đỏ cô Thu, địa chỉ: Ngã 4 Phan Đình Giót - Lê Hồng Phong. Nghỉ trưa tại Elephants Hotel, địa chỉ: 142 Hai Bà Trưng.\",\n          \"address\": \"Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc đi bộ\",\n          \"price\": \"150.000đ (Ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 1,\n          \"activity\": \"Di chuyển đến Hồ Lắk, tham quan hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, trải nghiệm đi thuyền độc mộc và tìm hiểu văn hóa M\'nông.\",\n          \"reason\": \"Hồ Lắk kết hợp thiên nhiên hùng vĩ với văn hóa bản địa M\'nông, phù hợp với sở thích văn hóa và trải nghiệm tự nhiên của du khách. Đồng thời, là điểm đến không quá xa để di chuyển từ Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho dịch vụ thuyền độc mộc của người dân địa phương.\",\n          \"suggestion\": \"Trải nghiệm lưu trú tại Lak Tented Camp để có cái nhìn toàn cảnh Hồ Lắk (nếu có ý định ở lại qua đêm tại Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 50km từ TP. Buôn Ma Thuột)\",\n          \"price\": \"250.000đ (Vé tham quan và dịch vụ thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức bữa tối và nghỉ ngơi tại Buôn Ma Thuột.\",\n          \"reason\": \"Trải nghiệm ẩm thực địa phương vào buổi tối và có thời gian nghỉ ngơi chuẩn bị cho ngày hôm sau.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho bữa tối tại quán ăn địa phương.\",\n          \"suggestion\": \"Ăn tối tại Quán Cà Te, địa chỉ: 140 Lê Thánh Tông. Nghỉ đêm tại Lee\'s House, địa chỉ: 55 đ.số 3, Cư Bur (homestay view đẹp).\",\n          \"address\": \"140 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc taxi/Grab\",\n          \"price\": \"400.000đ (Ăn tối và một phần chi phí lưu trú)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trải nghiệm Cà phê và Thác nước hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Khám phá văn hóa cà phê Buôn Ma Thuột. Tham quan bảo tàng cà phê, thưởng thức các loại cà phê đặc trưng và mua sắm quà lưu niệm.\",\n          \"reason\": \"Buôn Ma Thuột là thủ phủ cà phê Việt Nam, trải nghiệm văn hóa cà phê đặc sắc là không thể bỏ qua với sở thích ẩm thực của du khách.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho việc mua cà phê và các sản phẩm liên quan tại địa phương.\",\n          \"suggestion\": \"Thưởng thức cà phê tại Làng cà phê Trung Nguyên, địa chỉ: 163 Lý Thái Tổ. Mua sắm tại Chợ Trung tâm Buôn Ma Thuột để trải nghiệm chợ truyền thống.\",\n          \"address\": \"163 Lý Thái Tổ, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ\",\n          \"price\": \"150.000đ (Chi phí cà phê và quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa và nghỉ ngơi.\",\n          \"reason\": \"Nạp năng lượng cho buổi chiều khám phá thác nước.\",\n          \"community_impact\": \"Dự kiến 120.000đ cho bữa trưa.\",\n          \"suggestion\": \"Ăn trưa tại Phở hai tô 52, địa chỉ: 52 Ngô Quyền. Nghỉ trưa tại Zan Homestay, địa chỉ: 37 Hồ Giáo.\",\n          \"address\": \"52 Ngô Quyền, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc đi bộ\",\n          \"price\": \"120.000đ (Ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Tham quan Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Tận hưởng không khí trong lành và cảnh quan thiên nhiên tráng lệ.\",\n          \"reason\": \"Thác Dray Nur mang vẻ đẹp thiên nhiên hùng vĩ, là điểm đến lý tưởng để thư giãn và ngắm cảnh sau các hoạt động văn hóa, ẩm thực. Khoảng cách không quá xa từ Buôn Ma Thuột, thuận tiện di chuyển.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho vé vào cổng, góp phần vào việc bảo tồn và phát triển du lịch địa phương.\",\n          \"suggestion\": \"\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi/Grab (khoảng 25km từ TP. Buôn Ma Thuột)\",\n          \"price\": \"50.000đ (Vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức bữa tối cuối cùng tại Buôn Ma Thuột và chuẩn bị kết thúc hành trình.\",\n          \"reason\": \"Kết thúc chuyến đi với những trải nghiệm ẩm thực đáng nhớ.\",\n          \"community_impact\": \"Dự kiến 180.000đ cho bữa tối.\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45, địa chỉ: 45 Lê Thánh Tông. Nghỉ đêm tại Khách sạn Sài Gòn - Ban Mê, địa chỉ: 01-03 Phan Chu Trinh (tiện nghi trung tâm).\",\n          \"address\": \"45 Lê Thánh Tông, TP. Buôn Ma Thuột\",\n          \"transport\": \"Xe máy hoặc đi bộ\",\n          \"price\": \"380.000đ (Ăn tối và một phần chi phí lưu trú)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-29 06:22:05'),
(52, 7, 'Lịch trình 2 ngày - thiên nhiên, cà phê', 2, 'thiên nhiên, cà phê', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hương vị Thủ phủ Cà phê và Thác nguồn Đại ngàn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê đặc sắc và ăn sáng đặc sản\",\n          \"reason\": \"Bắt đầu hành trình tại thủ phủ cà phê để nạp năng lượng và tìm hiểu văn hóa bản địa theo đúng sở thích của du khách.\",\n          \"community_impact\": \"Dự kiến 150.000đ mua sắm hạt cà phê rang xay trực tiếp từ nông dân địa phương.\",\n          \"suggestion\": \"Ăn sáng Phở hai tô 52 (52 Ngô Quyền, Buôn Ma Thuột), sau đó thưởng thức cà phê tại SOUL Roastery (87 Nguyễn Khuyến, Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy thuê tự lái (khoảng 150.000đ/ngày) di chuyển trong nội thành.\",\n          \"price\": \"120.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa ẩm thực Tây Nguyên và nghỉ ngơi giữa ngày\",\n          \"reason\": \"Thưởng thức các món ăn đậm đà phong vị núi rừng trước khi di chuyển ra ngoại thành.\",\n          \"community_impact\": \"Dự kiến 300.000đ ủng hộ nhà hàng sử dụng nguyên liệu nông sản địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông, Buôn Ma Thuột) với món bò nhúng me đặc sản. Nghỉ trưa tại An Homestay (137/91 Thôi Hữu, Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy cá nhân.\",\n          \"price\": \"250.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Khám phá sự hùng vĩ của Thác Dray Nur\",\n          \"reason\": \"Thác Dray Nur là biểu tượng thiên nhiên hoang sơ, thích hợp cho du khách yêu thích chụp ảnh và trekking nhẹ nhàng bên dòng thác.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua nước uống và đồ ăn nhẹ từ các quầy hàng của người đồng bào Ê Đê tại khu du lịch.\",\n          \"suggestion\": \"Chụp ảnh check-in cầu treo và dòng thác đổ kỳ vĩ.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển khoảng 25km từ trung tâm TP. Buôn Ma Thuột theo hướng quốc lộ 14.\",\n          \"price\": \"50.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối bún đỏ đặc sản và trải nghiệm phố núi về đêm\",\n          \"reason\": \"Khám phá ẩm thực đường phố đặc trưng chỉ có tại Buôn Ma Thuột vào buổi tối se lạnh.\",\n          \"community_impact\": \"Dự kiến 80.000đ ủng hộ quán ăn vỉa hè của người dân địa phương.\",\n          \"suggestion\": \"Ăn tối Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong, Buôn Ma Thuột). Nghỉ đêm tại Lee\'s House (55 đ.số 3, Cư Bur, Buôn Ma Thuột) với view thung lũng cực đẹp.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy.\",\n          \"price\": \"100.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hồ nước ngọt đại ngàn và Văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Ngắm bình minh và trải nghiệm đi thuyền độc mộc trên Hồ Lắk\",\n          \"reason\": \"Hồ Lắk sở hữu vẻ đẹp thiên nhiên yên bình, thơ mộng, mang lại cảm giác thư thái tuyệt đối cho du khách yêu thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 200.000đ chi phí thuê thuyền độc mộc trực tiếp từ người lái thuyền M\'nông bản địa.\",\n          \"suggestion\": \"Trải nghiệm chèo thuyền độc mộc ngắm sen hoang sơ trên hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển khoảng 55km từ Buôn Ma Thuột dọc theo quốc lộ 27.\",\n          \"price\": \"150.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức chả cá thát lát Hồ Lắk và nghỉ trưa ven hồ\",\n          \"reason\": \"Thưởng thức đặc sản cá thát lát tươi ngon được đánh bắt ngay tại Hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 250.000đ chi tiêu tại nhà hàng ven hồ sử dụng thủy sản tự nhiên.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng thuộc Lak Tented Camp (ven Hồ Lắk). Nghỉ ngơi thư giãn ngắm cảnh hồ trực diện từ khu lều nghỉ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc đi thuyền nội khu.\",\n          \"price\": \"300.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục đỉnh Núi Đá Voi Mẹ khổng lồ\",\n          \"reason\": \"Địa điểm thiên nhiên độc đáo, dễ di chuyển trên đường từ Hồ Lắk về lại trung tâm, mang lại tầm nhìn toàn cảnh ruộng lúa và rừng núi bao la.\",\n          \"community_impact\": \"Dự kiến 300.000đ mua các sản phẩm lưu niệm như mật ong rừng, ca cao nguyên chất từ quầy nông sản chân núi.\",\n          \"suggestion\": \"Chinh phục tảng đá nguyên khối lớn nhất Việt Nam để ngắm hoàng hôn buông xuống thung lũng.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy khoảng 15km từ Hồ Lắk hướng về Buôn Ma Thuột.\",\n          \"price\": \"20.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối nhẹ nhàng và mua sắm đặc sản làm quà trước khi ra sân bay/bến xe\",\n          \"reason\": \"Kết thúc chuyến đi bằng bữa tối ấm cúng và mua sắm những món quà ý nghĩa từ vùng đất Tây Nguyên.\",\n          \"community_impact\": \"Dự kiến 500.000đ mua cà phê Arabica/Robusta chất lượng cao và thịt nai khô làm quà.\",\n          \"suggestion\": \"Ăn tối nhẹ tại Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, Buôn Ma Thuột). Mua sắm đặc sản tại các cửa hàng uy tín ở trung tâm thành phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển về trung tâm thành phố và trả xe thuê.\",\n          \"price\": \"150.000đ\"\n        }\n      ]\n    }\n  ]\n}\n', '2026-07-29 06:31:22'),
(53, 7, 'Lịch trình 2 ngày - trekking, cà phê', 2, 'trekking, cà phê', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Explore Coffee Culture and Trekking Dray Nur Waterfall\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 6,\n          \"activity\": \"Experience coffee culture and learn about local beans at the Vietnam coffee capital\",\n          \"reason\": \"Matches the tourist\'s high preference for coffee, providing a perfect morning start in the heart of Buon Ma Thuot.\",\n          \"community_impact\": \"Expected 150,000 VND to local coffee brewers and guides\",\n          \"suggestion\": \"Arul Coffee, 17 Tran Nhat Duat, Buon Ma Thuot, Dak Lak\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike (rental 150,000 VND/day)\",\n          \"price\": \"100,000 VND\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch and short rest before trekking\",\n          \"reason\": \"Replenish energy with famous local dishes and check in to store luggage.\",\n          \"community_impact\": \"Expected 200,000 VND to local restaurant staff\",\n          \"suggestion\": \"Lunch at Quan Ca Te (140 Le Thanh Tong, Buon Ma Thuot). Stay at Zan Homestay (37 Ho Giao, Buon Ma Thuot)\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"150,000 VND\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking and exploring the majestic Dray Nur Waterfall\",\n          \"reason\": \"Fulfills the trekking preference. Dray Nur offers pristine forest paths and exciting suspension bridges.\",\n          \"community_impact\": \"Expected 100,000 VND to local management and park rangers\",\n          \"suggestion\": \"Dray Nur Waterfall tourist site cafe, Krong Ana, Dak Lak\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Motorbike (about 25km south of city center)\",\n          \"price\": \"50,000 VND (Entrance fee)\"\n        },\n        {\n          \"time\": \"Evening\",\n          \"destination_id\": null,\n          \"activity\": \"Dinner and relaxing night walk in the city center\",\n          \"reason\": \"Rest after a long trek, enjoying Buon Ma Thuot\'s iconic noodle dish and cool night air.\",\n          \"community_impact\": \"Expected 120,000 VND to local street food vendors\",\n          \"suggestion\": \"Dinner at Bun do Co Thu (Phan Dinh Giot - Le Hong Phong). Overnight at Zan Homestay (37 Ho Giao, Buon Ma Thuot)\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike / Walking\",\n          \"price\": \"80,000 VND\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trekking in Yok Don and cultural immersion in Buon Don\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 5,\n          \"activity\": \"Trekking inside the dipterocarp forest of Yok Don National Park\",\n          \"reason\": \"Ideal for trekking enthusiasts, offering rich biodiversity and quiet natural pathways.\",\n          \"community_impact\": \"Expected 300,000 VND directly to forest preservation and local guides\",\n          \"suggestion\": \"Yok Don National Park canteen, Buon Don, Dak Lak\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Motorbike (heading northwest)\",\n          \"price\": \"150,000 VND (Trekking permit & guide)\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch with local specialties near Serepok river\",\n          \"reason\": \"Conveniently located on the route back, perfect for a peaceful lunch break.\",\n          \"community_impact\": \"Expected 250,000 VND to local river-side culinary hosts\",\n          \"suggestion\": \"Lunch at Nha San Co Ban restaurant in Buon Don. Rest at Huyen Thoai Homestay (Buon Don)\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"200,000 VND\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 4,\n          \"activity\": \"Explore Buon Don suspension bridges and E De longhouses\",\n          \"reason\": \"On the circular route back to the city center, allowing tourists to learn about ethnic cultures without extra travel time.\",\n          \"community_impact\": \"Expected 150,000 VND to local community tourism cooperative\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"100,000 VND\"\n        },\n        {\n          \"time\": \"Evening\",\n          \"destination_id\": null,\n          \"activity\": \"Farewell dinner and premium coffee tasting before departure\",\n          \"reason\": \"Provides a satisfying conclusion to the 2-day journey with high-quality local coffee beans.\",\n          \"community_impact\": \"Expected 200,000 VND to local hospitality businesses\",\n          \"suggestion\": \"Dinner at Pho 52 (52 Ngo Quyen). Coffee at Trung Nguyen Coffee Village (163 Ly Thai To). Sleep at Muong Thanh Hotel (81 Nguyen Tat Thanh)\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike / Taxi\",\n          \"price\": \"150,000 VND\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-29 06:37:25');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(54, NULL, 'Lịch trình 5 ngày - văn hoá, ẩm thực', 5, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Welcome to the Coffee Capital & Cultural Immersion\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 6,\n          \"activity\": \"Experience roasted coffee culture at the Coffee Capital\",\n          \"reason\": \"Perfect start to understand the local coffee heritage, matches the cultural and culinary preferences.\",\n          \"community_impact\": \"Expected 150,000 VND spent on local coffee products\",\n          \"suggestion\": \"Arul Coffee (17 Tran Nhat Duat, Buon Ma Thuot) - a beautiful traditional E De longhouse cafe.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike rental (150,000 VND/day)\",\n          \"price\": \"50,000 VND\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch with local specialty and hotel check-in\",\n          \"reason\": \"Taste local culinary dishes and rest after travel.\",\n          \"community_impact\": \"Expected 120,000 VND to local food vendor\",\n          \"suggestion\": \"Lunch at Bun do Co Thu (Phan Dinh Giot, Buon Ma Thuot). Stay at Zan Homestay (37 Ho Giao, Buon Ma Thuot).\",\n          \"address\": \"Phan Dinh Giot, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"40,000 VND\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 7,\n          \"activity\": \"Explore Ako Dhong Village to see traditional E De longhouses\",\n          \"reason\": \"Deep dive into the authentic indigenous culture of the E De people right in the city center.\",\n          \"community_impact\": \"Expected 100,000 VND spent on local handicrafts or drinks\",\n          \"suggestion\": \"Walk around the village and enjoy a drink at the local community space.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"0 VND\"\n        },\n        {\n          \"time\": \"Evening\",\n          \"destination_id\": null,\n          \"activity\": \"Dinner with Highlands cuisine and night walk\",\n          \"reason\": \"Savor famous local grilled beef and unwind in the central area.\",\n          \"community_impact\": \"Expected 300,000 VND to local restaurant\",\n          \"suggestion\": \"Dinner at Quan Ca Te (140 Le Thanh Tong, Buon Ma Thuot). Sleep at Zan Homestay (37 Ho Giao, Buon Ma Thuot).\",\n          \"address\": \"140 Le Thanh Tong, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"200,000 VND\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Traditional Elephant Land and Serepok River Culture\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 4,\n          \"activity\": \"Visit Buon Don, cross the suspension bridge and learn about elephant taming history\",\n          \"reason\": \"Buon Don is the historical cradle of elephant hunting and cultural exchange among M\'nong, E De, and Lao people.\",\n          \"community_impact\": \"Expected 150,000 VND entrance fees and local guides\",\n          \"suggestion\": \"Huyen Thoai Homestay (Buon Don) nearby for reference.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"80,000 VND\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch at Buon Don with traditional riverside dishes\",\n          \"reason\": \"Try local specialties such as Com Lam (bamboo rice) and grilled Serepok river fish.\",\n          \"community_impact\": \"Expected 250,000 VND to local riverside stall\",\n          \"suggestion\": \"Serepok Restaurant inside Buon Don tourism area.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Walking\",\n          \"price\": \"150,000 VND\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 5,\n          \"activity\": \"Walk through Yok Don National Park\'s unique ecosystem\",\n          \"reason\": \"Explore the peaceful dipterocarp dry deciduous forest and learn about elephant-friendly tourism.\",\n          \"community_impact\": \"Expected 300,000 VND to park rangers and local preservation fund\",\n          \"suggestion\": \"Eco-tours guided by Yok Don National Park staff.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"100,000 VND\"\n        },\n        {\n          \"time\": \"Evening\",\n          \"destination_id\": null,\n          \"activity\": \"Dinner back in the city and resting\",\n          \"reason\": \"Recover from the forest walk and enjoy a relaxing evening in town.\",\n          \"community_impact\": \"Expected 150,000 VND to city businesses\",\n          \"suggestion\": \"Dinner at Pho 52 (52 Ngo Quyen, Buon Ma Thuot). Sleep at Zan Homestay (37 Ho Giao, Buon Ma Thuot).\",\n          \"address\": \"52 Ngo Quyen, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"60,000 VND\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Majestic Waterfalls & Scenic Sunset\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 2,\n          \"activity\": \"Visit Dray Nur Waterfall, the pride of Central Highlands\",\n          \"reason\": \"Witness the powerful flow of the Serepok river and learn about local ethnic legends associated with the waterfall.\",\n          \"community_impact\": \"Expected 100,000 VND to local tourism workers\",\n          \"suggestion\": \"Buy some fresh forest-side snacks from local vendors.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"50,000 VND\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch near the waterfall and rest\",\n          \"reason\": \"Cool breeze from the river provides a perfect setting for a midday lunch and nap.\",\n          \"community_impact\": \"Expected 200,000 VND to local food providers\",\n          \"suggestion\": \"Dray Nur Restaurant located at the entrance. Rest at Lee\'s House (55 St. 3, Cu Bur) after returning.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"150,000 VND\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 8,\n          \"activity\": \"Sunset watching at Ea Kao Lake\",\n          \"reason\": \"Relaxing atmosphere, popular local hangout spot, and beautiful landscape photogenic spots.\",\n          \"community_impact\": \"Expected 50,000 VND for lakeside snacks and local drinks\",\n          \"suggestion\": \"Lakeside cafes around Ea Kao lake.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"30,000 VND\"\n        },\n        {\n          \"time\": \"Evening\",\n          \"destination_id\": null,\n          \"activity\": \"Dinner and experience Buon Ma Thuot night market\",\n          \"reason\": \"Experience authentic local street life, buy regional souvenirs, and try street snacks.\",\n          \"community_impact\": \"Expected 200,000 VND directly to market vendors\",\n          \"suggestion\": \"Eat street food around the Buon Ma Thuot Market area. Sleep at Elephants Hotel (142 Hai Ba Trung, Buon Ma Thuot).\",\n          \"address\": \"Y Jut, TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Motorbike / Walking\",\n          \"price\": \"100,000 VND\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"M\'nong Culture and Lak Lake Exploration\",\n      \"items\": [\n        {\n          \"time\": \"Morning\",\n          \"destination_id\": 16,\n          \"activity\": \"Climb Mother Elephant Rock for panoramic views\",\n          \"reason\": \"A legendary natural monolith with spiritual meaning for local ethnic minorities.\",\n          \"community_impact\": \"Expected 50,000 VND to local parking and beverage booths\",\n          \"suggestion\": \"Park at the base and hike up carefully; bring water.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"0 VND\"\n        },\n        {\n          \"time\": \"Noon\",\n          \"destination_id\": null,\n          \"activity\": \"Lunch with local special dishes from Lak Lake\",\n          \"reason\": \"Taste local Specialties such as chả cá thát lát (featherback fish paste) and wild vegetables.\",\n          \"community_impact\": \"Expected 250,000 VND to local restaurant owners\",\n          \"suggestion\": \"Lunch at a local lakeside restaurant near Jun Village. Rest at Lak Tented Camp (Lak Lake).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Motorbike\",\n          \"price\": \"150,000 VND\"\n        },\n        {\n          \"time\": \"Afternoon\",\n          \"destination_id\": 1,\n          \"activity\": \"Explore Lak Lake and Jun Village\",\n          \"reason\": \"Discover the tranquil waters of Lak Lake and learn about the unique matriarchal culture of the M\'nong people.\",\n          \"community_impact\": \"Expected 300,000 VND spent on dugout canoe rentals and village tours\",\n          \"suggestion\": \"Lak Tented Camp (Lak Lake) or rent a dugout canoe (Thuyền độc mộc) directly from M\'nong boatmen.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Walking / Boat\",\n          \"price\": \"150,000 VND\"\n        },\n        {\n          \"time\"