(56, NULL, 'Lịch trình 2 ngày - ẩm thực, trekking', 2, 'ẩm thực, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá đại ngàn và Thác nước hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking khám phá hệ thống thác Dray Nur, trải nghiệm cầu treo và ngắm dòng Sêrêpôk cuộn trào.\",\n          \"reason\": \"Phù hợp với sở thích trekking của du khách, buổi sáng mát mẻ thích hợp cho các hoạt động thể chất ngoài trời.\",\n          \"community_impact\": \"Dự kiến đóng góp 150.000đ mua vé tham quan và sử dụng dịch vụ hướng dẫn địa phương.\",\n          \"suggestion\": \"Ăn sáng nhẹ tại quán Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột) trước khi di chuyển.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy di chuyển từ trung tâm TP. Buôn Ma Thuột đến thác Dray Nur khoảng 25km.\",\n          \"price\": \"120.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên và nghỉ ngơi.\",\n          \"reason\": \"Khách cần nạp năng lượng sau chuyến trekking mệt mỏi.\",\n          \"community_impact\": \"Dự kiến tiêu dùng 200.000đ tại nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông). Nghỉ ngơi buổi trưa tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy về lại trung tâm thành phố.\",\n          \"price\": \"250.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm không gian văn hóa cà phê và thưởng thức hương vị cà phê Buôn Ma Thuột nguyên bản.\",\n          \"reason\": \"Kết hợp sở thích ẩm thực và thưởng thức đặc sản trứ danh của thủ phủ cà phê.\",\n          \"community_impact\": \"Ủng hộ 100.000đ cho chuỗi cung ứng nông sản cà phê tại địa phương.\",\n          \"suggestion\": \"Trải nghiệm tại Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy đi lại trong nội thành.\",\n          \"price\": \"80.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Khám phá ẩm thực đường phố và dạo quanh chợ đêm.\",\n          \"reason\": \"Đáp ứng nhu cầu trải nghiệm ẩm thực địa phương đặc trưng.\",\n          \"community_impact\": \"Dự kiến 150.000đ mua sắm quà lưu niệm hoặc đồ ăn vặt tại chợ.\",\n          \"suggestion\": \"Ăn tối món Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghủ đêm tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy.\",\n          \"price\": \"100.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Văn hóa bản địa và Thiên nhiên đại ngàn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tản bộ tham quan buôn làng cổ của người Ê Đê, ngắm nhìn những ngôi nhà dài truyền thống.\",\n          \"reason\": \"Trải nghiệm văn hóa bản địa nhẹ nhàng vào sáng sớm, kết hợp đi bộ ngắm cảnh.\",\n          \"community_impact\": \"Dự kiến mua đồ thủ công dệt thổ cẩm trị giá 100.000đ từ người dân bản địa.\",\n          \"suggestion\": \"Uống cà phê sáng tại Arul Coffee (17 Trần Nhật Duật) ngay trong buôn.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển khoảng 3km từ homestay.\",\n          \"price\": \"50.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa với các món đặc sản Tây Nguyên và nghỉ trưa.\",\n          \"reason\": \"Thưởng thức ẩm thực đặc trưng miền đất đỏ.\",\n          \"community_impact\": \"Dự kiến 250.000đ cho bữa trưa gia đình do đồng bào chế biến.\",\n          \"suggestion\": \"Ăn trưa tại Cư H\'Lăm Restaurant & Homestay (Ea Pốk). Nghỉ ngơi tại chỗ.\",\n          \"address\": \"Huyện Cư M\'gar, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy khoảng 12km từ Buôn Akô Dhông.\",\n          \"price\": \"200.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Trekking leo lên đỉnh Núi Đá Voi Mẹ - tảng đá nguyên khối lớn nhất Việt Nam ngắm toàn cảnh đại ngàn.\",\n          \"reason\": \"Hoạt động trekking chinh phục độ cao lý thú, ngắm hoàng hôn buông xuống thung lũng.\",\n          \"community_impact\": \"Mua nước uống và nông sản từ quầy hàng của người đồng bào M\'nông dưới chân núi khoảng 50.000đ.\",\n          \"suggestion\": \"Mua sắm đặc sản thịt nai khô và mật ong rừng tại các cửa hàng uy tín ven đường.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy dọc theo QL27 về hướng huyện Lắk khoảng 35km.\",\n          \"price\": \"40.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức bánh ướt chồng dĩa và chuẩn bị hành trình ra về.\",\n          \"reason\": \"Trải nghiệm phong cách ăn uống độc đáo thú vị của người dân Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến tiêu dùng 100.000đ tại quán ăn địa phương.\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Nghỉ ngơi hoặc lấy hành lý tại Zan Homestay (37 Hồ Giáo) để ra sân bay/bến xe.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy và taxi ra sân bay.\",\n          \"price\": \"120.000đ\"\n        }\n      ]\n    }\n  ]\n}\n', '2026-08-03 01:48:25'),
(57, 3, 'Lịch trình 2 ngày - thiên nhiên, ẩm thực', 2, 'thiên nhiên, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hương Vị Thủ Phủ Cà Phê Và Thiên Nhiên Hùng Vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức cà phê sáng tại thủ phủ và khám phá văn hoá cà phê độc đáo.\",\n          \"reason\": \"Phù hợp với sở thích ẩm thực và mong muốn trải nghiệm cà phê địa phương của du khách ngay khi bắt đầu hành trình.\",\n          \"community_impact\": \"Dự kiến 150.000đ đóng góp vào doanh thu hộ kinh doanh và nghệ nhân cà phê địa phương.\",\n          \"suggestion\": \"SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) - Quán cà phê với không gian mở hiện đại, cà phê Specialty chất lượng cao.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy tự lái (thuê khoảng 150.000đ/ngày tại trung tâm thành phố)\",\n          \"price\": \"50.000đ - 100.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực trưa đặc sản Tây Nguyên và nghỉ ngơi.\",\n          \"reason\": \"Nạp năng lượng với món ăn đặc trưng địa phương tại trung tâm để chuẩn bị cho hành trình thiên nhiên buổi chiều.\",\n          \"community_impact\": \"Dự kiến 250.000đ chi tiêu tại nhà hàng địa phương.\",\n          \"suggestion\": \"Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) nổi tiếng với bò nhúng ớt. Nghỉ trưa tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột) - không gian yên bình, gần gũi thiên nhiên.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"150.000đ - 250.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Chinh phục ngọn thác Dray Nur kỳ vĩ, tận hưởng thiên nhiên trong lành và chụp ảnh.\",\n          \"reason\": \"Đáp ứng trọn vẹn sở thích khám phá thiên nhiên hoang sơ, hùng vĩ của đại ngàn Tây Nguyên.\",\n          \"community_impact\": \"Dự kiến 100.000đ hỗ trợ ban quản lý du lịch sinh thái và bảo tồn tài nguyên rừng.\",\n          \"suggestion\": \"Trải nghiệm trekking nhẹ quanh chân thác. Có thể mua thêm nông sản khô từ người đồng bào bán bên ngoài.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển theo tuyến Quốc lộ 14 hướng về Krông Ana (~25km)\",\n          \"price\": \"30.000đ (Vé vào cổng)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối món bún đỏ đặc sản và dạo phố đêm Buôn Ma Thuột.\",\n          \"reason\": \"Bún đỏ là món ăn đường phố biểu tượng của Đắk Lắk, giúp du khách trải nghiệm sâu sắc văn hoá ẩm thực bản địa.\",\n          \"community_impact\": \"Dự kiến 80.000đ cho các gánh hàng rong và quán ăn vỉa hè.\",\n          \"suggestion\": \"Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột). Nghỉ đêm tại Elephants Hotel (142 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ quanh khu vực trung tâm\",\n          \"price\": \"30.000đ - 50.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Văn Hoá Buôn Làng Và Hồ Nước Đại Ngàn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Dạo bộ ngắm những ngôi nhà dài truyền thống của người Ê Đê tại Buôn Akô Dhông.\",\n          \"reason\": \"Trải nghiệm kết hợp hài hoà giữa kiến trúc truyền thống, thiên nhiên xanh mát của buôn làng trong lòng thành phố.\",\n          \"community_impact\": \"Dự kiến 150.000đ mua đồ thủ công dệt thổ cẩm hoặc uống nước tại các quán trong buôn.\",\n          \"suggestion\": \"Ghé Arul Coffee (17 Trần Nhật Duật, trong lòng Buôn Akô Dhông) để thưởng thức cà phê trong không gian nhà sàn gỗ cổ kính.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"Miễn phí vé vào buôn (Chi phí nước uống tự túc khoảng 40.000đ)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa món phở hai tô đặc sắc và nghỉ trưa.\",\n          \"reason\": \"Thưởng thức món phở khô trứ danh của vùng cao nguyên đất đỏ.\",\n          \"community_impact\": \"Dự kiến 100.000đ đóng góp cho kinh tế hộ gia đình.\",\n          \"suggestion\": \"Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ trưa ngắn tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"40.000đ - 60.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 8,\n          \"activity\": \"Thư giãn, cắm trại nhẹ ngắm hoàng hôn yên bình tại Hồ Ea Kao.\",\n          \"reason\": \"Hồ nước rộng lớn gần trung tâm, không khí mát mẻ, kết thúc chuyến đi bằng khoảnh khắc thiên nhiên dịu êm.\",\n          \"community_impact\": \"Dự kiến 50.000đ cho các dịch vụ giải khát ven hồ của người dân bản địa.\",\n          \"suggestion\": \"Thuê một chiếc bạt nhỏ ngồi ven hồ, ngắm hoàng hôn buông xuống mặt nước tĩnh lặng.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển khoảng 9km về hướng Đông Nam thành phố\",\n          \"price\": \"Miễn phí vào cổng (Chi phí ăn vặt ven hồ khoảng 30.000đ)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối nhẹ, mua sắm đặc sản làm quà tại Chợ Trung tâm Buôn Ma Thuột.\",\n          \"reason\": \"Đáp ứng sở thích khám phá chợ truyền thống, mua sắm các sản vật địa phương như cà phê, măng khô, mật ong rừng.\",\n          \"community_impact\": \"Dự kiến 500.000đ mua sắm đặc sản trực tiếp từ tiểu thương trong chợ.\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Mua sắm tại Chợ Trung tâm Buôn Ma Thuột (đường Điện Biên Phủ).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi\",\n          \"price\": \"100.000đ (ăn uống) + Chi phí mua quà tự chọn\"\n        }\n      ]\n    }\n  ]\n}', '2026-08-03 02:20:50'),
(58, 3, 'Lịch trình 2 ngày - thiên nhiên, ẩm thực', 2, 'thiên nhiên, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hương vị Thủ phủ Cà phê và Thác nguồn Đại ngàn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hóa cà phê tại thủ phủ cà phê Buôn Ma Thuột\",\n          \"reason\": \"Khởi đầu ngày mới bằng việc thưởng thức cà phê đặc sản và tìm hiểu văn hóa bản địa, phù hợp sở thích ẩm thực và nhịp sống địa phương.\",\n          \"community_impact\": \"Dự kiến 150.000đ đóng góp vào kinh doanh nông sản địa phương.\",\n          \"suggestion\": \"Thưởng thức tại SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) hoặc Arul Coffee (17 Trần Nhật Duật, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc Taxi di chuyển trong nội thành\",\n          \"price\": \"70.000đ - 120.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên và nghỉ trưa\",\n          \"reason\": \"Nạp năng lượng với các món đặc sản Đắk Lắk trước khi khởi hành đi tuyến thác.\",\n          \"community_impact\": \"Dự kiến 250.000đ ủng hộ nhà hàng ẩm thực bản địa.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) với món bò nhúng me. Nghỉ ngơi tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô tự lái\",\n          \"price\": \"150.000đ - 250.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 2,\n          \"activity\": \"Khám phá sự hùng vĩ của Thác Dray Nur\",\n          \"reason\": \"Khám phá một trong những thác nước đẹp và lớn nhất Tây Nguyên, thỏa mãn đam mê thiên nhiên sông nước hoang sơ.\",\n          \"community_impact\": \"Dự kiến 100.000đ chi phí dịch vụ và mua nước uống từ người dân địa phương.\",\n          \"suggestion\": \"Chụp ảnh check-in và đi bộ men theo các lối đá quanh thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô di chuyển khoảng 25km từ trung tâm thành phố theo hướng QL14\",\n          \"price\": \"50.000đ - 100.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối đặc sản bún đỏ và dạo quanh phố núi\",\n          \"reason\": \"Thưởng thức món ăn đường phố biểu tượng của Buôn Ma Thuột vào ban đêm mát mẻ.\",\n          \"community_impact\": \"Dự kiến 80.000đ hỗ trợ các hộ kinh doanh ẩm thực đêm.\",\n          \"suggestion\": \"Ăn tối tại Quán Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột). Nghỉ đêm tại Khách sạn Hai Bà Trưng (8 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"40.000đ - 80.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hồ Nước Ngọt Đại Ngàn và Văn Hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Ngắm bình minh và trải nghiệm đi thuyền trên Hồ Lắk\",\n          \"reason\": \"Hồ nước ngọt tự nhiên lớn thứ hai Việt Nam, mang vẻ đẹp thơ mộng, tĩnh lặng vào buổi sáng, kết hợp tìm hiểu văn hóa M\'nông.\",\n          \"community_impact\": \"Dự kiến 300.000đ thuê thuyền độc mộc trực tiếp từ người dân buôn Jun.\",\n          \"suggestion\": \"Ghé thăm Buôn Jun ven hồ để trải nghiệm đời sống bản địa.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô hoặc xe máy theo QL27 hướng đi Lâm Đồng khoảng 50km\",\n          \"price\": \"150.000đ - 300.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức cơm lam, cá bống kho tộ Hồ Lắk và nghỉ trưa\",\n          \"reason\": \"Thưởng thức các món ăn dân dã đặc sản khai thác trực tiếp từ lòng Hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 200.000đ cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng ven hồ. Nghỉ trưa ngắn tại Lak Tented Camp (ven Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"120.000đ - 200.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ\",\n          \"reason\": \"Địa điểm nằm trên đường quay trở về thành phố, là tảng đá nguyên khối khổng lồ biểu tượng của tình yêu và đại ngàn.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua nông sản, nước giải khát chân núi.\",\n          \"suggestion\": \"Nên mang giày thể thao bám tốt để leo lên lưng đá voi an toàn.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc ô tô di chuyển dọc QL27 hướng về lại Buôn Ma Thuột\",\n          \"price\": \"20.000đ - 50.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối bánh ướt chồng dĩa và mua sắm đặc sản làm quà\",\n          \"reason\": \"Kết thúc hành trình bằng món ăn độc đáo thú vị và mua sắm quà lưu niệm đặc trưng Tây Nguyên.\",\n          \"community_impact\": \"Dự kiến 500.000đ mua cà phê, thịt nai khô từ các hợp tác xã OCOP.\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Mua sắm đặc sản tại các cửa hàng trung tâm.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi ra sân bay/bến xe\",\n          \"price\": \"100.000đ - 500.000đ\"\n        }\n      ]\n    }\n  ]\n}', '2026-08-03 02:28:17');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(59, NULL, 'Lịch trình 4 ngày - thiên nhiên, văn hoá', 4, 'thiên nhiên, văn hoá', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Chạm ngõ Đắk Lắk - Hương vị Cà phê & Văn hóa Buôn làng\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức hương vị cà phê Buôn Ma Thuột tại thủ phủ cà phê\",\n          \"reason\": \"Khởi đầu ngày mới tràn đầy năng lượng bằng việc tìm hiểu nét văn hóa cà phê đặc trưng của vùng đất Tây Nguyên đầy nắng gió.\",\n          \"community_impact\": \"Dự kiến 100.000đ đóng góp vào chuỗi cung ứng nông sản của nông dân trồng cà phê địa phương.\",\n          \"suggestion\": \"Trải nghiệm tại Làng cà phê Trung Nguyên - địa chỉ: 163 Lý Thái Tổ, Tân Lợi, TP. Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy thuê tại trung tâm thành phố (khoảng 120.000đ/ngày).\",\n          \"price\": \"70.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Tây Nguyên và nghỉ trưa\",\n          \"reason\": \"Nạp năng lượng với món ăn mang hương vị núi rừng độc đáo, đậm đà.\",\n          \"community_impact\": \"Dự kiến 150.000đ cho nhà hàng ẩm thực địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ trưa tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy tự lái\",\n          \"price\": \"150.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Khám phá kiến trúc nhà dài truyền thống của người Ê Đê tại Buôn Akô Dhông\",\n          \"reason\": \"Buôn làng bình yên nằm ngay trong lòng thành phố, giúp du khách dễ dàng tiếp cận và tìm hiểu văn hóa bản địa đặc sắc.\",\n          \"community_impact\": \"Dự kiến ủng hộ 50.000đ mua đồ thủ công mỹ nghệ do bà con trong buôn tự làm.\",\n          \"suggestion\": \"Ghé Arul Coffee (17 Trần Nhật Duật, TP. Buôn Ma Thuột) nằm ngay trong buôn để tận hưởng không gian nhà sàn truyền thống.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển khoảng 3km từ trung tâm.\",\n          \"price\": \"50.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối bún đỏ đặc sản và dạo chợ đêm\",\n          \"reason\": \"Trải nghiệm ẩm thực đường phố trứ danh của Buôn Ma Thuột vào buổi tối se lạnh.\",\n          \"community_impact\": \"Dự kiến 60.000đ cho gánh bún đỏ lề đường và mua sắm nhỏ tại chợ.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ đêm tại Đam San Hotel (212 Nguyễn Công Trứ, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy\",\n          \"price\": \"80.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hùng vĩ Đại ngàn - Khám phá Thác nước Dray Nur\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Hòa mình vào thiên nhiên kỳ vĩ tại Thác Dray Nur\",\n          \"reason\": \"Thác nước hoang sơ, bọt tung trắng xóa là địa điểm lý tưởng để chiêm ngưỡng vẻ đẹp tự nhiên của núi rừng Krông Ana.\",\n          \"community_impact\": \"Dự kiến chi tiêu 100.000đ cho các dịch vụ hướng dẫn, hỗ trợ tham quan của người bản địa.\",\n          \"suggestion\": \"Mua vé tham quan trực tiếp tại quầy vé khu du lịch Thác Dray Nur.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc thuê ô tô tự lái theo hướng QL14 hướng về Krông Ana.\",\n          \"price\": \"50.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại ẩm thực Tây Nguyên và nghỉ ngơi bên dòng thác\",\n          \"reason\": \"Thưởng thức cơm lam, gà nướng thơm nức ngay bên cạnh tiếng thác đổ rì rầm.\",\n          \"community_impact\": \"Dự kiến 200.000đ ủng hộ nhà hàng sử dụng nguồn nguyên liệu cá sông, gà đồi của người dân xung quanh thác.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng trong khu du lịch Thác Dray Nur. Nghỉ trưa võng dưới bóng mát tán cây cổ thụ.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ tại khu du lịch\",\n          \"price\": \"200.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 3,\n          \"activity\": \"Khám phá Thác Dray Sáp lân cận\",\n          \"reason\": \"Tận dụng khoảng cách địa lý gần nhau để ngắm nhìn ngọn thác khói mộng mơ gắn liền với những truyền thuyết dân gian.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua nước uống từ các sạp hàng nhỏ của đồng bào dọc lối đi.\",\n          \"suggestion\": \"Có thể kết hợp trekking nhẹ nhàng men theo con đường mòn rừng nối giữa các cụm thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy di chuyển khoảng cách ngắn giữa hai khu vực thác.\",\n          \"price\": \"40.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Trở về thành phố, thưởng thức ẩm thực độc đáo\",\n          \"reason\": \"Nghỉ ngơi và hồi sức sau một ngày vận động thể chất ngoài thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 120.000đ chi tiêu tại quán ăn của người dân địa phương.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại Khách sạn Hai Bà Trưng (8 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy về lại trung tâm thành phố.\",\n          \"price\": \"120.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Huyền thoại Buôn Đôn - Voi rừng & Trải nghiệm hoang dã\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu nghề săn bắt và thuần dưỡng voi rừng\",\n          \"reason\": \"Tìm hiểu sâu hơn về lịch sử, văn hóa độc đáo của các dân tộc Ê Đê, M\'nông và trải nghiệm bước chân trên cầu treo cheo leo.\",\n          \"community_impact\": \"Dự kiến 150.000đ mua vé tham quan và sử dụng dịch vụ thuyết minh bản địa.\",\n          \"suggestion\": \"Đi dạo trên hệ thống cầu treo bằng tre bắc qua dòng sông Sêrêpôk.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc xe buýt từ TP. Buôn Ma Thuột đi Buôn Đôn (~40km).\",\n          \"price\": \"100.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa cơm lam gà sa lửa đặc sắc Buôn Đôn\",\n          \"reason\": \"Thưởng thức món ăn truyền thống được chế biến công phu từ nguồn nguyên liệu tươi ngon tại chỗ.\",\n          \"community_impact\": \"Dự kiến 180.000đ đóng góp vào kinh tế du lịch cộng đồng tại Buôn Đôn.\",\n          \"suggestion\": \"Ăn trưa tại khu ẩm thực Buôn Đôn hoặc Cư H\'Lăm Restaurant & Homestay (Ea Pốk, trên đường về lại). Nghỉ trưa tại homestay.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ\",\n          \"price\": \"180.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 5,\n          \"activity\": \"Tham quan sinh thái tại Vườn quốc gia Yok Đôn\",\n          \"reason\": \"Tận hưởng không khí trong lành của cánh rừng khộp duy nhất tại Việt Nam và quan sát cuộc sống thân thiện của những chú voi.\",\n          \"community_impact\": \"Dự kiến 200.000đ chi trả cho dịch vụ bảo tồn và hướng dẫn viên kiểm lâm địa phương.\",\n          \"suggestion\": \"Tham gia tour trải nghiệm xem voi thân thiện (không cưỡi voi) để ủng hộ du lịch nhân văn.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy khoảng 5km từ Buôn Đôn sang cổng Vườn quốc gia.\",\n          \"price\": \"150.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối bánh ướt chồng dĩa thú vị\",\n          \"reason\": \"Trải nghiệm phong cách ăn uống vô cùng độc đáo, xếp chồng những chiếc dĩa sau khi ăn xong.\",\n          \"community_impact\": \"Dự kiến 80.000đ cho quán ăn gia đình địa phương.\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ đêm tại Lee\'s House (55 đường số 3, Cư Bur, TP. Buôn Ma Thuột) - homestay có view thung lũng cực đẹp.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển về thành phố\",\n          \"price\": \"80.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Hồ Lắk Bình Yên - Phiêu du trên Thuyền độc mộc\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Ngắm bình minh, đi thuyền độc mộc trên Hồ Lắk\",\n          \"reason\": \"Cảm nhận sự tĩnh lặng, huyền ảo của mặt hồ nước ngọt tự nhiên lớn thứ hai Việt Nam dưới ánh nắng sớm mai.\",\n          \"community_impact\": \"Dự kiến 150.000đ chi trả trực tiếp cho người chèo thuyền độc mộc là đồng bào M\'nông bản địa.\",\n          \"suggestion\": \"Thuê thuyền độc mộc ngay tại bến thuyền Buôn Jun bên hồ Lắk.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển từ sáng sớm bằng xe máy theo QL27 hướng đi Lâm Đồng khoảng 50km.\",\n          \"price\": \"200.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa chả cá thát lát Hồ Lắk và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức món chả cá thát lát Hồ Lắk dai ngon nổi tiếng cùng canh chua cá lăng.\",\n          \"community_impact\": \"Dự kiến 200.000đ chi tiêu tại nhà hàng ven hồ sử dụng thủy sản đánh bắt tự nhiên từ hồ.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng thuộc Lak Tented Camp (ven Hồ Lắk) hoặc các quán ăn bình dân tại thị trấn Liên Sơn. Nghỉ trưa thư giãn ven hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ\",\n          \"price\": \"180.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ khổng lồ\",\n          \"reason\": \"Tận mắt chứng kiến tảng đá nguyên khối khổng lồ mang những truyền thuyết tâm linh huyền bí của người dân địa phương.\",\n          \"community_impact\": \"Dịch vụ tự do, không thu phí vé, có thể ủng hộ 20.000đ gửi xe tại nhà dân dưới chân núi.\",\n          \"suggestion\": \"Lưu ý leo nhẹ nhàng và mang giày thể thao chống trơn trượt để lên đỉnh ngắm toàn cảnh thung lũng.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy trên đường về lại Buôn Ma Thuột.\",\n          \"price\": \"20.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Mua sắm đặc sản làm quà và kết thúc hành trình\",\n          \"reason\": \"Ghé chợ truyền thống hoặc các cơ sở uy tín mua cà phê, mật ong rừng, bò một nắng làm quà lưu niệm ý nghĩa.\",\n          \"community_impact\": \"Dự kiến 300.000đ mua sắm nông sản trực tiếp từ tiểu thương địa phương.\",\n          \"suggestion\": \"Ghé Chợ Trung tâm Buôn Ma Thuột để mua sắm. Thưởng thức ly cà phê cuối trước khi ra sân bay tại SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy về trung tâm, sau đó di chuyển ra sân bay bằng taxi.\",\n          \"price\": \"350.000đ\"\n        }\n      ]\n    }\n  ]\n}\n', '2026-08-04 16:24:11'),
