(61, NULL, 'Lịch trình 3 ngày - văn hoá, ẩm thực', 3, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hơi thở Bản sắc Ê Đê và Hương vị Ban Mê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hoá cà phê mộc mạc và khám phá góc nhỏ yên bình của Buôn Ma Thuột\",\n          \"reason\": \"Bắt đầu ngày mới bằng việc tìm hiểu nét văn hoá cà phê đặc trưng của thủ phủ Tây Nguyên, phù hợp với sở thích ẩm thực và phong cách nhẹ nhàng.\",\n          \"community_impact\": \"Dự kiến 150.000đ đóng góp vào quán cà phê địa phương phát triển bền vững.\",\n          \"suggestion\": \"Trải nghiệm tại SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) để thưởng thức cà phê đặc sản đúng điệu.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy tự thuê (chi phí khoảng 120.000đ/ngày) di chuyển trong nội thành.\",\n          \"price\": \"60.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên đậm đà và nghỉ ngơi trưa\",\n          \"reason\": \"Khám phá ẩm thực bản địa độc đáo với món bò nhúng me hoặc gỏi cà đắng.\",\n          \"community_impact\": \"Dự kiến 300.000đ chi tiêu tại nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ trưa tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột) - một góc nhỏ xanh mát và yên tĩnh.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy cá nhân.\",\n          \"price\": \"180.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Khám phá buôn cổ Akô Dhông thanh bình, tìm hiểu kiến trúc nhà dài\",\n          \"reason\": \"Akô Dhông là buôn làng kiểu mẫu của người Ê Đê với những nếp nhà d