(62, NULL, 'Lịch trình 4 ngày - thiên nhiên, văn hoá, ẩm thực', 4, 'thiên nhiên, văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá thủ phủ cà phê và văn hóa Ê Đê giữa lòng Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": \"6\",\n          \"activity\": \"Trải nghiệm văn hóa cà phê đặc sắc và thưởng thức bữa sáng tại Thủ phủ cà phê\",\n          \"reason\": \"Khởi đầu ngày mới tràn đầy năng lượng tại thủ phủ cà phê, tìm hiểu văn hóa bản địa độc đáo phù hợp với sở thích ẩm thực và lịch sử.\",\n          \"community_impact\": \"Dự kiến 150.000đ đóng góp vào doanh thu nông sản và chuỗi cung ứng cà phê địa phương.\",\n          \"suggestion\": \"Ăn sáng tại Quán Phở hai tô 52 (địa chỉ: 52 Ngô Quyền, TP. Buôn Ma Thuột), sau đó thưởng thức cà phê tại SOUL Roastery (địa chỉ: 87 Nguyễn Khuyến, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Thuê xe máy tự lái tại trung tâm thành phố (chi phí khoảng 120.000đ/ngày).\",\n          \"price\": \"180.000 VNĐ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên và nhận phòng nghỉ ngơi\",\n          \"reason\": \"Nạp năng lượng với các món ăn đặc sản vùng miền và nghỉ ngơi để chuẩn bị cho hành trình buổi chiều.\",\n          \"community_impact\": \"Dự kiến 250.000đ chi tiêu cho nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (địa chỉ: 140 Lê Thánh Tông, TP. Buôn Ma Thuột) với món bò nhúng me nổi tiếng. Nghỉ trưa và lưu trú tại Zan Homestay (địa chỉ: 37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy cá nhân.\",\n          \"price\": \"350.000 VNĐ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": \"7\",\n          \"activity\": \"Ghé thăm Buôn Akô Dhông - Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột\",\n          \"reason\": \"Khám phá kiến trúc nhà dài truyền thống, hòa mình vào không gian văn hóa bản địa mộc mạc và bình yên.\",\n          \"community_impact\": \"Dự kiến 100.000đ mua đồ thủ công mỹ nghệ trực tiếp từ đồng bào Ê Đê.\",\n          \"suggestion\": \"Ghé Arul Coffee (địa chỉ: 17 Trần Nhật Duật, TP. Buôn Ma Thuột) nằm ngay trong buôn để ngắm nhà sàn xưa.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy, quãng đường rất gần trung tâm (~3km).\",\n          \"price\": \"50.000 VNĐ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Khám phá ẩm thực đường phố Buôn Ma Thuột về đêm\",\n          \"reason\": \"Trải nghiệm nhịp sống tối và các món ăn đường phố độc đáo của Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 150.000đ ủng hộ các hộ kinh doanh ẩm thực đêm.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (địa chỉ: Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột). Nghỉ đêm tại Zan Homestay (địa chỉ: 37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ hoặc xe máy dạo quanh phố phường.\",\n          \"price\": \"100.000 VNĐ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hành trình về miền đất huyền thoại Buôn Đôn và rừng đại ngàn Yok Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": \"4\",\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu nghề săn bắt và thuần dưỡng voi\",\n          \"reason\": \"Khám phá lịch sử, văn hóa bản địa đặc trưng, check-in cầu treo và nhà sàn cổ hơn trăm tuổi.\",\n          \"community_impact\": \"Dự kiến 150.000đ vé tham quan và dịch vụ thuyết minh đóng góp vào quỹ bảo tồn văn hóa.\",\n          \"suggestion\": \"Ăn sáng nhẹ tại trung tâm trước khi khởi hành. Trải nghiệm đi cầu treo Buôn Đôn.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô tự lái hoặc xe máy theo hướng Tỉnh lộ 1 (~40km từ trung tâm).\",\n          \"price\": \"100.000 VNĐ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa ẩm thực bản địa và nghỉ trưa tại Buôn Đôn\",\n          \"reason\": \"Thưởng thức các món đặc sản như cơm lam, gà nướng và cá lăng sông Serepok.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng sinh thái của người bản địa.\",\n          \"suggestion\": \"Ăn trưa tại Nhà hàng sinh thái Bản Đôn (địa chỉ: Trục đường chính Buôn Đôn, Đắk Lắk). Nghỉ trưa tại homestay sinh thái Cư H\'Lăm Restaurant & Homestay (địa chỉ: Thị trấn Ea Pốk, Cư M\'gar - trên đường di chuyển).\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Nghỉ ngơi tại chỗ.\",\n          \"price\": \"250.000 VNĐ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": \"5\",\n          \"activity\": \"Trải nghiệm thiên nhiên hoang dã tại Vườn quốc gia Yok Đôn\",\n          \"reason\": \"Yêu thích thiên nhiên hoang sơ, trải nghiệm mô hình du lịch thân thiện với voi (không cưỡi voi) và đi bộ dưới tán rừng khộp.\",\n          \"community_impact\": \"Dự kiến 300.000đ phí hướng dẫn viên kiểm lâm địa phương và bảo tồn động vật hoang dã.\",\n          \"suggestion\": \"Đăng ký tour trải nghiệm xem voi thân thiện tại Ban quản lý Vườn quốc gia Yok Đôn.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô liên kết giữa 2 điểm sát cạnh nhau.\",\n          \"price\": \"300.000 VNĐ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Trở về thành phố, thưởng thức bánh ướt chồng dĩa độc đáo\",\n          \"reason\": \"Trải nghiệm món ăn đặc sản vô cùng thú vị của giới trẻ Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 120.000đ cho quán ăn gia đình địa phương.\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45 (địa chỉ: 45 Lê Thánh Tông, TP. Buôn Ma Thuột). Nghỉ đêm tại Khách sạn Sài Gòn - Ban Mê (địa chỉ: 01-03 Phan Chu Trinh, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển về lại trung tâm thành phố (~40km) bằng xe máy hoặc ô tô.\",\n          \"price\": \"120.000 VNĐ\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Chinh phục ngọn thác hùng vĩ Dray Nur và ngắm hoàng hôn Hồ Ea Kao\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": \"2\",\n          \"activity\": \"Hòa mình vào thiên nhiên kỳ vĩ tại Thác Dray Nur\",\n          \"reason\": \"Chiêm ngưỡng dòng thác nước khổng lồ, bọt tung trắng xóa, phù hợp với du khách yêu thiên nhiên, thích chụp ảnh và trekking nhẹ nhàng.\",\n          \"community_impact\": \"Dự kiến 100.000đ mua sắm nước uống, nông sản của người dân quanh khu du lịch.\",\n          \"suggestion\": \"Ăn sáng bún cá sứa tại trung tâm rồi di chuyển sớm để tận hưởng không khí mát mẻ của dòng thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi (~25km từ trung tâm thành phố).\",\n          \"price\": \"80.000 VNĐ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên bên bờ thác và nghỉ ngơi\",\n          \"reason\": \"Nghỉ ngơi mát mẻ dưới bóng cây cổ thụ và thưởng thức ẩm thực bản địa ngon miệng.\",\n          \"community_impact\": \"Dự kiến 200.000đ chi phí ăn uống tại khu du lịch.\",\n          \"suggestion\": \"Ăn trưa tại Nhà hàng trong Khu du lịch Thác Dray Nur. Nghỉ trưa võng dưới bóng mát cây rừng hoặc tại nhà sàn dịch vụ.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ trong khu vực thác.\",\n          \"price\": \"200.000 VNĐ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": \"8\",\n          \"activity\": \"Thư giãn và đón hoàng hôn lãng mạn tại Hồ Ea Kao\",\n          \"reason\": \"Hồ nước rộng lớn, không khí trong lành, là địa điểm tuyệt vời nhất để ngắm hoàng hôn buông xuống ngoại ô thành phố.\",\n          \"community_impact\": \"Dự kiến 50.000đ thưởng thức nước dừa, ăn vặt ven hồ của các hộ kinh doanh nhỏ.\",\n          \"suggestion\": \"Dạo bước ven bờ kè hồ, ngắm cảnh hoàng hôn rực rỡ.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển từ thác Dray Nur về Hồ Ea Kao bằng xe máy (~30km).\",\n          \"price\": \"30.000 VNĐ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Tiệc tối ấm cúng và nghỉ ngơi thư giãn\",\n          \"reason\": \"Tận hưởng đêm cuối tại Buôn Ma Thuột với không gian lưu trú xanh, gần gũi thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 400.000đ chi phí ăn uống và lưu trú sinh thái.\",\n          \"suggestion\": \"Ăn tối và nghỉ qua đêm tại Lee\'s House (địa chỉ: 55 đường số 3, xã Cư Bur, TP. Buôn Ma Thuột) - homestay có view thung lũng cực đẹp.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi về Homestay.\",\n          \"price\": \"600.000 VNĐ\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Huyền thoại Hồ Lắk và kỳ quan Đá Voi Mẹ trước khi tạm biệt đại ngàn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": \"16\",\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ khổng lồ\",\n          \"reason\": \"Chinh phục tảng đá nguyên khối lớn nhất Việt Nam, ngắm toàn cảnh cánh đồng và cánh rừng sừng sững từ trên cao.\",\n          \"community_impact\": \"Dự kiến 50.000đ ủng hộ dịch vụ gửi xe và nước giải khát của hộ dân dưới chân núi.\",\n          \"suggestion\": \"Chuẩn bị giày có độ bám tốt để leo đá an toàn. Chụp ảnh lưu niệm tại lưng chừng núi đá.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô theo Quốc lộ 27 hướng đi Lâm Đồng (~40km từ trung tâm).\",\n          \"price\": \"20.000 VNĐ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": \"1\",\n          \"activity\": \"Khám phá Hồ Lắk, đi thuyền độc mộc và ăn trưa đặc sản cá thác lác\",\n          \"reason\": \"Hồ nước ngọt tự nhiên thơ mộng, tìm hiểu đời sống văn hóa lâu đời của người M\'nông và thưởng thức chả cá thác lác trứ danh.\",\n          \"community_impact\": \"Dự kiến 300.000đ chi phí thuê thuyền độc mộc trực tiếp từ người dân bản địa.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng thuộc Lak Tented Camp hoặc quán ăn ven hồ với món chả cá thác lác hồ Lắk. Trải nghiệm đi thuyền độc mộc trên hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển từ Núi Đá Voi Mẹ đến Hồ Lắk khoảng 15km bằng xe máy/ô tô.\",\n          \"price\": \"450.000 VNĐ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": null,\n          \"activity\": \"Ghé thăm buôn Lê, buôn Jun và mua sắm quà lưu niệm đặc sản\",\n          \"reason\": \"Trải nghiệm chiều sâu văn hóa của người M\'nông rơm, tìm hiểu dệt thổ cẩm và mua sắm nông sản địa phương làm quà.\",\n          \"community_impact\": \"Dự kiến 500.000đ mua đặc sản cà phê, thịt nai khô, mật ong rừng trực tiếp từ các hợp tác xã OCOP địa phương.\",\n          \"suggestion\": \"Mua sắm đặc sản chất lượng tại các cửa hàng uy tín quanh khu vực Buôn Ma Thuột trước khi ra sân bay/bến xe.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô quay về hướng trung tâm Buôn Ma Thuột.\",\n          \"price\": \"500.000 VNĐ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Bữa tối nhẹ nhàng và kết thúc hành trình 4 ngày 3 đêm ý nghĩa\",\n          \"reason\": \"Hoàn tất chuyến đi, thư giãn cơ thể trước khi di chuyển về lại nhà.\",\n          \"community_impact\": \"Dự kiến 100.000đ cho dịch vụ vận chuyển và ẩm thực nhẹ.\",\n          \"suggestion\": \"Ăn tối nhẹ nhàng với món bánh canh hoặc hủ tiếu tại trung tâm thành phố trước khi di chuyển ra Sân bay Buôn Ma Thuột.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Taxi di chuyển ra sân bay hoặc bến xe để về lại điểm xuất phát.\",\n          \"price\": \"150.000 VNĐ\"\n        }\n      ]\n    }\n  ]\n}', '2026-08-04 16:36:20');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(63, NULL, 'Lịch trình 4 ngày - văn hoá, ẩm thực', 4, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hương vị Thủ phủ Cà phê và Văn hóa Ê Đê giữa lòng Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hoá cà phê đặc sắc tại Thủ phủ cà phê Việt Nam\",\n          \"reason\": \"Khởi đầu ngày mới bằng việc tìm hiểu và thưởng thức ly cà phê Đắk Lắk đậm đà đúng sở thích ẩm thực của du khách.\",\n          \"community_impact\": \"Dự kiến 150.000đ mua quà lưu niệm và ủng hộ các quán nước địa phương.\",\n          \"suggestion\": \"SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) hoặc Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy tự lái (thuê khoảng 150.000đ/ngày) hoặc Taxi di chuyển trong nội thành.\",\n          \"price\": \"70.000đ - 120.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức ẩm thực Tây Nguyên và nghỉ trưa tại trung tâm thành phố\",\n          \"reason\": \"Phục hồi năng lượng bằng các món ăn đặc sản đậm chất văn hóa bản địa.\",\n          \"community_impact\": \"Dự kiến 300.000đ chi tiêu tại nhà hàng địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) với món bò nhúng me nổi tiếng. Nghỉ trưa tại Zan Homestay (37 Hồ Giáo, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi di chuyển ngắn trong nội thành.\",\n          \"price\": \"150.000đ - 250.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột\",\n          \"reason\": \"Khám phá kiến trúc nhà dài truyền thống của người Ê Đê và hòa mình vào không gian văn hóa đặc sắc.\",\n          \"community_impact\": \"Dự kiến 100.000đ mua đồ thủ công mĩ nghệ của người đồng bào.\",\n          \"suggestion\": \"Ghé Arul Coffee (17 Trần Nhật Duật, TP. Buôn Ma Thuột) nằm ngay trong buôn để trải nghiệm uống cà phê trong nhà sàn gỗ.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ tham quan xung quanh buôn làng.\",\n          \"price\": \"Miễn phí vé vào cửa (chỉ tính chi phí nước uống tự chọn)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Trải nghiệm ẩm thực đường phố Buôn Ma Thuột về đêm\",\n          \"reason\": \"Khám phá các món ăn vặt trứ danh của phố núi như Bún đỏ, Bánh ướt chồng dĩa.\",\n          \"community_impact\": \"Dự kiến 150.000đ mua sắm quà vặt lề đường.\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong) hoặc Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Nghỉ đêm tại Khách sạn Hai Bà Trưng (8 Hai Bà Trưng, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc đi bộ quanh khu vực trung tâm.\",\n          \"price\": \"50.000đ - 100.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Hùng vĩ Đại ngàn và Truyền thuyết Voi Buôn Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, khám phá cầu treo và nhà sàn cổ trăm tuổi\",\n          \"reason\": \"Tìm hiểu về nghề săn bắt và thuần dưỡng voi rừng huyền thoại, tìm về gốc rễ văn hóa bản địa.\",\n          \"community_impact\": \"Dự kiến 200.000đ chi phí cho các dịch vụ do hướng dẫn viên địa phương thuyết minh.\",\n          \"suggestion\": \"Mua vé tham quan Khu du lịch Cầu Treo Buôn Đôn. Thử trải nghiệm các sản phẩm dệt thổ cẩm của người M\'nông.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Thuê ô tô tự lái hoặc taxi di chuyển từ trung tâm TP. Buôn Ma Thuột khoảng 40km.\",\n          \"price\": \"40.000đ - 80.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức cơm lam, gà nướng và cá lăng sông Sêrêpốk\",\n          \"reason\": \"Thưởng thức các món ăn dân dã Tây Nguyên ngay bên dòng sông huyền thoại.\",\n          \"community_impact\": \"Dự kiến 350.000đ ủng hộ nhà hàng sinh thái của người bản địa.\",\n          \"suggestion\": \"Dùng bữa tại Cư H\'Lăm Restaurant & Homestay (Ea Pốk, trên đường từ Buôn Đôn về). Nghỉ trưa trực tiếp tại nhà sàn của homestay.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô hoặc xe máy.\",\n          \"price\": \"200.000đ - 300.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 5,\n          \"activity\": \"Trải nghiệm du lịch sinh thái thân thiện tại Vườn quốc gia Yok Đôn\",\n          \"reason\": \"Khám phá rừng khộp độc nhất vô nhị của Việt Nam, trải nghiệm tour xem voi thân thiện (không cưỡi voi).\",\n          \"community_impact\": \"Dự kiến 500.000đ đóng góp vào quỹ bảo tồn voi và tạo thu nhập cho kiểm lâm địa phương.\",\n          \"suggestion\": \"Đăng ký dịch vụ hướng dẫn trải nghiệm ngắm voi thân thiện trực tiếp tại ban quản lý rừng.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi bộ trekking nhẹ nhàng trong rừng theo chỉ dẫn.\",\n          \"price\": \"300.000đ - 500.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối đặc sản Phở hai tô và dạo chơi chợ đêm\",\n          \"reason\": \"Trải nghiệm phong cách ẩm thực độc đáo giao thoa vùng miền Gia Lai - Đắk Lắk.\",\n          \"community_impact\": \"Dự kiến 100.000đ tiêu dùng dịch vụ chợ đêm.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại Homestay Lee\'s House (55 đường số 3, xã Cư Bur, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi về lại trung tâm thành phố.\",\n          \"price\": \"45.000đ - 60.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Huyền thoại Hồ Lắk và Văn hóa M\'nông Rơm\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ - tảng đá nguyên khối khổng lồ\",\n          \"reason\": \"Chiêm ngưỡng cảnh quan bao la từ đỉnh đá và nghe kể truyền thuyết thần kỳ về hòn đá biết đi.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua nước và đồ ăn nhẹ tại các quầy hàng dưới chân núi.\",\n          \"suggestion\": \"Mang giày thể thao có độ bám tốt để leo đá an toàn.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển theo Quốc lộ 27 hướng đi Lâm Đồng khoảng 40km từ trung tâm Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí vé tham quan (chỉ mất tiền gửi xe khoảng 10.000đ)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức chả cá thát lát Hồ Lắk và đặc sản địa phương\",\n          \"reason\": \"Thưởng thức món chả cá nổi tiếng dai ngon tự nhiên từ nguồn nước Hồ Lắk.\",\n          \"community_impact\": \"Dự kiến 250.000đ mua sắm đặc sản chả cá đóng gói mang về làm quà.\",\n          \"suggestion\": \"Dùng bữa trưa tại nhà hàng ven hồ trong khu vực buôn Jun. Nghỉ trưa tại Lak Tented Camp (ven Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô.\",\n          \"price\": \"150.000đ - 250.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 1,\n          \"activity\": \"Đi thuyền độc mộc ngắm cảnh trên Hồ Lắk và giao lưu văn hóa buôn Jun\",\n          \"reason\": \"Cảm nhận sự bình yên trên hồ nước ngọt lớn thứ 2 Việt Nam bằng thuyền độc mộc truyền thống, tìm hiểu đời sống của người M\'nông Rơm.\",\n          \"community_impact\": \"Dự kiến 200.000đ trực tiếp trả cho nghệ nhân chèo thuyền độc mộc người bản địa.\",\n          \"suggestion\": \"Thuê thuyền độc mộc của người dân bản địa tại bến thuyền Buôn Jun.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng thuyền gỗ trên hồ.\",\n          \"price\": \"150.000đ - 200.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Trải nghiệm Đêm hội cồng chiêng Tây Nguyên và nghỉ đêm ven hồ\",\n          \"reason\": \"Hoà mình vào không gian văn hoá cồng chiêng - di sản văn hoá phi vật thể đã được UNESCO công nhận.\",\n          \"community_impact\": \"Dự kiến 500.000đ hỗ trợ đội văn nghệ cồng chiêng của buôn làng.\",\n          \"suggestion\": \"Đăng ký xem biểu diễn cồng chiêng và uống rượu cần tại Buôn Jun. Nghỉ đêm tại Lak Tented Camp để tận hưởng không khí mát mẻ ven hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ quanh khu vực buôn cổ.\",\n          \"price\": \"200.000đ - 300.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Bản hùng ca Thác nước Krông Ana trước giờ tạm biệt\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Chiêm ngưỡng sự hùng vĩ của Thác Dray Nur\",\n          \"reason\": \"Tận hưởng không khí trong lành của ngọn thác lớn nhất vùng, cảm nhận dòng năng lượng sảng khoái từ thiên nhiên.\",\n          \"community_impact\": \"Dự kiến 100.000đ mua các loại nông sản ép nước của người dân bản địa.\",\n          \"suggestion\": \"Chuẩn bị trang phục dã ngoại thoải mái và chụp ảnh lưu niệm dưới chân thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển từ Hồ Lắk đi đường tắt hoặc về ngã ba EaKtur để vào thác Dray Nur khoảng 30km.\",\n          \"price\": \"30.000đ - 50.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại và nghỉ ngơi bên tiếng thác đổ\",\n          \"reason\": \"Kết hợp ăn trưa nghỉ ngơi thư giãn giữa rừng cây đại ngàn trước khi kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 150.000đ chi trả cho dịch vụ ăn uống lâm viên.\",\n          \"suggestion\": \"Đặt đồ ăn gà nướng, cơm lam tại nhà hàng ngay trong khu du lịch Thác Dray Nur. Nghỉ trưa tại các lán trại võng có sẵn.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ trong khuôn viên khu du lịch.\",\n          \"price\": \"150.000đ - 200.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 3,\n          \"activity\": \"Khám phá Thác Dray Sáp lân cận\",\n          \"reason\": \"Hoàn thành bộ đôi thác nước huyền thoại của dòng sông Sêrêpốk.\",\n          \"community_impact\": \"Dự kiến 100.000đ chi tiêu dịch vụ phụ trợ.\",\n          \"suggestion\": \"Nên đi giày chống trơn trượt để tham quan các mỏm đá ngắm cảnh thác khói.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ qua cầu treo hoặc di chuyển xe máy đoạn ngắn giữa hai khu thác.\",\n          \"price\": \"40.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Mua sắm đặc sản và tiễn sân bay Buôn Ma Thuột\",\n          \"reason\": \"Mua sắm những món quà ý nghĩa cuối hành trình mang hương vị Tây Nguyên về cho gia đình.\",\n          \"community_impact\": \"Dự kiến 1.000.000đ mua các đặc sản địa phương như hạt tiêu, cà phê bột, thịt nai khô.\",\n          \"suggestion\": \"Ghé các cửa hàng uy tín tại trung tâm thành phố để mua đặc sản chất lượng. Kết thúc hành trình 4 ngày 3 đêm trọn vẹn văn hoá - ẩm thực.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô/taxi ra Sân bay Buôn Ma Thuột (khoảng 10km từ trung tâm).\",\n          \"price\": \"150.000đ - 200.000đ (tiền taxi ra sân bay)\"\n        }\n      ]\n    }\n  ]\n}', '2026-08-04 16:38:07'),
(64, NULL, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Ê Đê và Hương vị Thủ phủ Cà phê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 6,\n          \"activity\": \"Thưởng thức và trải nghiệm không gian văn hoá cà phê đặc sắc tại Buôn Ma Thuột\",\n          \"reason\": \"Phù hợp với sở thích ẩm thực và tìm hiểu văn hóa khởi đầu ngày mới đầy năng lượng\",\n          \"community_impact\": \"Dự kiến 150.000đ đóng góp vào doanh thu dịch vụ địa phương\",\n          \"suggestion\": \"Thưởng thức cà phê tại SOUL Roastery (87 Nguyễn Khuyến, TP. Buôn Ma Thuột) hoặc Làng cà phê Trung Nguyên (163 Lý Thái Tổ, TP. Buôn Ma Thuột)\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy tự lái hoặc Grab Car di chuyển trong trung tâm thành phố\",\n          \"price\": \"50.000đ - 100.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Tây Nguyên và nghỉ ngơi giữ sức\",\n          \"reason\": \"Khám phá ẩm thực độc đáo của Đắk Lắk với các món ăn mang đậm hương vị núi rừng\",\n          \"community_impact\": \"Dự kiến 250.000đ cho nhà hàng địa phương\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông, TP. Buôn Ma Thuột) với món bò nhúng me đặc sản. Nghỉ trưa tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy hoặc taxi di chuyển ngắn\",\n          \"price\": \"150.000đ - 250.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 7,\n          \"activity\": \"Ghé thăm Buôn Akô Dhông - buôn làng Ê Đê kiểu mẫu giữa lòng thành phố\",\n          \"reason\": \"Phù hợp với sở thích tìm hiểu văn hoá bản địa, ngắm nhà dài truyền thống và chụp ảnh lưu niệm\",\n     