activity\": \"Khám phá Bản Đôn - quê hương nghề săn bắt, thuần dưỡng voi\",\n          \"reason\": \"Tìm hiểu nét văn hóa bản địa lâu đời, đi cầu treo bằng tre bắc qua sông Serepôk và nghe kể về Vua Voi.\",\n          \"community_impact\": \"Dự kiến 150.000đ phí thuyết minh và mua đồ lưu niệm của đồng bào M\'nông.\",\n          \"suggestion\": \"Tham quan nhà sàn cổ hơn 120 tuổi của Vua săn voi Khun Ju Nốp.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Đi xe máy hoặc taxi dọc theo đường tỉnh lộ 1 khoảng 40km từ thành phố.\",\n          \"price\": \"100.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Thưởng thức bữa trưa bản địa Buôn Đôn\",\n          \"reason\": \"Trải nghiệm các món ăn mang đậm phong vị Tây Nguyên như heo rẫy nướng, lẩu rau rừng.\",\n          \"community_impact\": \"Dự kiến 300.000đ cho nhà hàng sinh thái địa phương.\",\n          \"suggestion\": \"Ăn trưa tại Nhà hàng sinh thái Bản Đôn Thanh Hà. Nghỉ trưa tại homestay Cư H\'Lăm (Thị trấn Ea Pốk, trên đường về lại TP).\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy.\",\n          \"price\": \"150.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 5,\n          \"activity\": \"Trekking nhẹ nhàng tại Vườn quốc gia Yok Đôn\",\n          \"reason\": \"Khám phá hệ sinh thái rừng khộp duy nhất tại Việt Nam và trải nghiệm du lịch thân thiện với voi (không cưỡi voi).\",\n          \"community_impact\": \"Dự kiến 300.000đ thuê hướng dẫn viên kiểm lâm địa phương dẫn đường bảo tồn.\",\n          \"suggestion\": \"Nên đặt trước dịch vụ ngắm voi thân thiện để ủng hộ mô hình bảo tồn voi.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy sát bên khu Buôn Đôn.\",\n          \"price\": \"350.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối món Phở hai tô đặc trưng và thư giãn\",\n          \"reason\": \"Thưởng thức nét giao thoa ẩm thực độc đáo của vùng Cao Nguyên.\",\n          \"community_impact\": \"Dự kiến 100.000đ hỗ trợ quán ăn gia đình.\",\n          \"suggestion\": \"Ăn tối tại Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ đêm tại An Homestay (137/91 Thôi Hữu, TP. Buôn Ma Thuột).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy về lại thành phố.\",\n          \"price\": \"50.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Bình yên Hồ Lắk và Đá Voi Mẹ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục đỉnh Núi Đá Voi Mẹ khổng lồ\",\n          \"reason\": \"Chiêm ngưỡng tảng đá nguyên khối lớn nhất Việt Nam, ngắm toàn cảnh thung lũng lúa xanh rì từ trên cao.\",\n          \"community_impact\": \"Dự kiến 50.000đ mua nông sản địa phương dưới chân núi.\",\n          \"suggestion\": \"Mang giày thể thao chống trơn trượt để leo lên lưng đá voi an toàn.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy xuôi theo quốc lộ 27 khoảng 40km hướng đi Lâm Đồng.\",\n          \"price\": \"20.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": 1,\n          \"activity\": \"Khám phá Hồ Lắk và thưởng thức đặc sản chả cá thát lát\",\n          \"reason\": \"Chiêm ngưỡng hồ nước ngọt tự nhiên thơ mộng và trải nghiệm bữa trưa với các món cá đặc sản của hồ nước ngọt.\",\n          \"community_impact\": \"Dự kiến 350.000đ chi tiêu ăn uống tại nhà hàng ven hồ của người dân bản địa.\",\n          \"suggestion\": \"Ăn trưa tại nhà hàng ven hồ Lắk với món Chả cá thát lát cuộn lá thì là. Nghỉ trưa tại Lak Tented Camp (ven Hồ Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy khoảng 10km từ Đá Voi Mẹ đến Hồ Lắk.\",\n          \"price\": \"200.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 1,\n          \"activity\": \"Trải nghiệm đi thuyền độc mộc trên Hồ Lắk\",\n          \"reason\": \"Hòa mình vào không gian văn hóa M\'nông Gar, lênh đênh ngắm hoàng hôn buông xuống mặt hồ yên ả.\",\n          \"community_impact\": \"Dự kiến 200.000đ trả trực tiếp cho người chèo thuyền độc mộc địa phương.\",\n          \"suggestion\": \"Nên trải nghiệm vào lúc xế chiều để đón được ánh nắng hoàng hôn đẹp nhất.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi thuyền gỗ trên hồ.\",\n          \"price\": \"150.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối nhẹ và kết thúc hành trình ý nghĩa\",\n          \"reason\": \"Mua sắm quà lưu niệm đặc sản Tây Nguyên trước khi ra sân bay/bến xe kết thúc chuyến đi.\",\n          \"community_impact\": \"Dự kiến 500.000đ mua đặc sản cà phê, thịt nai khô, mật ong rừng làm quà.\",\n          \"suggestion\": \"Ghé các cửa hàng uy tín tại trung tâm thành phố để chọn mua quà lưu niệm chất lượng. Nghỉ ngơi tại quán cà phê Làng cà phê Trung Nguyên (163 Lý Thái Tổ) trước giờ khởi hành.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển xe máy về lại thành phố trả xe và đi taxi ra sân bay.\",\n          \"price\": \"100.000đ\"\n        }\n      ]\n    }\n  ]\n}', '2026-08-04 17:23:19'),
(66, NULL, 'Lịch trình 3 ngày - văn hoá, ẩm thực, trekking', 3, 'văn hoá, ẩm thực, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hoá Ê Đê và Hương vị Thủ phủ Cà phê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 7,\n          \"activity\": \"Tham quan Buôn Akô Dhông - buôn làng Ê Đê đẹp nhất Buôn Ma Thuột\",\n          \"reason\": \"Thỏa mãn sở thích tìm hiểu văn hóa bản địa, ngắm nhà dài truyền thống và tìm hiểu đời sống người Ê Đê.\",\n          \"community_impact\": \"Dự kiến 100.000đ mua đồ lưu niệm thủ công của đồng bào Ê Đê\",\n          \"suggestion\": \"Trải nghiệm Arul Coffee tại 17 Trần Nhật Duật ngay trong lòng buôn để thưởng thức cà phê trong không gian nhà sàn.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy thuê tự lái di chuyển trong thành phố\",\n          \"price\": \"50.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa đặc sản Tây Nguyên và nghỉ ngơi\",\n          \"reason\": \"Thưởng thức ẩm thực địa phương đặc sắc, tái tạo năng lượng sau một buổi sáng đi bộ nhiều.\",\n          \"community_impact\": \"Dự kiến 150.000đ chi tiêu tại nhà hàng địa phương\",\n          \"suggestion\": \"Ăn trưa tại Quán Cà Te (140 Lê Thánh Tông) với món bò nhúng me nổi tiếng. Nghỉ trưa tại Zan Homestay (37 Hồ Giáo).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"180.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 6,\n          \"activity\": \"Trải nghiệm văn hoá và bảo tàng thế giới cà phê\",\n          \"reason\": \"Kết hợp sở thích ẩm thực và tìm hiểu lịch sử ngành cà phê tại vùng đất thủ phủ.\",\n          \"community_impact\": \"Dự kiến mua cà phê bột nguyên chất làm quà hỗ trợ HTX địa phương ~200.000đ\",\n          \"suggestion\": \"Thưởng thức cà phê phin đặc trưng tại SOUL Roastery (87 Nguyễn Khuyến).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"150.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối bún đỏ truyền thống và dạo chợ đêm\",\n          \"reason\": \"Trải nghiệm món ăn đường phố biểu tượng của Buôn Ma Thuột và cảm nhận nhịp sống chợ đêm.\",\n          \"community_impact\": \"Dự kiến mua sắm nông sản, trái cây tại chợ truyền thống ~100.000đ\",\n          \"suggestion\": \"Ăn tối tại Bún đỏ cô Thu (Ngã 4 Phan Đình Giót - Lê Hồng Phong). Nghỉ đêm tại Khách sạn Hai Bà Trưng (8 Hai Bà Trưng).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Đi bộ và xe máy\",\n          \"price\": \"80.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trekking Thác Nước Hùng Vĩ và Check-in Núi Đá Voi\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 2,\n          \"activity\": \"Trekking khám phá Thác Dray Nur\",\n          \"reason\": \"Đáp ứng nhu cầu trekking, hòa mình vào thiên nhiên hùng vĩ của một trong những ngọn thác lớn nhất Tây Nguyên.\",\n          \"community_impact\": \"Dự kiến mua nước uống và dịch vụ chỉ dẫn từ người bản địa 50.000đ\",\n          \"suggestion\": \"Nên mang giày thể thao độ bám tốt để trekking dọc bờ đá quanh chân thác.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển khoảng 25km từ trung tâm thành phố\",\n          \"price\": \"120.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa dã ngoại ẩm thực bên dòng Serepok và nghỉ ngơi\",\n          \"reason\": \"Nạp năng lượng bằng các món ăn nướng đặc sản núi rừng bên cạnh dòng nước mát.\",\n          \"community_impact\": \"Dự kiến chi tiêu cho dịch vụ ẩm thực tại khu du lịch thác 200.000đ\",\n          \"suggestion\": \"Ăn gà nướng cơm lam ngay tại nhà hàng khu du lịch Thác Dray Nur. Nghỉ ngơi võng mát ven suối.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Tại chỗ\",\n          \"price\": \"200.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 16,\n          \"activity\": \"Chinh phục Núi Đá Voi Mẹ khổng lồ\",\n          \"reason\": \"Trải nghiệm leo núi nhẹ nhàng lên đỉnh tảng đá nguyên khối lớn nhất Việt Nam để ngắm toàn cảnh đại ngàn.\",\n          \"community_impact\": \"Dự kiến ủng hộ 30.000đ phí gửi xe và nước mát tại nhà dân chân núi\",\n          \"suggestion\": \"Leo núi vào tầm xế chiều để tránh nắng gắt, có thể ngắm hoàng hôn buông xuống rừng cây.\",\n          \"address\": \"Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển theo hướng QL27 về phía huyện Lắk\",\n          \"price\": \"50.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối đặc sản cá bống hồ Lắk và thưởng thức văn nghệ cồng chiêng\",\n          \"reason\": \"Trải nghiệm ẩm thực vùng hồ và hòa vào không gian văn hóa cồng chiêng M\'nông.\",\n          \"community_impact\": \"Dự kiến 300.000đ đóng góp quỹ phát triển văn hóa cồng chiêng buôn làng\",\n          \"suggestion\": \"Ăn tối và lưu trú qua đêm độc đáo tại Lak Tented Camp (Ven Hồ Lắk, Huyện Lắk).\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Xe máy và thuyền gỗ sang khu nghỉ dưỡng\",\n          \"price\": \"600.000đ\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Bình Minh Trên Hồ Lắk và Trải Nghiệm Bản Địa Buôn Đôn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"destination_id\": 1,\n          \"activity\": \"Đón bình minh trên Hồ Lắk và đi thuyền độc mộc\",\n          \"reason\": \"Khám phá nét văn hóa sông nước độc đáo của người M\'nông rơ-lăm trên hồ nước ngọt lớn thứ 2 Việt Nam.\",\n          \"community_impact\": \"Dự kiến 150.000đ trả trực tiếp cho nghệ nhân chèo thuyền độc mộc địa phương\",\n          \"suggestion\": \"Trải nghiệm ngồi thuyền độc mộc lướt trên hồ khi sương sớm còn bảng lảng.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Thuyền độc mộc và đi bộ quanh buôn Jun\",\n          \"price\": \"200.000đ\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn trưa Phở Hai Tô truyền thống và di chuyển về Buôn Đôn\",\n          \"reason\": \"Thưởng thức món ăn sáng - trưa quen thuộc của người dân phố núi trước khi đi Buôn Đôn.\",\n          \"community_impact\": \"Dự kiến 100.000đ chi trả tại quán ăn địa phương\",\n          \"suggestion\": \"Ăn trưa tại quán Phở hai tô 52 (52 Ngô Quyền, TP. Buôn Ma Thuột). Nghỉ trưa ngắn tại An Homestay (137/91 Thôi Hữu).\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"90.000đ\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"destination_id\": 4,\n          \"activity\": \"Tham quan Buôn Đôn, cầu treo và nhà sàn cổ\",\n          \"reason\": \"Tìm hiểu về truyền thống săn bắt, thuần dưỡng voi rừng huyền thoại và dạo bước trên cầu treo bằng tre bắc qua sông Serepok.\",\n          \"community_impact\": \"Dự kiến 100.000đ mua quà lưu niệm thổ cẩm thủ công tại buôn\",\n          \"suggestion\": \"Ghé thăm nhà sàn cổ hơn trăm tuổi của vua voi Amacông và thử rượu thuốc trứ danh.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Xe máy di chuyển khoảng 40km từ trung tâm\",\n          \"price\": \"100.000đ\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"destination_id\": null,\n          \"activity\": \"Ăn tối bánh ướt chồng dĩa và mua sắm đặc sản\",\n          \"reason\": \"Kết thúc hành trình bằng món ăn chơi vô cùng độc đáo của giới trẻ Buôn Ma Thuột.\",\n          \"community_impact\": \"Dự kiến 400.000đ mua đặc sản thịt nai khô, mật ong rừng tại các cơ sở OCOP địa phương\",\n          \"suggestion\": \"Ăn tối tại Bánh ướt chồng dĩa 45 (45 Lê Thánh Tông). Mua sắm đặc sản tại các cửa hàng uy tín trung tâm thành phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Xe máy\",\n          \"price\": \"450.000đ\"\n        }\n      ]\n    }\n  ]\n}', '2026-08-04 17:28:44');
INSERT INTO `itinerary_items` (`id`, `itinerary_id`, `destination_id`, `day_number`, `time_slot`, `activity`, `address`, `transport`, `sort_order`) VALUES
(9, 4, NULL, 1, 'Sáng', 'Thưởng thức Cà phê Buôn Ma Thuột tại thủ phủ cà phê, tìm hiểu về văn hóa cà phê bản địa và dùng bữa sáng với món bún đỏ đặc sản.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi trong khu vực trung tâm thành phố Buôn Ma Thuột.', 0),
(10, 4, NULL, 1, 'Trưa', 'Ăn trưa với các món ăn truyền thống của người Ê Đê như vếch bò, gà nướng bản địa.', '', 'Đi bộ hoặc đi xe máy khoảng 5-10 phút từ quán cà phê trung tâm.', 1),
(11, 4, NULL, 1, 'Chiều', 'Ghé thăm Buôn Akô Dhông để chiêm ngưỡng những ngôi nhà dài truyền thống của người Ê Đê và tìm hiểu đời sống văn hóa đặc sắc nơi đây.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô khoảng 3km từ trung tâm thành phố.', 2),
(12, 4, NULL, 1, 'Tối', 'Thư giãn, ngắm hoàng hôn và dạo mát tại Hồ Ea Kao, sau đó thưởng thức ẩm thực đường phố quanh hồ.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 20 phút (~12km) từ Buôn Akô Dhông.', 3),
(13, 4, NULL, 2, 'Sáng', 'Khám phá Hồ Lắk, trải nghiệm đi thuyền độc mộc trên hồ nước ngọt tự nhiên lớn thứ hai Việt Nam và tìm hiểu văn hoá của người M\'nông Gar.', 'Huyện Lắk, Đắk Lắk', 'Di chuyển bằng ô tô hoặc xe máy từ trung tâm TP. Buôn Ma Thuột đi theo quốc lộ 27 khoảng 1 giờ 15 phút (~56km).', 4),
(14, 4, NULL, 2, 'Trưa', 'Thưởng thức bữa trưa với các món đặc sản Hồ Lắk như chả cá thát lát, cá bống kho tộ.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ từ khu vực ven hồ đến các nhà hàng ẩm thực lân cận.', 5),
(15, 4, NULL, 2, 'Chiều', 'Di chuyển tham quan Thác Dray Nur, chiêm ngưỡng sự hùng vĩ của một trong những thác nước đẹp nhất Tây Nguyên và chụp ảnh lưu niệm.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng ô tô hoặc xe máy khoảng 1 giờ 30 phút (~60km) từ Hồ Lắk theo hướng về Krông Ana.', 6),
(16, 4, NULL, 2, 'Tối', 'Trở về Buôn Ma Thuột, ăn tối nhẹ nhàng với món bánh ướt chồng dĩa đặc sản và mua sắm quà lưu niệm, cà phê trước khi kết thúc hành trình.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển khoảng 45 phút (~30km) từ Thác Dray Nur về lại trung tâm TP. Buôn Ma Thuột.', 7),
(17, 5, NULL, 1, 'Sáng', 'Khởi đầu ngày mới tại TP. Buôn Ma Thuột bằng việc thưởng thức Cà phê Buôn Ma Thuột, tìm hiểu về lịch sử và văn hoá cà phê của thủ phủ Tây Nguyên.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi trong khu vực nội thành TP. Buôn Ma Thuột.', 0),
(18, 5, NULL, 1, 'Trưa', 'Ghé thăm Buôn Akô Dhông để chiêm ngưỡng những ngôi nhà dài truyền thống của người Ê Đê, tìm hiểu văn hóa bản địa và dùng bữa trưa với các món ăn đặc sản Tây Nguyên.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng ô tô hoặc xe máy khoảng 10 phút (~3km) từ trung tâm thành phố.', 1),
(19, 5, NULL, 1, 'Chiều', 'Thư giãn và dạo chơi tại Hồ Ea Kao, ngắm cảnh hoàng hôn yên bình, thích hợp cho các hoạt động gia đình và chụp ảnh lưu niệm.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng ô tô hoặc xe máy khoảng 20 phút (~9km) về hướng Đông Nam từ Buôn Akô Dhông.', 2),
(20, 5, NULL, 1, 'Tối', 'Trở về trung tâm thành phố ăn tối, tự do dạo phố đêm Buôn Ma Thuột và thưởng thức các món ăn đường phố.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy cá nhân.', 3),
(21, 5, NULL, 2, 'Sáng', 'Hành trình trekking, khám phá vẻ đẹp hoang sơ và kỳ vĩ của Thác Dray Nur. Gia đình có thể đi dạo trên các lối mòn, chụp ảnh check-in và cảm nhận hơi nước mát lạnh.', 'Huyện Krông Ana, Đắk Lắk', 'Thuê ô tô tự lái hoặc xe máy di chuyển khoảng 50 phút (~30km) từ trung tâm TP. Buôn Ma Thuột theo hướng quốc lộ 14 rẽ đường tỉnh 682.', 4),
(22, 5, NULL, 2, 'Trưa', 'Thưởng thức bữa trưa dã ngoại hoặc dùng bữa tại nhà hàng ngay cạnh Thác Dray Nur với các món đặc sản như cơm lam, gà nướng.', 'Huyện Krông Ana, Đắk Lắk', 'Đi bộ trong khu vực cụm thác.', 5),
(23, 5, NULL, 2, 'Chiều', 'Tiếp tục hành trình trekking ngắn sang Thác Dray Sáp lân cận, chiêm ngưỡng dòng thác khói huyền thoại và khám phá hệ sinh thái rừng đặc dụng.', 'Huyện Krông Ana, Đắk Lắk', 'Đi bộ xuyên rừng qua cầu treo kết nối hoặc di chuyển xe máy/ô tô khoảng 5 phút giữa hai khu vực thác.', 6),
(24, 5, NULL, 2, 'Tối', 'Di chuyển về lại trung tâm TP. Buôn Ma Thuột, mua sắm quà lưu niệm (cà phê, đồ thổ cẩm) và kết thúc chuyến hành trình 2 ngày 1 đêm.', '', 'Di chuyển bằng ô tô hoặc xe máy khoảng 50 phút (~30km) để về lại thành phố.', 7),
(25, 6, NULL, 1, 'Sáng', 'Bắt đầu ngày mới với trải nghiệm văn hóa cà phê đặc trưng của Buôn Ma Thuột. Thưởng thức cà phê tại một quán cà phê địa phương, tìm hiểu về quy trình sản xuất và lịch sử cà phê Buôn Ma Thuột. Bạn có thể ghé thăm Bảo tàng Cà phê Thế giới để có cái nhìn sâu sắc hơn.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 0),
(26, 6, NULL, 1, 'Trưa', 'Thưởng thức ẩm thực địa phương với các món ăn đặc sản Đắk Lắk như bún đỏ, phở khô hoặc nem nướng tại một nhà hàng ở trung tâm Buôn Ma Thuột.', '', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 1),
(27, 6, NULL, 1, 'Chiều', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê cổ kính và đẹp nhất Buôn Ma Thuột. Tìm hiểu về kiến trúc nhà dài truyền thống, văn hóa và phong tục tập quán của người Ê Đê.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.', 2),
(28, 6, NULL, 1, 'Tối', 'Ăn tối tại một nhà hàng có không gian ấm cúng ở Buôn Ma Thuột và khám phá chợ đêm để mua sắm đặc sản địa phương hoặc quà lưu niệm.', '', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 3),
(29, 6, NULL, 2, 'Sáng', 'Khám phá Buôn Đôn, một làng văn hóa nổi tiếng với nghề săn bắt và thuần dưỡng voi. Bạn có thể tham quan nhà dài cổ, cầu treo và tìm hiểu về cuộc sống của người dân địa phương. Lưu ý: các hoạt động cưỡi voi đang dần được thay thế bằng các hoạt động thân thiện với voi hơn như cho voi ăn, tắm cho voi.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~45km) từ trung tâm Buôn Ma Thuột.', 4),
(30, 6, NULL, 2, 'Trưa', 'Ăn trưa tại nhà hàng địa phương ở Buôn Đôn hoặc trên đường đi Hồ Lắk, thưởng thức các món ăn mang đậm hương vị núi rừng Tây Nguyên.', '', 'Di chuyển bằng xe máy hoặc ô tô.', 5),
(31, 6, NULL, 2, 'Chiều', 'Tham quan Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, gắn liền với văn hóa M\'nông. Bạn có thể trải nghiệm đi thuyền độc mộc trên hồ, ngắm cảnh hoàng hôn và thăm quan các buôn làng quanh hồ.', 'Huyện Lắk, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1.5 - 2 giờ (~50km) từ Buôn Đôn hoặc khoảng 1.5 giờ (~50km) từ Buôn Ma Thuột. Nên đi theo quốc lộ 27.', 6),
(32, 6, NULL, 2, 'Tối', 'Ăn tối và nghỉ ngơi tại các homestay hoặc nhà nghỉ ven Hồ Lắk để tận hưởng không khí trong lành và yên bình của vùng đất này. Thưởng thức các món cá nước ngọt đặc sản của hồ.', '', 'Đi bộ hoặc di chuyển xe máy/ô tô ngắn trong khu vực Hồ Lắk.', 7),
(33, 7, NULL, 1, 'Sáng sớm', 'Thưởng thức cà phê Buôn Ma Thuột tại một quán cà phê địa phương, tìm hiểu về văn hóa cà phê', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy đến các quán cà phê trung tâm TP Buôn Ma Thuột.', 0),
(34, 7, NULL, 1, 'Sáng', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê truyền thống với những ngôi nhà dài cổ kính.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Từ trung tâm thành phố, di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km).', 1),
(35, 7, NULL, 1, 'Trưa', 'Thưởng thức ẩm thực địa phương tại TP. Buôn Ma Thuột (ví dụ: bún đỏ, nem nướng).', '', 'Đi bộ hoặc di chuyển bằng taxi/xe máy đến các nhà hàng/quán ăn địa phương.', 2),
(36, 7, NULL, 1, 'Chiều', 'Tìm hiểu sâu hơn về cà phê tại Bảo tàng Cà phê Thế giới hoặc một nông trại cà phê gần trung tâm thành phố.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi trong TP Buôn Ma Thuột.', 3),
(37, 7, NULL, 1, 'Tối', 'Khám phá chợ đêm Buôn Ma Thuột và thưởng thức ẩm thực đường phố.', '', 'Đi bộ hoặc xe máy/taxi trong TP Buôn Ma Thuột.', 4),
(38, 7, NULL, 2, 'Sáng sớm', 'Trekking và khám phá Thác Dray Nur, một trong những thác nước đẹp nhất Tây Nguyên.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~30km) từ trung tâm Buôn Ma Thuột.', 5),
(39, 7, NULL, 2, 'Trưa', 'Ăn trưa dã ngoại hoặc tại nhà hàng địa phương gần thác Dray Nur.', '', 'Di chuyển gần khu vực thác.', 6),
(40, 7, NULL, 2, 'Chiều', 'Tiếp tục trekking và khám phá Thác Dray Sáp, chiêm ngưỡng \'nước khói\' huyền ảo.', 'Huyện Krông Ana, Đắk Lắk', 'Thác Dray Sáp và Dray Nur nằm gần nhau, có thể đi bộ qua cầu hoặc di chuyển bằng xe máy/ô tô một đoạn ngắn.', 7),
(41, 7, NULL, 2, 'Hoàng hôn', 'Ngắm hoàng hôn tại khu vực thác nước hoặc trên đường về Buôn Ma Thuột.', '', 'Trên đường về trung tâm thành phố.', 8),
(42, 7, NULL, 2, 'Tối', 'Ăn tối tại Buôn Ma Thuột và nghỉ ngơi.', '', 'Di chuyển bằng taxi/xe máy.', 9),
(43, 7, NULL, 3, 'Sáng sớm', 'Khám phá Vườn quốc gia Yok Đôn, trekking rừng và tìm hiểu về voi rừng.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1.5 giờ (~40km) từ Buôn Ma Thuột.', 10),
(44, 7, NULL, 3, 'Trưa', 'Ăn trưa với các món ăn đặc sản tại Buôn Đôn.', '', 'Di chuyển từ Vườn quốc gia Yok Đôn đến các nhà hàng ở Buôn Đôn.', 11),
(45, 7, NULL, 3, 'Chiều', 'Tham quan Buôn Đôn, tìm hiểu về văn hóa săn bắt và thuần dưỡng voi, khám phá cầu treo.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển trong khu vực Buôn Đôn.', 12),
(46, 7, NULL, 3, 'Hoàng hôn', 'Ngắm cảnh hoàng hôn tại Buôn Đôn hoặc trên đường về Buôn Ma Thuột.', '', 'Trên đường về trung tâm thành phố.', 13),
(47, 7, NULL, 3, 'Tối', 'Thưởng thức bữa tối đặc sản tại Buôn Ma Thuột, thư giãn.', '', 'Di chuyển bằng taxi/xe máy.', 14),
(48, 7, NULL, 4, 'Sáng sớm', 'Di chuyển đến Hồ Lắk, ngắm bình minh trên hồ và trải nghiệm chèo thuyền độc mộc (nếu có).', 'Huyện Lắk, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1.5 - 2 giờ (~50km) từ Buôn Ma Thuột.', 15),
(49, 7, NULL, 4, 'Sáng', 'Tham quan các buôn làng M\'nông quanh Hồ Lắk, tìm hiểu văn hóa địa phương.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc xe máy trong khu vực quanh Hồ Lắk.', 16),
(50, 7, NULL, 4, 'Trưa', 'Ăn trưa tại nhà hàng ven Hồ Lắk, thưởng thức các món ăn từ cá nước ngọt.', '', 'Di chuyển đến các nhà hàng ven hồ.', 17),
(51, 7, NULL, 4, 'Chiều', 'Thư giãn hoặc cắm trại tại Hồ Ea Kao (nếu có thời gian và chuẩn bị trước).', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Từ Hồ Lắk, di chuyển về TP Buôn Ma Thuột, sau đó đi thêm khoảng 30 phút (~12km) đến Hồ Ea Kao.', 18),
(52, 7, NULL, 4, 'Hoàng hôn', 'Ngắm hoàng hôn tại Hồ Ea Kao hoặc tại một điểm cao ở Buôn Ma Thuột.', '', 'Tại khu vực hồ hoặc trên đường về trung tâm.', 19),
(53, 7, NULL, 4, 'Tối', 'Ăn tối chia tay Đắk Lắk với các món đặc sản.', '', 'Di chuyển bằng taxi/xe máy trong TP Buôn Ma Thuột.', 20),
(54, 8, NULL, 1, 'Sáng', 'Bắt đầu ngày mới tại trung tâm Buôn Ma Thuột bằng việc khám phá văn hóa cà phê. Tham quan Bảo tàng Cà phê và thưởng thức một ly cà phê đậm đà tại một quán địa phương.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc di chuyển bằng taxi/xe máy trong trung tâm thành phố.', 0),
(55, 8, NULL, 1, 'Trưa', 'Thưởng thức ẩm thực đặc sản Tây Nguyên tại nhà hàng địa phương, thử các món như gà nướng Bản Đôn, cơm lam, lẩu lá rừng.', '', 'Đi bộ hoặc taxi/xe máy.', 1),
(56, 8, NULL, 1, 'Chiều', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê cổ truyền đẹp nhất Buôn Ma Thuột. Tìm hiểu về kiến trúc nhà dài truyền thống và văn hóa bản địa.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.', 2),
(57, 8, NULL, 1, 'Tối', 'Dạo chợ đêm Buôn Ma Thuột, thưởng thức các món ăn vặt đường phố và mua sắm đặc sản địa phương.', '', 'Đi bộ hoặc taxi/xe máy.', 3),
(58, 8, NULL, 2, 'Sáng', 'Khởi hành đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Tại đây, bạn có thể trải nghiệm đi thuyền độc mộc trên hồ, tìm hiểu về văn hóa M\'nông và ngắm cảnh thiên nhiên hùng vĩ.', 'Huyện Lắk, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~50km) theo quốc lộ 27 từ Buôn Ma Thuột.', 4),
(59, 8, NULL, 2, 'Trưa', 'Ăn trưa tại một nhà hàng địa phương gần Hồ Lắk, thưởng thức các món ăn dân dã của đồng bào M\'nông.', '', 'Đi bộ hoặc xe máy trong khu vực Hồ Lắk.', 5),
(60, 8, NULL, 2, 'Chiều', 'Tham quan buôn làng quanh Hồ Lắk, tìm hiểu thêm về đời sống và phong tục của người M\'nông. Mua sắm các sản phẩm thủ công mỹ nghệ làm quà lưu niệm.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc xe máy quanh khu vực Hồ Lắk.', 6),
(61, 8, NULL, 2, 'Tối', 'Trở về Buôn Ma Thuột. Thưởng thức bữa tối chia tay tại một nhà hàng với các món ăn đặc trưng của Đắk Lắk.', '', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~50km) về Buôn Ma Thuột.', 7),
(62, 9, NULL, 1, 'Sáng', 'Thưởng thức cà phê Buôn Ma Thuột tại một quán cà phê nổi tiếng và khám phá Bảo tàng Thế giới Cà phê.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 0),
(63, 9, NULL, 1, 'Trưa', 'Thưởng thức các món ăn đặc sản địa phương tại nhà hàng trong trung tâm Buôn Ma Thuột.', '', 'Đi bộ hoặc taxi/xe máy quãng ngắn.', 1),
(64, 9, NULL, 1, 'Chiều', 'Tham quan Buôn Akô Dhông, tìm hiểu văn hóa nhà dài của người Ê Đê và chụp ảnh.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi xe máy hoặc taxi khoảng 10-15 phút từ trung tâm thành phố.', 2),
(65, 9, NULL, 1, 'Tối', 'Dạo chợ đêm Buôn Ma Thuột, thưởng thức ẩm thực đường phố và mua sắm đặc sản.', '', 'Đi bộ hoặc taxi/xe máy quãng ngắn.', 3),
(66, 9, NULL, 2, 'Sáng', 'Khám phá Thác Dray Nur, một trong những thác nước đẹp nhất Tây Nguyên. Tận hưởng không gian thiên nhiên hùng vĩ và chụp ảnh.', 'Huyện Krông Ana, Đắk Lắk', 'Thuê xe máy hoặc taxi/ô tô tự lái khoảng 45 phút - 1 giờ (~30km) từ Buôn Ma Thuột theo quốc lộ 14 và đường tỉnh 682.', 4),
(67, 9, NULL, 2, 'Trưa', 'Ăn trưa tại các nhà hàng gần khu vực thác, thưởng thức đặc sản địa phương.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 5),
(68, 9, NULL, 2, 'Chiều', 'Tiếp tục tham quan Thác Dray Sáp, chiêm ngưỡng vẻ đẹp của thác \'nước khói\'.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 5-10 phút từ Thác Dray Nur.', 6),
(69, 9, NULL, 2, 'Tối', 'Quay về Buôn Ma Thuột, ăn tối và nghỉ ngơi.', '', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 45 phút - 1 giờ về Buôn Ma Thuột.', 7),
(70, 9, NULL, 3, 'Sáng', 'Tham quan Buôn Đôn, khám phá làng văn hóa voi, cầu treo và nhà dài truyền thống.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi/ô tô tự lái khoảng 1 giờ (~45km) từ Buôn Ma Thuột.', 8),
(71, 9, NULL, 3, 'Trưa', 'Thưởng thức ẩm thực đặc trưng tại Buôn Đôn, đặc biệt là các món ăn từ thịt rừng (nếu có và hợp pháp) hoặc cơm lam, gà nướng.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 9),
(72, 9, NULL, 3, 'Chiều', 'Tham quan Vườn quốc gia Yok Đôn, trải nghiệm đi bộ trong rừng hoặc tham gia các hoạt động sinh thái (lưu ý không khuyến khích cưỡi voi).', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 15-20 phút từ trung tâm Buôn Đôn.', 10),
(73, 9, NULL, 3, 'Tối', 'Quay về Buôn Ma Thuột, ăn tối và tự do khám phá.', '', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 1 giờ về Buôn Ma Thuột.', 11),
(74, 9, NULL, 4, 'Sáng', 'Di chuyển đến Hồ Lắk, tham quan hồ nước ngọt lớn thứ hai Việt Nam và tìm hiểu văn hóa M\'nông.', 'Huyện Lắk, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1.5 - 2 giờ (~55km) theo quốc lộ 27 từ Buôn Ma Thuột.', 12),
(75, 9, NULL, 4, 'Trưa', 'Ăn trưa tại các nhà hàng ven Hồ Lắk, thưởng thức cá nước ngọt hoặc các món ăn địa phương.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 13),
(76, 9, NULL, 4, 'Chiều', 'Trải nghiệm đi thuyền độc mộc trên Hồ Lắk, ngắm cảnh và chụp ảnh hoàng hôn.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc xe máy quãng ngắn quanh khu vực hồ.', 14),
(77, 9, NULL, 4, 'Tối', 'Tham gia giao lưu văn hóa cồng chiêng (nếu có tổ chức) hoặc thưởng thức bữa tối tại resort/nhà nghỉ ven hồ.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 15),
(78, 9, NULL, 5, 'Sáng', 'Thư giãn tại Hồ Ea Kao, tận hưởng không khí trong lành, có thể cắm trại (nếu muốn) hoặc đi dạo ven hồ.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 20-30 phút (~12km) từ trung tâm Buôn Ma Thuột.', 16),
(79, 9, NULL, 5, 'Trưa', 'Ăn trưa tại một nhà hàng có view đẹp hoặc các quán ăn dân dã gần Hồ Ea Kao.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 17),
(80, 9, NULL, 5, 'Chiều', 'Mua sắm đặc sản Đắk Lắk như cà phê, hồ tiêu, mật ong, thổ cẩm tại các chợ hoặc cửa hàng đặc sản.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 18),
(81, 9, NULL, 5, 'Tối', 'Bữa tối chia tay tại một nhà hàng đặc sắc ở Buôn Ma Thuột và chuẩn bị khởi hành.', '', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 19),
(82, 10, NULL, 1, 'Sáng', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê lâu đời và đẹp nhất tại Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa địa phương.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy khoảng 15 phút (~5km) từ trung tâm thành phố.', 0),
(83, 10, NULL, 1, 'Trưa', 'Thưởng thức các món đặc sản địa phương tại một nhà hàng gần trung tâm Buôn Ma Thuột. Gợi ý: Bún đỏ, phở khô, hoặc lẩu rau rừng.', '', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 1),
(84, 10, NULL, 1, 'Chiều', 'Trải nghiệm văn hóa Cà phê Buôn Ma Thuột. Tham quan bảo tàng cà phê hoặc một quán cà phê vườn nổi tiếng để thưởng thức hương vị cà phê Ban Mê chính hiệu.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 2),
(85, 10, NULL, 1, 'Tối', 'Dạo chợ đêm Buôn Ma Thuột, khám phá ẩm thực đường phố và mua sắm đặc sản địa phương.', '', 'Đi bộ hoặc di chuyển bằng taxi/xe máy nếu ở xa chợ đêm.', 3),
(86, 10, NULL, 2, 'Sáng', 'Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Trải nghiệm đi thuyền độc mộc trên hồ, tìm hiểu văn hóa của người M\'nông bản địa.', 'Huyện Lắk, Đắk Lắk', 'Nên thuê xe máy hoặc taxi đi khoảng 1 giờ 30 phút (~50km) theo quốc lộ 27 từ Buôn Ma Thuột.', 4),
(87, 10, NULL, 2, 'Trưa', 'Thưởng thức bữa trưa với các món ăn đặc sản vùng Hồ Lắk như cá lăng, gà nướng bản địa tại các nhà hàng ven hồ.', '', 'Đi bộ hoặc xe máy gần khu vực Hồ Lắk.', 5),
(88, 10, NULL, 2, 'Chiều', 'Tham quan Buôn Đôn, làng văn hóa nổi tiếng với nghề săn bắt và thuần dưỡng voi. Tìm hiểu nhà dài truyền thống và cầu treo độc đáo.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~45km) từ Hồ Lắk. Từ Buôn Ma Thuột đi Buôn Đôn khoảng 40 phút (~30km).', 6),
(89, 10, NULL, 2, 'Tối', 'Quay về Buôn Ma Thuột, thưởng thức bữa tối và mua sắm quà lưu niệm trước khi kết thúc chuyến đi.', '', 'Di chuyển bằng xe máy hoặc taxi/ô tô khoảng 40 phút (~30km) từ Buôn Đôn về Buôn Ma Thuột.', 7),
(90, 11, NULL, 1, 'Sáng sớm', 'Thưởng thức cà phê Ban Mê tại TP. Buôn Ma Thuột', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy/taxi trong trung tâm thành phố.', 0),
(91, 11, NULL, 1, 'Sáng', 'Tham quan Làng Cà phê Buôn Ma Thuột để tìm hiểu về quy trình sản xuất cà phê và văn hóa cà phê bản địa.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc di chuyển bằng xe máy/taxi trong trung tâm TP. Buôn Ma Thuột.', 1),
(92, 11, NULL, 1, 'Trưa', 'Ăn trưa với các món đặc sản địa phương như bún đỏ, nem nướng tại TP. Buôn Ma Thuột.', '', 'Đi bộ hoặc di chuyển bằng xe máy/taxi trong TP. Buôn Ma Thuột.', 2),
(93, 11, NULL, 1, 'Chiều', 'Khám phá Buôn Ako Dhong, ngôi làng Ê Đê cổ kính ngay giữa lòng thành phố, tìm hiểu về kiến trúc nhà dài và đời sống văn hóa của người dân tộc Ê Đê.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc di chuyển bằng xe máy/taxi khoảng 10-15 phút từ trung tâm TP. Buôn Ma Thuột.', 3),
(94, 11, NULL, 1, 'Hoàng hôn', 'Ngắm hoàng hôn lãng mạn tại Hồ Ea Kao. Du khách có thể đi dạo, cắm trại hoặc thưởng thức đồ uống tại các quán ven hồ.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 20-30 phút (~12km) từ trung tâm TP. Buôn Ma Thuột.', 4),
(95, 11, NULL, 1, 'Tối', 'Thưởng thức ẩm thực đường phố tại chợ đêm Buôn Ma Thuột hoặc dùng bữa tại nhà hàng địa phương.', '', 'Đi bộ hoặc xe máy/taxi trong TP. Buôn Ma Thuột.', 5),
(96, 11, NULL, 2, 'Sáng sớm', 'Di chuyển đến Hồ Lắk để đón bình minh và trải nghiệm không khí trong lành của vùng hồ. Ngắm nhìn cảnh quan thiên nhiên và các hoạt động của người dân địa phương vào buổi sáng.', 'Huyện Lắk, Đắk Lắk', 'Nên thuê xe máy hoặc taxi đi khoảng 1 giờ 30 phút (~55km) theo quốc lộ 27 từ TP. Buôn Ma Thuột. Nên khởi hành sớm để kịp đón bình minh.', 6),
(97, 11, NULL, 2, 'Sáng', 'Trải nghiệm văn hóa M\'nông tại Hồ Lắk. Có thể tham gia chèo thuyền độc mộc trên hồ hoặc khám phá các buôn làng xung quanh để tìm hiểu về đời sống và phong tục tập quán của người M\'nông.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ quanh hồ hoặc sử dụng các dịch vụ thuyền độc mộc tại chỗ.', 7),
(98, 11, NULL, 2, 'Trưa', 'Ăn trưa tại nhà hàng địa phương ven Hồ Lắk, thưởng thức các món ăn đặc sản của vùng như cá nướng, cơm lam.', '', 'Đi bộ hoặc di chuyển bằng xe máy/taxi ngắn.', 8),
(99, 11, NULL, 2, 'Chiều', 'Trải nghiệm cuộc sống của người dân địa phương tại Huyện Buôn Đôn, tham quan cầu treo và nhà dài truyền thống.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 1 giờ 30 phút (~70km) từ Hồ Lắk. Hoặc quay về TP. Buôn Ma Thuột và di chuyển từ đó.', 9),
(100, 11, NULL, 2, 'Hoàng hôn', 'Ngắm hoàng hôn tại Dray Nur Waterfall - một trong những thác nước hùng vĩ nhất Tây Nguyên. Cảnh quan hùng vĩ và không khí trong lành sẽ mang lại trải nghiệm đáng nhớ.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 1 giờ (~40km) từ Buôn Đôn hoặc 30 phút (~25km) từ TP. Buôn Ma Thuột.', 10),
(101, 11, NULL, 2, 'Tối', 'Quay về TP. Buôn Ma Thuột, thưởng thức bữa tối cuối cùng với các món ăn Tây Nguyên và mua sắm đặc sản làm quà.', '', 'Di chuyển bằng xe máy/ô tô tự lái hoặc taxi về TP. Buôn Ma Thuột.', 11),
(102, 12, NULL, 1, 'Sáng', 'Bắt đầu hành trình với trải nghiệm không gian cà phê tại thủ phủ cà phê Buôn Ma Thuột. Thưởng thức hương vị cà phê địa phương và tìm hiểu về quy trình chế biến tại một quán cà phê nổi tiếng.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy đến trung tâm thành phố.', 0),
(103, 12, NULL, 1, 'Trưa', 'Ăn trưa với các món đặc sản địa phương như bún đỏ, nem nướng hoặc bánh ướt thịt nướng tại các nhà hàng quanh khu vực trung tâm thành phố.', 'TP. Buôn Ma Thuột, Đắk Lán', 'Đi bộ hoặc di chuyển bằng xe máy/taxi trong thành phố.', 1),
(104, 12, NULL, 1, 'Chiều', 'Tham quan Buôn Ako Dhong, một ngôi làng Ê Đê yên bình ngay giữa lòng thành phố. Tìm hiểu về kiến trúc nhà dài truyền thống và văn hóa bản địa.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.', 2),
(105, 12, NULL, 1, 'Tối', 'Dạo chợ đêm Buôn Ma Thuột, khám phá ẩm thực đường phố và mua sắm các sản phẩm thủ công, đặc sản địa phương làm quà. Thưởng thức bữa tối tại chợ.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc xe máy/taxi trong thành phố.', 3),
(106, 12, NULL, 2, 'Sáng', 'Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Tận hưởng không khí trong lành, ngắm cảnh bình minh trên hồ và tìm hiểu về văn hóa M\'nông địa phương.', 'Huyện Lắk, Đắk Lắk', 'Nên thuê xe máy hoặc taxi đi khoảng 1 giờ 30 phút (~55km) theo quốc lộ 27 từ Buôn Ma Thuột.', 4),
(107, 12, NULL, 2, 'Trưa', 'Thưởng thức bữa trưa với các món ăn đặc sản địa phương tại nhà hàng ven hồ Lắk, như cá lăng nướng, cơm lam, hoặc gà nướng.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc di chuyển bằng xe máy gần khu vực hồ.', 5),
(108, 12, NULL, 2, 'Chiều', 'Trải nghiệm đi thuyền độc mộc trên Hồ Lắk, khám phá cuộc sống của người dân M\'nông và ngắm cảnh hoàng hôn tuyệt đẹp trên hồ.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc di chuyển bằng xe máy/taxi gần khu vực hồ.', 6),
(109, 12, NULL, 2, 'Tối', 'Thưởng thức bữa tối và nghỉ ngơi tại các homestay hoặc nhà nghỉ gần Hồ Lắk để trải nghiệm không gian văn hóa bản địa.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc xe máy/taxi trong khu vực Hồ Lắk.', 7),
(110, 12, NULL, 3, 'Sáng', 'Khám phá Buôn Đôn, nổi tiếng với truyền thống săn bắt và thuần dưỡng voi. Tham quan những ngôi nhà dài truyền thống và tìm hiểu về văn hóa của người M\'nông.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 1 giờ (~45km) từ Buôn Ma Thuột.', 8),
(111, 12, NULL, 3, 'Trưa', 'Ăn trưa tại nhà hàng địa phương ở Buôn Đôn với các món đặc sản như gà nướng, cá suối nướng hoặc lẩu cá lăng.', 'Huyện Buôn Đôn, Đắk Lắk', 'Đi bộ hoặc xe máy/taxi trong khu vực Buôn Đôn.', 9),
(112, 12, NULL, 3, 'Chiều', 'Trải nghiệm đi cầu treo bắc qua sông Serepok. Nếu có điều kiện, có thể trải nghiệm cho voi ăn hoặc tham gia các hoạt động thân thiện với voi (lưu ý tìm hiểu kỹ về các hoạt động bảo vệ voi).', 'Huyện Buôn Đôn, Đắk Lắk', 'Đi bộ tham quan các điểm trong Buôn Đôn.', 10),
(113, 12, NULL, 3, 'Tối', 'Quay về Buôn Ma Thuột, thưởng thức bữa tối tại một nhà hàng có món ăn Tây Nguyên và thư giãn tại một quán cà phê acoustic.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 1 giờ (~45km) về Buôn Ma Thuột.', 11),
(114, 12, NULL, 4, 'Sáng', 'Tham quan chợ Buôn Ma Thuột vào buổi sáng để cảm nhận nhịp sống địa phương, mua sắm các sản vật và đặc sản tươi sống về làm quà.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc xe máy/taxi trong thành phố.', 12),
(115, 12, NULL, 4, 'Trưa', 'Ăn trưa với các món ăn vặt đặc trưng của Buôn Ma Thuột hoặc chọn một quán ăn truyền thống để thưởng thức ẩm thực lần cuối trước khi rời đi.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc xe máy/taxi trong thành phố.', 13),
(116, 12, NULL, 4, 'Chiều', 'Thư giãn tại Hồ Ea Kao, một hồ nước yên bình với phong cảnh hữu tình. Có thể đi dạo quanh hồ, chụp ảnh hoặc đơn giản là tận hưởng không khí trong lành trước khi ra sân bay.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 20-30 phút (~12km) từ trung tâm thành phố.', 14),
(117, 12, NULL, 4, 'Tối', 'Di chuyển ra sân bay Buôn Ma Thuột hoặc bến xe để kết thúc chuyến đi.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe buýt sân bay.', 15),
(118, 13, NULL, 1, 'Sáng', 'Tìm hiểu văn hóa cà phê Buôn Ma Thuột tại các quán cà phê nổi tiếng và ghé thăm Bảo tàng Cà phê.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Thuê xe máy hoặc taxi để di chuyển trong trung tâm thành phố.', 0),
(119, 13, NULL, 1, 'Trưa', 'Thưởng thức các món ăn đặc sản Đắk Lắk như bún đỏ, nem nướng...', '', 'Đi bộ hoặc xe máy đến các quán ăn địa phương.', 1),
(120, 13, NULL, 1, 'Chiều', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê cổ truyền với những ngôi nhà dài truyền thống.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 15 phút từ trung tâm TP. Buôn Ma Thuột.', 2),
(121, 13, NULL, 1, 'Tối', 'Tự do khám phá ẩm thực đường phố Buôn Ma Thuột hoặc thưởng thức không khí cà phê đêm.', '', 'Đi bộ hoặc xe máy.', 3),
(122, 13, NULL, 2, 'Sáng', 'Di chuyển đến Thác Dray Nur và bắt đầu hành trình trekking khám phá vẻ đẹp hoang sơ của thác nước hùng vĩ này.', 'Huyện Krông Ana, Đắk Lắk', 'Nên thuê xe máy hoặc ô tô tự lái/taxi khoảng 45 phút (~30km) từ Buôn Ma Thuột theo quốc lộ 14.', 4),
(123, 13, NULL, 2, 'Trưa', 'Ăn trưa tại nhà hàng địa phương gần thác Dray Nur, thưởng thức các món ăn dân dã.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 5),
(124, 13, NULL, 2, 'Chiều', 'Tiếp tục tham quan Thác Dray Sáp, chiêm ngưỡng dòng thác \'nước khói\' độc đáo.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 5-10 phút từ Thác Dray Nur (hai thác khá gần nhau).', 6),
(125, 13, NULL, 2, 'Tối', 'Quay về Buôn Ma Thuột, nghỉ ngơi và ăn tối.', '', 'Xe máy/ô tô tự lái/taxi khoảng 45 phút (~30km) về Buôn Ma Thuột.', 7),
(126, 13, NULL, 3, 'Sáng', 'Tham quan Buôn Đôn, tìm hiểu văn hóa săn bắt và thuần dưỡng voi, trải nghiệm cầu treo Buôn Đôn.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~45km) từ TP. Buôn Ma Thuột.', 8),
(127, 13, NULL, 3, 'Trưa', 'Thưởng thức các món ăn đặc sản Buôn Đôn như cơm lam, gà nướng, cá lăng sông Sêrêpôk.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 9),
(128, 13, NULL, 3, 'Chiều', 'Khám phá Vườn quốc gia Yok Đôn, vườn quốc gia lớn nhất Việt Nam, nơi sinh sống của voi rừng. Có thể lựa chọn các tour trekking trong rừng ngắn hoặc đạp xe.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 15 phút từ Buôn Đôn.', 10),
(129, 13, NULL, 3, 'Tối', 'Quay về Buôn Ma Thuột, nghỉ ngơi và thưởng thức ẩm thực địa phương.', '', 'Xe máy/ô tô tự lái/taxi khoảng 1 giờ (~45km) về Buôn Ma Thuột.', 11),
(130, 13, NULL, 4, 'Sáng', 'Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, khám phá văn hóa M\'nông bản địa.', 'Huyện Lắk, Đắk Lắk', 'Nên thuê xe máy hoặc ô tô tự lái/taxi khoảng 1.5 giờ (~50km) từ Buôn Ma Thuột theo quốc lộ 27.', 12),
(131, 13, NULL, 4, 'Trưa', 'Ăn trưa tại nhà hàng ven hồ Lắk, thưởng thức đặc sản cá nước ngọt và ẩm thực địa phương.', '', 'Đi bộ hoặc xe máy quãng ngắn.', 13),
(132, 13, NULL, 4, 'Chiều', 'Trải nghiệm chèo thuyền độc mộc trên Hồ Lắk, ngắm cảnh hoàng hôn trên hồ.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ quanh khu vực hồ.', 14),
(133, 13, NULL, 4, 'Tối', 'Trải nghiệm văn hóa cồng chiêng và thưởng thức rượu cần (nếu có đoàn biểu diễn hoặc đặt trước). Nghỉ đêm tại Hồ Lắk hoặc quay về Buôn Ma Thuột.', '', 'Đi bộ.', 15),
(134, 13, NULL, 5, 'Sáng', 'Tham quan Hồ Ea Kao, hồ nước rộng lớn gần trung tâm thành phố, thích hợp để tản bộ, ngắm cảnh hoặc cắm trại nhẹ (nếu muốn).', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 20-30 phút (~12km) từ trung tâm TP. Buôn Ma Thuột.', 16),
(135, 13, NULL, 5, 'Trưa', 'Ăn trưa tại các nhà hàng ven Hồ Ea Kao hoặc quay về trung tâm Buôn Ma Thuột.', '', 'Xe máy/taxi.', 17),
(136, 13, NULL, 5, 'Chiều', 'Mua sắm đặc sản Đắk Lắk làm quà như cà phê, mật ong, tiêu, thổ cẩm tại chợ Buôn Ma Thuột hoặc các cửa hàng đặc sản.', '', 'Đi bộ hoặc xe máy trong trung tâm thành phố.', 18),
(137, 13, NULL, 5, 'Tối', 'Ăn tối chia tay Đắk Lắk và chuẩn bị khởi hành.', '', 'Xe máy/taxi.', 19),
(138, 14, NULL, 1, 'Sáng', 'Khám phá Buôn Akô Dhông, buôn làng Ê Đê lâu đời và đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa địa phương.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Từ trung tâm Buôn Ma Thuột, bạn có thể đi taxi hoặc xe máy khoảng 10-15 phút (~3km).', 0),
(139, 14, NULL, 1, 'Trưa', 'Thưởng thức ẩm thực địa phương tại các nhà hàng ở trung tâm Buôn Ma Thuột. Gợi ý các món đặc sản như bún đỏ, lẩu lá rừng.', '', 'Di chuyển bằng xe máy hoặc taxi trong khu vực trung tâm thành phố.', 1),
(140, 14, NULL, 1, 'Chiều', 'Tham quan khu vực Cà phê Buôn Ma Thuột, tìm hiểu quy trình trồng và chế biến cà phê, thưởng thức những ly cà phê đậm đà tại thủ phủ cà phê Việt Nam.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi từ trung tâm thành phố, khoảng 15-20 phút.', 2),
(141, 14, NULL, 1, 'Tối', 'Dạo quanh chợ đêm Buôn Ma Thuột, mua sắm quà lưu niệm và thưởng thức các món ăn vặt đường phố.', '', 'Đi bộ hoặc xe máy/taxi trong khu vực trung tâm thành phố.', 3),
(142, 14, NULL, 2, 'Sáng', 'Bắt đầu hành trình trekking tại Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Khám phá vẻ đẹp hoang sơ và tận hưởng không khí trong lành.', 'Huyện Krông Ana, Đắk Lắk', 'Thuê xe máy hoặc taxi từ trung tâm Buôn Ma Thuột, đi khoảng 45 phút (~30km) theo quốc lộ 14 và đường tỉnh 684.', 4),
(143, 14, NULL, 2, 'Trưa', 'Ăn trưa gần khu vực thác Dray Nur, có thể là các quán ăn địa phương hoặc chuẩn bị đồ ăn nhẹ mang theo để picnic.', '', 'Đi bộ hoặc xe máy trong khu vực quanh thác.', 5),
(144, 14, NULL, 2, 'Chiều', 'Tiếp tục khám phá Thác Dray Sáp, thác \'nước khói\' nổi tiếng nằm cách Dray Nur không xa, với những trải nghiệm trekking và ngắm cảnh khác biệt.', 'Huyện Krông Ana, Đắk Lắk', 'Từ Thác Dray Nur, bạn có thể đi bộ qua cầu treo hoặc di chuyển bằng xe máy khoảng 5-10 phút để đến Thác Dray Sáp.', 6),
(145, 14, NULL, 2, 'Tối', 'Trở về Buôn Ma Thuột, dùng bữa tối và nghỉ ngơi, chuẩn bị cho chuyến đi về.', '', 'Di chuyển bằng xe máy hoặc taxi từ Thác Dray Sáp về trung tâm Buôn Ma Thuột khoảng 45 phút (~30km).', 7),
(146, 15, NULL, 1, 'Sáng', 'Khám phá Buôn Akô Dhông - buôn làng Ê Đê lâu đời và đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống, giao lưu với người dân bản địa và nghe kể chuyện về văn hóa Ê Đê.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Từ trung tâm thành phố Buôn Ma Thuột, bạn có thể đi taxi hoặc xe máy khoảng 10-15 phút (~5km).', 0),
(147, 15, NULL, 1, 'Trưa', 'Thưởng thức ẩm thực địa phương tại một nhà hàng gần trung tâm Buôn Ma Thuột, với các món ăn mang đậm hương vị Tây Nguyên.', '', 'Di chuyển bằng xe máy hoặc taxi về trung tâm thành phố.', 1),
(148, 15, NULL, 1, 'Chiều', 'Tham quan và trải nghiệm văn hóa cà phê Buôn Ma Thuột. Ghé thăm các quán cà phê rang xay thủ công, tìm hiểu quy trình chế biến cà phê và thưởng thức những ly cà phê nguyên chất.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc xe máy/taxi tham quan các quán cà phê trong trung tâm thành phố.', 2),
(149, 15, NULL, 1, 'Tối', 'Tự do khám phá Buôn Ma Thuột về đêm, thưởng thức các món ăn vặt đường phố hoặc ghé một quán cà phê acoustic để thư giãn.', '', 'Đi bộ hoặc xe máy/taxi.', 3),
(150, 15, NULL, 2, 'Sáng', 'Di chuyển đến Buôn Đôn, tham quan Làng văn hoá Buôn Đôn, tìm hiểu về nghề săn bắt và thuần dưỡng voi truyền thống. Khám phá kiến trúc nhà dài độc đáo và cầu treo bắc qua sông Serepok.', 'Huyện Buôn Đôn, Đắk Lắk', 'Thuê xe máy hoặc taxi/ô tô tự lái từ Buôn Ma Thuột đi khoảng 1 giờ (~45km) theo tỉnh lộ 1.', 4),
(151, 15, NULL, 2, 'Trưa', 'Thưởng thức bữa trưa với các món ăn đặc sản của Buôn Đôn như cơm lam, gà nướng, cá lăng sông Serepok.', '', 'Ăn uống tại các nhà hàng trong khu vực Buôn Đôn.', 5),
(152, 15, NULL, 2, 'Chiều', 'Khám phá Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Trải nghiệm chèo thuyền độc mộc trên hồ và tìm hiểu văn hóa M\'nông, ngắm cảnh hoàng hôn tuyệt đẹp.', 'Huyện Lắk, Đắk Lắk', 'Từ Buôn Đôn, di chuyển bằng xe máy hoặc ô tô khoảng 1.5 - 2 giờ (~70km) về phía Nam theo quốc lộ 27. Hoặc từ Buôn Ma Thuột đi khoảng 1.5 giờ (~50km).', 6),
(153, 15, NULL, 2, 'Tối', 'Kết thúc chuyến đi, quay trở về Buôn Ma Thuột hoặc nghỉ đêm tại các nhà nghỉ/homestay gần Hồ Lắk để trải nghiệm không khí yên bình của vùng đất này.', '', 'Di chuyển bằng xe máy hoặc ô tô về Buôn Ma Thuột (~50km) hoặc tìm chỗ nghỉ tại Hồ Lắk.', 7),
(154, 16, NULL, 1, 'Sáng sớm', 'Bắt đầu ngày mới tại thủ phủ cà phê Buôn Ma Thuột. Thưởng thức một ly cà phê đậm đà tại một quán cà phê địa phương nổi tiếng. Có thể ghé thăm Bảo tàng Cà phê Thế giới để tìm hiểu sâu hơn về lịch sử và văn hóa cà phê.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.', 0),
(155, 16, NULL, 1, 'Sáng', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa bản địa.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc xe máy/taxi từ trung tâm thành phố (khoảng 10-15 phút).', 1),
(156, 16, NULL, 1, 'Trưa', 'Ăn trưa với các món đặc sản Tây Nguyên tại nhà hàng địa phương ở Buôn Ma Thuột.', '', 'Di chuyển bằng xe máy/taxi trong TP. Buôn Ma Thuột.', 2),
(157, 16, NULL, 1, 'Chiều', 'Khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Có thể tham gia trekking nhẹ xung quanh khu vực thác.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 45 phút (~30km) từ Buôn Ma Thuột theo quốc lộ 14 và đường nhánh.', 3),
(158, 16, NULL, 1, 'Hoàng hôn', 'Ngắm hoàng hôn tại Thác Dray Nur và sau đó quay về Buôn Ma Thuột.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi về lại TP. Buôn Ma Thuột.', 4),
(159, 16, NULL, 1, 'Tối', 'Ăn tối và tự do khám phá Buôn Ma Thuột về đêm.', '', 'Đi bộ hoặc xe máy/taxi trong TP. Buôn Ma Thuột.', 5),
(160, 16, NULL, 2, 'Sáng sớm', 'Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, để đón bình minh và trải nghiệm văn hóa M\'nông. Có thể đi thuyền độc mộc trên hồ hoặc tham quan buôn làng.', 'Huyện Lắk, Đắk Lắk', 'Nên thuê xe máy hoặc taxi đi khoảng 1.5 giờ (~50km) theo quốc lộ 27 từ Buôn Ma Thuột.', 6),
(161, 16, NULL, 2, 'Sáng', 'Khám phá Thác Dray Sáp, thác \'nước khói\' nổi tiếng. Du khách có thể đi bộ tham quan và tận hưởng không khí trong lành.', 'Huyện Krông Ana, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái từ Hồ Lắk khoảng 1 giờ (~40km) hoặc từ TP. Buôn Ma Thuột khoảng 45 phút (~30km).', 7),
(162, 16, NULL, 2, 'Trưa', 'Ăn trưa tại nhà hàng địa phương gần khu vực Thác Dray Sáp hoặc quay về Buôn Ma Thuột để thưởng thức ẩm thực.', '', 'Di chuyển bằng xe máy/ô tô.', 8),
(163, 16, NULL, 2, 'Chiều', 'Tham quan Vườn quốc gia Yok Đôn, vườn quốc gia lớn nhất Việt Nam. Trải nghiệm trekking trong rừng để khám phá hệ sinh thái đa dạng.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô khoảng 1 giờ (~40km) từ Buôn Ma Thuột. Từ Thác Dray Sáp đến Yok Đôn mất khoảng 1.5 - 2 giờ di chuyển.', 9),
(164, 16, NULL, 2, 'Hoàng hôn', 'Tận hưởng không khí yên bình của rừng núi Yok Đôn vào lúc hoàng hôn, sau đó di chuyển về Buôn Ma Thuột.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy hoặc ô tô về lại TP. Buôn Ma Thuột.', 10),
(165, 16, NULL, 2, 'Tối', 'Ăn tối chia tay và thư giãn tại Buôn Ma Thuột.', '', 'Đi bộ hoặc xe máy/taxi trong TP. Buôn Ma Thuột.', 11),
(166, 17, NULL, 1, 'Sáng', 'Bắt đầu hành trình khám phá văn hóa cà phê tại thủ phủ Buôn Ma Thuột. Tham quan một quán cà phê địa phương, tìm hiểu quy trình chế biến cà phê và thưởng thức hương vị đặc trưng. Gợi ý: Làng cà phê Trung Nguyên hoặc SOUL Roastery để có trải nghiệm sâu sắc.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Nên thuê xe máy (100.000 - 150.000 VNĐ/ngày) hoặc taxi để di chuyển trong thành phố.', 0),
(167, 17, NULL, 1, 'Trưa', 'Thưởng thức ẩm thực địa phương với món bún đỏ nổi tiếng Buôn Ma Thuột. Gợi ý: Bún đỏ cô Thu hoặc Thúy.', '', 'Di chuyển bằng xe máy hoặc đi bộ trong trung tâm thành phố.', 1),
(168, 17, NULL, 1, 'Chiều', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Khám phá kiến trúc nhà dài truyền thống và tìm hiểu về đời sống, văn hóa của người Ê Đê. Đây là một góc khuất yên bình ngay trong lòng thành phố.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.', 2),
(169, 17, NULL, 1, 'Tối', 'Thưởng thức đặc sản phở hai tô hoặc bánh ướt chồng dĩa 45. Sau đó, có thể dạo quanh quảng trường hoặc các quán cà phê acoustic.', '', 'Di chuyển bằng xe máy hoặc taxi.', 3),
(170, 17, NULL, 2, 'Sáng', 'Khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Du khách có thể trekking xung quanh thác để cảm nhận trọn vẹn vẻ đẹp hoang sơ. Sau đó di chuyển đến Thác Dray Sáp, thác \'nước khói\' nổi tiếng gần đó để có một trải nghiệm thác nước đa dạng hơn.', 'Huyện Krông Ana, Đắk Lắk', 'Nên thuê xe máy hoặc taxi di chuyển khoảng 45 phút (~30km) từ Buôn Ma Thuột theo quốc lộ 14 và quốc lộ 27. Sau đó có thể đi bộ giữa 2 thác.', 4),
(171, 17, NULL, 2, 'Trưa', 'Ăn trưa với món gà nướng - cơm lam đặc trưng của vùng Tây Nguyên tại khu vực gần thác hoặc trên đường đến Buôn Đôn.', '', 'Di chuyển bằng xe máy hoặc ô tô.', 5),
(172, 17, NULL, 2, 'Chiều', 'Tham quan Buôn Đôn, làng văn hoá nổi tiếng với nghề săn bắt và thuần dưỡng voi. Khám phá cầu treo dài bắt qua sông Sêrêpôk và tìm hiểu về nhà dài truyền thống. Đây là một trải nghiệm văn hóa độc đáo, ít người biết về lịch sử voi rừng.', 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 1 giờ (~45km) từ khu vực thác Dray Nur/Dray Sáp.', 6),
(173, 17, NULL, 2, 'Tối', 'Trở về Buôn Ma Thuột. Mua sắm đặc sản địa phương như cà phê, thịt nai khô, mật ong. Sau đó dùng bữa tối và chuẩn bị kết thúc chuyến đi.', '', 'Di chuyển bằng xe máy/ô tô tự lái khoảng 45 phút (~30km) về Buôn Ma Thuột.', 7),
(174, 18, NULL, 1, 'Sáng', 'Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại bảo tàng cà phê và các quán cà phê nổi tiếng.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Thuê xe máy hoặc taxi/Grab để di chuyển trong thành phố.', 0),
(175, 18, NULL, 1, 'Trưa', 'Ăn trưa với đặc sản địa phương.', '', 'Đi bộ hoặc thuê xe máy.', 1),
(176, 18, NULL, 1, 'Chiều', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê truyền thống giữa lòng thành phố.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Thuê xe máy hoặc taxi/Grab, di chuyển khoảng 15 phút từ trung tâm.', 2),
